window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch03"]={"id":"ch03","title":"第三章(一) 内膜系统","sub":"翟中和《细胞生物学》第4版 · 教师课件逐页详解","sub2":"内质网 · 蛋白质分选 · 高尔基体 · 溶酶体","modules":[{"i":0,"name":"模块一：真核细胞分室化与内质网","slides":[{"i":0,"sec":"第一节 分室化","title":"第三章 内膜系统与蛋白质分选 (p1)","notes":"第三章 内膜系统与蛋白质分选、膜泡运输。一、真核细胞内的膜被细胞器及其功能:分室化；二、蛋白质的分选(protein sorting)及定向转运——膜泡运输、跨膜运输、核孔运输。","page":1,"level":"掌握","img":"assets/img/ch03/p001.jpg","anim":null,"fig":null,"points":["内膜系统：真核细胞内膜被细胞器→分室化","蛋白质分选与定向转运三条途径：膜泡运输、跨膜运输、核孔运输"],"check":{"q":"本章所述蛋白质定向转运的方式包括？","o":["A. 自由扩散、协助扩散、主动运输","B. 膜泡运输、跨膜运输、核孔运输","C. 复制、转录、翻译","D. 有丝分裂、减数分裂、无丝分裂"],"a":"B","e":"蛋白质分选与定向转运通过膜泡运输、跨膜运输和核孔运输三种方式实现。","oe":["错：属小分子跨膜运输方式，不符合本页所学概念","对：与笔记三种定向转运方式一致","错：属遗传信息流过程，不符合本页所学概念","错：三者属于细胞分裂的方式，不符合本页所学概念"],"basis":"膜泡运输、跨膜运输、核孔运输"},"cards":[{"front":"内膜系统与蛋白质分选的核心内容有哪些？","back":"膜被细胞器与分室化；蛋白质分选及定向转运：膜泡运输、跨膜运输、核孔运输","mnemonic":"分室—分选—三运输","type":"组成数字","useImg":false,"blank":"膜泡运输","blank2":"跨膜运输"}],"mem":"分室—分选—三运输","big":"assets/img/ch03/big/p001.jpg","terms":[{"t":"蛋白质分选","en":"protein sorting","d":"新合成的蛋白经信号引导被定向运送到特定细胞器或部位的过 程。"}]},{"i":1,"sec":"第一节 分室化","title":"真核细胞分室化 (p2)","notes":"Part I 真核细胞分室化-膜被细胞器。Membranes divide the cytoplasm of eukaryotic cells into distinct compartments——膜把真核细胞质分隔成不同区室，各细胞器功能专一化，是效率的基础。","page":2,"level":"掌握","img":"assets/img/ch03/p002.jpg","anim":"compartmentalization","fig":null,"points":["膜把真核细胞质分隔成不同区室(膜被细胞器)","各细胞器功能专一化，是效率的基础"],"check":{"q":"关于真核细胞的分室化，叙述正确的是（　）","o":["A. 分室化使各细胞器的功能趋于相同","B. 膜把细胞质分隔为不同区室，使各细胞器功能专一化","C. 分室化只发生于原核细胞","D. 分室化降低了细胞代谢的效率"],"a":"B","e":"膜把真核细胞质分隔成不同区室，各细胞器功能专一化，是细胞高效运作的基础。","oe":["分室化使各细胞器功能专一化，而非趋于相同。","膜将真核细胞质分为不同区室，各细胞器功能专一，是效率的基础。","分室化是真核细胞的特征，原核细胞无此结构。","分室化提高了代谢效率，而不是降低。"]},"cards":[{"front":"真核细胞分室化（膜被细胞器）的意义是什么？","back":"膜把细胞质分隔成不同区室；各细胞器功能专一化，是细胞效率的基础","mnemonic":"膜隔区室，专工出高效","type":"功能","useImg":true,"blank":"细胞质","blank2":"细胞器功能专一化"}],"mem":"膜隔区室，专工出高效","big":"assets/img/ch03/big/p002.jpg"},{"i":2,"sec":"第一节 分室化","title":"内膜系统定义 (p3)","notes":"Endomembrane System内膜系统：在结构、功能乃至发生上相关的、由单层膜围绕成的细胞器或细胞结构。它们的膜是相互流动的、可相互转化的。包括内质网、高尔基体、溶酶体、胞内体、液泡及分泌小泡等(不含线粒体、叶绿体、过氧化物酶体)。","page":3,"level":"掌握","img":"assets/img/ch03/p003.jpg","anim":null,"fig":"这张图给出内膜系统的“膜流”方向：核膜与内质网相通 → 内质网出芽形成运输小泡 → 高尔基体顺面(CGN) → 中间膜囊 → 反面(TGN) → 分选到溶酶体、分泌泡或质膜。读图抓住“一条主干、多个岔路”：主干是 ER→Golgi→TGN，岔路在 TGN 决定货物去溶酶体还是分泌到胞外。","points":["结构、功能乃至发生上相关，由单层膜围绕成的细胞器","膜相互流动、可相互转化","包括ER、高尔基体、溶酶体、胞内体、液泡、分泌小泡（不含线粒体/叶绿体/过氧化物酶体）"],"check":{"q":"下列细胞器中属于内膜系统的是？","o":["A. 线粒体、叶绿体、过氧化物酶体","B. 细胞核、核仁、染色体","C. 内质网、高尔基体、溶酶体","D. 中心体、纺锤体、纤毛"],"a":"C","e":"内膜系统指结构功能及发生上相关、由单层膜围成的细胞器，包括内质网、高尔基体、溶酶体等。","oe":["错：页面明确其不属于内膜系统，不符合本页所学概念","错：核结构不是内膜系统成员，不符合本页所学概念","对：均为笔记所列内膜系统成员，与笔记原文相符","错：属细胞骨架相关结构，不符合本页所学概念"],"basis":"包括内质网、高尔基体、溶酶体…(不含线粒体、叶绿体)"},"cards":[{"front":"内膜系统的定义是什么？","back":"在结构、功能及发生上相关、由单层膜围绕的细胞器或结构；膜相互流动、可相互转化","mnemonic":"单层膜、相关联、可流动","type":"定义","useImg":false,"blank":"单层膜","blank2":"膜相互流动"},{"front":"内膜系统包括哪些细胞器？不包括哪些？","back":"包括内质网、高尔基体、溶酶体、胞内体、液泡及分泌小泡；不包括线粒体、叶绿体、过氧化物酶体","mnemonic":"内高溶体液泡泡，线叶过不算","type":"组成数字","useImg":false,"blank":"内质网","blank2":"高尔基体"}],"mem":"单层膜、相关联、可流动","big":"assets/img/ch03/big/p003.jpg"},{"i":3,"sec":"第一节 分室化","title":"内吞途径 (p4)","notes":"Endocytic pathway from the plasma membrane to lysosomes：质膜→早期胞内体(内体,endosome)→晚期胞内体→溶酶体。是细胞摄取胞外物质的降解途径。\n\n【本页英文讲解】\n本页讲内吞途径（endocytic pathway）从质膜到溶酶体的运输路线。细胞经内吞摄取胞外物质后，依次经质膜→早期胞内体（early endosome）→晚期胞内体（late endosome）→溶酶体（lysosome），最终被降解。这是与分泌途径方向相反的膜泡运输通路。考点：各站点顺序及内体分选功能，见翟中和教材第七章、第八章。","page":4,"level":"掌握","img":"assets/img/ch03/p004.jpg","anim":null,"fig":"早期内体接收来自质膜的胞吞小泡，腔内 pH 逐渐降低；随质子泵持续泵入 H⁺，早期内体成熟为晚期内体，最终与溶酶体融合。图的关键是“成熟＝pH 下降＋货物分选”。","points":["内吞途径：质膜→早期胞内体→晚期胞内体→溶酶体","是摄取胞外物质的降解途径（与分泌途径方向相反）"],"check":{"q":"内吞途径从质膜到溶酶体的运输顺序是（　）","o":["A. 质膜→晚期胞内体→早期胞内体→溶酶体","B. 质膜→早期胞内体→晚期胞内体→溶酶体","C. 质膜→高尔基体→早期胞内体→溶酶体","D. 质膜→溶酶体→胞内体→高尔基体"],"a":"B","e":"内吞物质依次经质膜、早期胞内体、晚期胞内体到达溶酶体，最终被降解。","oe":["早期胞内体应在晚期胞内体之前，顺序颠倒。","内吞物质依次经质膜、早期胞内体、晚期胞内体到达溶酶体降解。","高尔基体属分泌途径，不参与内吞途径的这一顺序。","溶酶体是内吞途径的终点，不会先于胞内体出现。"]},"cards":[{"front":"内吞途径的路径是什么？","back":"质膜→早期胞内体→晚期胞内体→溶酶体；是摄取胞外物质的降解途径","mnemonic":"质早晚溶，由外到内降解","type":"流程","useImg":true,"blank":"溶酶体","blank2":"胞内体"}],"mem":"质早晚溶，由外到内降解","big":"assets/img/ch03/big/p004.jpg","terms":[{"t":"内吞途径","en":"endocytic pathway","d":"质膜内陷形成内吞小泡、把细胞外物质运入细胞的运输途径。"},{"t":"早期胞内体","en":"early endosome","d":"内吞小泡脱包被后融合形成的、pH偏酸的胞内区室，是分选和回收内吞货物的枢纽。"},{"t":"晚期胞内体","en":"late endosome","d":"由早期胞内体成熟而来，进一步酸化并最终与溶酶体融合。"}]},{"i":4,"sec":"第一节 分室化","title":"其他膜性细胞器 (p5)","notes":"区别：Several other membranous organelles of the cytoplasm——线粒体、叶绿体、过氧化物酶体虽具膜，但不由内膜系统衍生，不属于内膜系统。其膜蛋白由自身基因组或特殊途径导入。","page":5,"level":"理解","img":"assets/img/ch03/p005.jpg","anim":null,"fig":null,"points":null,"check":{"q":"下列具有膜但不属于内膜系统的是（　）","o":["A. 胞内体、分泌泡和液泡","B. 线粒体、叶绿体和过氧化物酶体","C. 内质网、胞内体和溶酶体","D. 内质网、高尔基体和溶酶体"],"a":"B","e":"线粒体、叶绿体、过氧化物酶体虽具膜，但不由内膜系统衍生，不属于内膜系统。","oe":["胞内体、分泌泡、液泡均属于内膜系统。","线粒体、叶绿体、过氧化物酶体虽有膜，但不由内膜系统衍生，不属内膜系统。","内质网、胞内体、溶酶体都属于内膜系统。","内质网、高尔基体、溶酶体是内膜系统的典型成员。"]},"cards":null,"mem":"线粒体/叶绿体/过氧化物酶体有膜但非内膜系统","big":"assets/img/ch03/big/p005.jpg"},{"i":5,"sec":"第一节 分室化","title":"细胞膜系统的研究方法 (p6)","notes":"A few approaches to the study of cytomembranes：①放射自显影与电镜技术；②GFP标记活细胞观察蛋白运动；③差速离心与密度梯度离心分离细胞器；④亚细胞组分分离。","page":6,"level":"掌握","img":"assets/img/ch03/p006.jpg","anim":null,"fig":null,"points":["放射自显影与电镜技术","GFP标记活细胞观察蛋白运动","差速离心与密度梯度离心（亚细胞组分分离）"],"check":{"q":"下列属于细胞膜系统研究方法的是？","o":["A. 聚合酶链反应(PCR)","B. X射线晶体衍射测定DNA结构","C. 双缩脲法定量蛋白质","D. 放射自显影、GFP标记与差速离心"],"a":"D","e":"研究细胞膜系统可用放射自显影与电镜、GFP标记活细胞、差速离心与密度梯度离心及亚细胞分离。","oe":["错：PCR用于扩增核酸，不符合本页所学概念","错：用于结构解析，非膜系统研究","错：双缩脲法属于蛋白质定量方法","对：均为笔记所列研究方法，与笔记原文相符"],"basis":"放射自显影与电镜技术；GFP标记活细胞；差速离心与密度梯度离心"},"cards":[{"front":"研究细胞膜系统的主要方法有哪些？","back":"放射自显影与电镜；GFP标记活细胞观察蛋白运动；差速离心与密度梯度离心；亚细胞组分分离","mnemonic":"自显、荧光、离心、分离","type":"流程","useImg":false,"blank":"差速离心","blank2":"密度梯度离心"}],"mem":"自显、荧光、离心、分离","big":"assets/img/ch03/big/p006.jpg","terms":[{"t":"聚合酶链反应","en":"PCR","d":"体外扩增特定DNA片段的技术。"}]},{"i":6,"sec":"第一节 分室化","title":"放射自显影与电镜 (p7)","notes":"放射自显影与电镜技术：用放射性标记氨基酸脉冲标记胰腺腺泡细胞，追踪分泌蛋白在ER→Golgi→分泌小泡→细胞外的运输路径。这是研究膜泡运输的经典实验。","page":7,"level":"掌握","img":"assets/img/ch03/p007.jpg","anim":"pulse_chase","fig":null,"points":["Palade 用放射性氨基酸脉冲标记胰腺腺泡细胞，追踪分泌蛋白路径。","3 min 放射性在粗面内质网 → 20 min 到高尔基体 → 120 min 到分泌泡(分泌颗粒)。","结论：分泌蛋白沿 rER→Golgi→分泌泡→胞外 单向运输。"],"check":{"q":"Palade用放射性氨基酸脉冲标记胰腺腺泡细胞，追踪到的分泌蛋白路径是（　）","o":["A. 细胞核→粗面内质网→高尔基体→细胞外","B. 高尔基体→粗面内质网→分泌泡→细胞外","C. 粗面内质网→溶酶体→分泌泡→细胞外","D. 粗面内质网→高尔基体→分泌泡→细胞外"],"a":"D","e":"脉冲标记显示3min放射性在rER、20min到高尔基体、120min到分泌泡，最终分泌到胞外。","oe":["分泌蛋白在胞质核糖体起始，不经过细胞核。","分泌蛋白先经rER再到高尔基体，顺序不应颠倒。","溶酶体不是分泌蛋白运输的必经站点。","脉冲标记显示3min在rER、20min到高尔基体、120min到分泌泡，最终分泌到胞外。"]},"cards":[{"front":"放射自显影与电镜实验证明了什么？","back":"用放射性氨基酸脉冲标记胰腺腺泡细胞，追踪分泌蛋白路径：ER→Golgi→分泌小泡→细胞外","mnemonic":"脉冲标记追分泌，ER高泡出细胞","type":"例证","useImg":true,"blank":"分泌蛋白","blank2":"分泌小泡"}],"mem":"脉冲标记追分泌，ER高泡出细胞","big":"assets/img/ch03/big/p007.jpg"},{"i":7,"sec":"第一节 分室化","title":"GFP标记活细胞 (p8)","notes":"The use of GFP reveals the movement of proteins within a living cell——绿色荧光蛋白(GFP)标记使人们能在活细胞中实时观察蛋白质的运动和定位。\n\n【本页英文讲解】\n本页讲绿色荧光蛋白（GFP，green fluorescent protein）在活细胞成像中的应用。用GFP标记目标蛋白后，可借荧光显微镜在活细胞中实时观察蛋白质的运动与定位。GFP源自水母，成熟发光无需底物和辅因子，是细胞生物学常用报告分子。此为研究方法考点，常用于研究蛋白质分选与膜泡运输（第八章）。","page":8,"level":"理解","img":"assets/img/ch03/p008.jpg","anim":null,"fig":"把 GFP(绿色荧光蛋白)与目标蛋白融合表达，用荧光显微镜实时观察蛋白在活细胞内的运动。图中荧光从 ER 经高尔基体向细胞表面移动，说明膜蛋白/分泌蛋白是经内膜系统逐步运输的。GFP 是“活细胞蛋白定位”的通用标签。","points":null,"check":{"q":"关于绿色荧光蛋白(GFP)的叙述，正确的是（　）","o":["A. 发光需要外加底物和辅因子","B. 只能用于固定细胞的免疫染色","C. 可标记目标蛋白并在活细胞中实时观察其运动与定位","D. 来源于细菌，主要用于标记DNA"],"a":"C","e":"GFP源自水母，成熟发光无需底物和辅因子，可实时显示活细胞内蛋白质的运动与定位。","oe":["GFP成熟发光不需要外加底物和辅因子。","GFP最大优势是可用于活细胞成像，而非仅固定细胞。","GFP源自水母，成熟发光无需底物和辅因子，可实时显示活细胞内蛋白运动。","GFP源自水母，常用于标记蛋白质而非DNA。"]},"cards":null,"mem":"GFP标记可活细胞内实时看蛋白运动定位","big":"assets/img/ch03/big/p008.jpg"},{"i":8,"sec":"第一节 分室化","title":"差速离心分离 (p9-10)","notes":"差速离心分离细胞器：20,000g 20min→核、线粒体、未破碎细胞；50,000g 2hrs→微粒体(microsome)。In general, the smaller the size, the higher the speed needed。微粒体是破碎ER自我融合形成的囊泡。","page":9,"level":"掌握","img":"assets/img/ch03/p009.jpg","anim":"differential_centrifugation","fig":null,"points":["亚细胞分级分离的基础是差速离心。","先低速(约 20,000g)沉淀核、线粒体、过氧化物酶体、未破碎细胞；","再高速(约 50,000g)沉淀微粒体(ER/Golgi 碎片)，上清为胞质溶胶。"],"check":{"q":"差速离心分离细胞器时，通常先沉淀的组分是（　）","o":["A. 核、线粒体等较大组分，再高速沉淀微粒体","B. 微粒体只存在于低速沉淀中","C. 沉淀顺序与颗粒大小和离心速度无关","D. 先沉淀微粒体，再沉淀细胞核"],"a":"A","e":"差速离心先低速沉淀核、线粒体等较大颗粒，再高速沉淀微粒体，颗粒越小所需转速越高。","oe":["差速离心先低速沉淀核、线粒体等较大颗粒，再高速沉淀微粒体。","微粒体在高速(约50000g)沉淀，不在低速沉淀中。","沉淀顺序取决于颗粒大小与离心速度。","微粒体较小，需高速才能沉淀，不会先于细胞核沉淀。"]},"cards":[{"front":"差速离心分离细胞器的条件与结果是什么？","back":"20,000g 20min→核、线粒体、未破碎细胞；50,000g 2hrs→微粒体；越小需转速越高","mnemonic":"越大越先沉，越小转速高","type":"流程","useImg":false,"blank":"微粒体","blank2":"线粒体"},{"front":"微粒体是什么？","back":"破碎内质网自我融合形成的囊泡","mnemonic":"碎ER自融合成微粒体","type":"定义","useImg":false,"blank":"囊泡","blank2":"内质网"}],"mem":"越大越先沉，越小转速高","big":"assets/img/ch03/big/p009.jpg"},{"i":9,"sec":"第二节 内质网","title":"内质网(ER)概述 (p11)","notes":"3.1 内质网(endoplasmic reticulum, ER)：粗面内质网(rER)——膜表面分布大量核糖体，多扁囊状排列较整齐，合成分泌蛋白；光面内质网(sER)——表面无核糖体。ER是真核细胞普遍且形态多变的细胞器。","page":11,"level":"掌握","img":"assets/img/ch03/p011.jpg","anim":null,"fig":null,"points":["rER：膜表面有大量核糖体，多扁囊状，合成分泌蛋白","sER：表面无核糖体","ER是真核细胞普遍且形态多变的细胞器"],"check":{"q":"关于粗面内质网(rER)的形态与功能，下列叙述正确的是？","o":["A. 表面无核糖体，主要参与解毒与储钙","B. 膜表面附着大量核糖体，主要合成分泌蛋白","C. 膜层不连续，与光面内质网各自完全独立","D. 仅存在于原核细胞，负责蛋白质合成"],"a":"B","e":"rER膜附着核糖体、合成分泌蛋白，sER表面无核糖体，二者膜连续。","oe":["无核糖体、解毒储钙是光面内质网sER的功能","rER膜附着核糖体，呈扁囊状，主要合成分泌蛋白","rER与sER形态功能不同，但膜是连续的","ER是真核细胞普遍且形态多变的细胞器"]},"cards":[{"front":"粗面内质网与光面内质网的区别是什么？","back":"rER：膜表面有大量核糖体，多扁囊状排列整齐，合成分泌蛋白；sER：表面无核糖体","mnemonic":"粗有核糖合分泌，光无核糖管脂质","type":"对比","useImg":true,"blank":"核糖体","blank2":"分泌蛋白"}],"mem":"粗有核糖合分泌，光无核糖管脂质","big":"assets/img/ch03/big/p011.jpg","terms":[{"t":"粗面内质网","en":"rough ER, rER","d":"表面附着核糖体的内质网，主要合成分泌蛋白与膜蛋白。"},{"t":"光面内质网","en":"smooth ER, sER","d":"无核糖体的内质网，参与脂质合成、解毒和储存Ca²⁺。"}]},{"i":10,"sec":"第二节 内质网","title":"电镜下的粗面内质网 (p12)","notes":"透射电镜下的胰腺腺泡细胞中的粗面内质网、扫描电镜下的粗面内质网：显示rER的扁囊状结构和表面核糖体颗粒。","page":12,"level":"理解","img":"assets/img/ch03/p012.jpg","anim":null,"fig":null,"points":null,"check":{"q":"透射电镜下胰腺腺泡细胞粗面内质网的典型特征是？","o":["A. 表面光滑无颗粒的同心圆状双膜结构","B. 由微管构成的辐射状纤维网络","C. 表面附着核糖体颗粒的扁囊状结构","D. 内部充满致密结晶物质的囊泡"],"a":"C","e":"电镜下rER的特征是扁囊状结构加表面核糖体颗粒，可与sER区分。","oe":["表面光滑无颗粒是sER的特点，非rER","微管属细胞骨架，不是内质网的形态","rER电镜下呈扁囊状且表面附着核糖体颗粒","致密结晶非rER特征，且与题干无关"]},"cards":null,"mem":"rER电镜：扁囊状+表面核糖体颗粒","big":"assets/img/ch03/big/p012.jpg"},{"i":11,"sec":"第二节 内质网","title":"微粒体与特殊内质网 (p13)","notes":"两种特殊类型的内质网。微粒体(microsomes)：体外实验中细胞匀浆和差速离心得到的、由分离的内质网自我融合形成的近似球形囊泡结构。是研究ER功能的体外模型。","page":13,"level":"掌握","img":"assets/img/ch03/p013.jpg","anim":null,"fig":"微粒体是匀浆时内质网膜破碎后重新封闭成的囊泡，保留了 ER 的酶系。肌质网(SR)是特化的 sER，含 Ca²⁺-ATPase 储存 Ca²⁺。sER 与 rER 功能不同：sER 无核糖体，管脂质合成、解毒、储钙。","points":["体外匀浆+差速离心得到的、由分离ER自我融合成的球形囊泡","是研究ER功能的体外模型"],"check":{"q":"关于微粒体的叙述，正确的是（　）","o":["A. 由高尔基体破碎后融合形成","B. 是完整细胞内天然存在的一种细胞器","C. 是线粒体自我融合形成的产物","D. 是破碎内质网自我融合形成的近似球形囊泡"],"a":"D","e":"微粒体是细胞匀浆经差速离心后由分离的内质网自我融合成的球形囊泡，是研究ER的体外模型。","oe":["微粒体主要来源于内质网碎片，而非高尔基体。","微粒体是体外破碎后人工形成的囊泡，非天然细胞器。","微粒体来源于内质网，与线粒体无关。","微粒体是匀浆差速离心后由分离的内质网自我融合成的球形囊泡，是ER研究模型。"]},"cards":[{"front":"微粒体(microsomes)是什么？如何获得？","back":"体外细胞匀浆、差速离心后由内质网自我融合形成的球形囊泡；是研究ER功能的体外模型","mnemonic":"匀浆离心，ER自融成球","type":"定义","useImg":false,"blank":"球形囊泡","blank2":"差速离心"}],"mem":"匀浆离心，ER自融成球","big":"assets/img/ch03/big/p013.jpg"},{"i":12,"sec":"第二节 内质网","title":"ER的结构 (p14)","notes":"内质网是真核细胞中普遍且形态多变的细胞器之一，由封闭的管状或扁平囊状膜系统及其包被的腔(ER腔/lumen)构成。rER与sER在形态和功能上不同，但膜是连续的。","page":14,"level":"掌握","img":"assets/img/ch03/p014.jpg","anim":null,"fig":null,"points":["由封闭的管状或扁平囊状膜系统及其包被的腔(ER腔)构成","rER与sER形态功能不同，但膜是连续的"],"check":{"q":"关于内质网(ER)的结构，下列叙述正确的是？","o":["A. rER与sER的膜互不相连、各自独立分布","B. 是原核细胞中普遍存在的细胞器","C. 由封闭的管状或扁平囊状膜系统及其包被的腔构成","D. ER腔与细胞质基质之间直接相通"],"a":"C","e":"ER是封闭膜系统围成ER腔，真核细胞普遍存在，rER与sER膜连续。","oe":["rER与sER虽功能不同，但膜是连续的","ER是真核细胞普遍具有的细胞器","ER由封闭膜系统及其围成的ER腔构成","ER腔被膜包被，与细胞质基质隔开"]},"cards":[{"front":"内质网的基本结构由什么构成？","back":"封闭的管状或扁平囊状膜系统及其包被的ER腔(lumen)；rER与sER形态功能不同但膜连续","mnemonic":"管囊成网，腔在其中","type":"组成","useImg":true,"blank":"ER腔","blank2":"rER"}],"mem":"管囊成网，腔在其中","big":"assets/img/ch03/big/p014.jpg"},{"i":13,"sec":"第二节 内质网","title":"sER功能-解毒与储钙 (p15)","notes":"(1) sER功能：①Detoxification解毒；②Sequestering calcium储钙——参与信号传递，肌细胞肌质网储钙。sER还合成脂类。\n\n【本页英文讲解】\n本页讲滑面内质网（sER，smooth endoplasmic reticulum）的功能：①解毒（detoxification）；②储存钙（sequestering calcium），储存Ca²⁺并参与信号传递，肌细胞中特化为肌质网储存钙以调节收缩。此外sER还合成脂类。考点：sER与粗面内质网（rER）的功能分工，见教材第七章内质网（ER）。","page":15,"level":"掌握","img":"assets/img/ch03/p015.jpg","anim":null,"fig":null,"points":["光面内质网(sER)三大功能：合成脂质、解毒、储存 Ca²⁺。","肝细胞 sER 含细胞色素 P450，氧化分解药物/毒物。","肌细胞 sER(肌质网)储存 Ca²⁺，控制肌肉收缩。"],"check":{"q":"下列属于光面内质网(sER)功能的是？","o":["A. 合成脂质、解毒、储存Ca²⁺","B. 合成分泌性蛋白","C. 将mRNA翻译为多肽","D. 为分泌蛋白添加N-连接糖链"],"a":"A","e":"光面内质网表面无核糖体，主要功能为合成脂质、解毒和储存Ca²⁺，肌细胞中特化为肌质网。","oe":["对：笔记列出sER三大功能，与笔记原文相符","错：分泌蛋白由rER合成，不符合本页所学概念","错：翻译在核糖体上进行，不符合本页所学概念","错：糖基化起始于rER而非sER"],"basis":"光面内质网(sER)三大功能：合成脂质、解毒、储存Ca²⁺"},"cards":[{"front":"sER的三大功能是什么？","back":"①解毒；②储钙(参与信号传递)；③合成脂类","mnemonic":"解、钙、脂","type":"功能","useImg":false,"blank":"解毒","blank2":"储钙"}],"mem":"解、钙、脂","big":"assets/img/ch03/big/p015.jpg","terms":[{"t":"解毒","en":"detoxification","d":"sER通过羟化等反应把脂溶性药物、毒物转化为易于排泄形式的功能。"},{"t":"储存钙","en":"sequestering calcium","d":"sER储存Ca²⁺，在信号刺激下释放到胞质。"}]},{"i":14,"sec":"第二节 内质网","title":"sER解毒作用 (p16)","notes":"解毒作用——肝细胞：肝细胞sER很丰富，含一些酶用以清除脂溶性药物和代谢产生的有害物质。多数解毒反应与氧化作用有关，核心成员是细胞色素P450。","page":16,"level":"掌握","img":"assets/img/ch03/p016.jpg","anim":null,"fig":"P450 催化的羟化反应：把脂溶性药物/毒物加上羟基使其水溶性增加，便于排出。解毒反应依赖 sER 膜上的 P450 和 NADPH。长期服用某些药物会诱导 sER 增生(P450 增多)。","points":["肝细胞sER丰富，清除脂溶性药物与有害物质","解毒多为氧化反应，核心成员是细胞色素P450"],"check":{"q":"肝细胞滑面内质网解毒作用的核心酶成员是（　）","o":["A. 细胞色素P450","B. 水通道蛋白AQP1","C. Na+/K+-ATPase","D. 信号肽酶"],"a":"A","e":"肝细胞sER很丰富，含与氧化解毒有关的酶，核心成员是细胞色素P450。","oe":["肝细胞sER富含与氧化解毒有关的酶，核心成员是细胞色素P450。","AQP1是水通道，与脂溶性药物解毒无关。","Na+/K+-ATPase位于质膜，负责离子转运，不参与解毒。","信号肽酶负责切除信号肽，与解毒作用无关。"]},"cards":[{"front":"肝细胞sER解毒的核心酶是什么？","back":"细胞色素P450；多数解毒反应与氧化作用有关，清除脂溶性药物和有害物质","mnemonic":"P450，肝里解毒王","type":"例证","useImg":false,"blank":"细胞色素P450","blank2":"氧化作用"}],"mem":"P450，肝里解毒王","big":"assets/img/ch03/big/p016.jpg"},{"i":15,"sec":"第二节 内质网","title":"sER储钙 (p17)","notes":"储钙(Ca库)：ER膜上的Ca2+-ATPase将细胞基质中的钙泵入ER中储存，使内质网腔钙离子浓度高达3mM。sER通过释放/回收Ca2+调节细胞信号(如肌肉收缩)。","page":17,"level":"掌握","img":"assets/img/ch03/p017.jpg","anim":null,"fig":"肌质网膜上的 Ca²⁺-ATPase 把胞质 Ca²⁺ 泵入 SR 腔储存；神经冲动到达时，Ca²⁺ 通道开放，Ca²⁺ 涌入胞质触发肌丝收缩。图强调“储钙—释放”的开关作用。","points":["ER膜上Ca²⁺-ATPase将钙泵入ER储存，腔钙浓度达3mM","sER通过释放/回收Ca²⁺调节信号（如肌肉收缩）"],"check":{"q":"内质网储存Ca2+所依靠的机制是（　）","o":["A. 钙通道使Ca2+顺浓度梯度自由扩散入ER","B. 线粒体将自身Ca2+转运至ER腔","C. 质膜Na+/K+泵将Ca2+泵入ER腔","D. ER膜上的Ca2+-ATPase将胞质Ca2+泵入ER腔"],"a":"D","e":"ER膜上的Ca2+-ATPase把胞质中的钙泵入ER腔储存，使腔内钙浓度高达3mM。","oe":["ER储钙靠Ca2+-ATPase主动泵入，而非通道自由扩散。","ER腔高钙由ER自身钙泵建立，与线粒体无关。","Na+/K+泵转运Na+和K+，不负责把Ca2+泵入ER。","ER膜上Ca2+-ATPase把胞质Ca2+泵入ER腔，使腔内钙浓度高达3mM。"]},"cards":[{"front":"ER如何储钙？腔内钙浓度多高？","back":"ER膜上Ca2+-ATPase将基质Ca2+泵入ER储存；腔钙浓度高达3mM，通过释放/回收Ca2+调节信号","mnemonic":"钙泵入腔，三毫摩尔","type":"流程","useImg":true,"blank":"Ca2+-ATPase","blank2":"ER膜"}],"mem":"钙泵入腔，三毫摩尔","big":"assets/img/ch03/big/p017.jpg"},{"i":16,"sec":"第二节 内质网","title":"sER合成膜脂 (p18)","notes":"sER合成构成细胞所需的绝大多数膜脂(甘油磷脂和胆固醇)。磷脂酰胆碱(卵磷脂)的合成：脂酰辅酶A在sER膜上经酶催化合成，膜脂在ER合成后运往其他膜。","page":18,"level":"掌握","img":"assets/img/ch03/p018.jpg","anim":"lipid_synthesis","fig":"膜脂(甘油磷脂、胆固醇)主要在 sER 的胞质面合成。新合成的脂质插入 ER 膜，随后通过囊泡运输或磷脂交换蛋白分配到其他膜。图显示合成部位在 ER 膜上。","points":["sER合成构成细胞所需的绝大多数膜脂（甘油磷脂和胆固醇）","卵磷脂(磷脂酰胆碱)在sER膜上经酶催化合成"],"check":{"q":"关于膜脂的合成，叙述正确的是（　）","o":["A. sER合成绝大多数膜脂，包括甘油磷脂和胆固醇","B. 胆固醇不能在细胞内合成，只能从胞外摄取","C. 磷脂酰胆碱在细胞核内合成","D. 膜脂主要由高尔基体合成后运往sER"],"a":"A","e":"sER合成构成细胞所需的绝大多数膜脂，包括甘油磷脂和胆固醇，再运往其他膜结构。","oe":["sER合成甘油磷脂和胆固醇等绝大多数膜脂，再运往其他膜结构。","胆固醇是膜脂之一，可在细胞内(主要是sER)合成。","磷脂酰胆碱在sER膜上由脂酰辅酶A参与合成。","膜脂主要在sER合成，高尔基体不是主要合成场所。"]},"cards":[{"front":"sER合成哪些膜脂？以什么为例？","back":"绝大多数膜脂(甘油磷脂和胆固醇)；如磷脂酰胆碱(卵磷脂)在sER膜上由脂酰辅酶A经酶催化合成","mnemonic":"膜脂工厂在sER","type":"功能","useImg":false,"blank":"磷脂酰胆碱","blank2":"甘油磷脂"}],"mem":"膜脂工厂在sER","big":"assets/img/ch03/big/p018.jpg"},{"i":17,"sec":"第二节 内质网","title":"膜脂在ER合成后运输 (p19)","notes":"Most membrane lipids are synthesized entirely within the ER——膜脂在ER合成后，通过运输方式(转运蛋白、膜泡运输、膜接触)运往线粒体、高尔基体、质膜等。","page":19,"level":"理解","img":"assets/img/ch03/p019.jpg","anim":null,"fig":"ER 合成的脂质有三种去向：①经囊泡运输随膜流到 Golgi 及以后；②由磷脂交换蛋白(PITP)在膜之间搬运；③在 ER 与线粒体等接触点直接转移。图说明“脂质不能自由穿水相”，需载体或囊泡。","points":null,"check":{"q":"ER合成的膜脂运往线粒体、高尔基体和质膜的方式包括？","o":["A. 自由穿过水相扩散","B. 囊泡运输、磷脂交换蛋白搬运、膜接触点直接转移","C. 经核孔复合体运输","D. 由ATP驱动泵逆浓度梯度运输"],"a":"B","e":"ER合成的膜脂需借助载体或囊泡运输，包括囊泡运输、磷脂交换蛋白搬运及膜接触点直接转移。","oe":["错：脂质不能自由穿过水相，不符合本页所学概念","对：与图示三种去向一致，与笔记原文相符","错：核孔运输针对蛋白质，不符合本页所学概念","错：膜脂转运并非由ATP驱动泵完成"],"basis":"经囊泡运输…由磷脂交换蛋白(PITP)搬运；接触点直接转移"},"cards":null,"mem":"膜脂主要在ER合成后运往各细胞器","big":"assets/img/ch03/big/p019.jpg","terms":[{"t":"磷脂交换蛋白","en":"PITP","d":"在膜之间转运单个磷脂分子、帮助膜脂在ER与其他膜间分配的蛋白。"}]},{"i":18,"sec":"第二节 内质网","title":"rER功能-蛋白质合成 (p20)","notes":"(2) rER的功能：①蛋白质合成——rER膜上有称作translocon(易位子)的蛋白复合体'通道'，蛋白多肽链边延伸边穿过rER膜入内质网腔，继续折叠修饰。","page":20,"level":"掌握","img":"assets/img/ch03/p020.jpg","anim":null,"fig":null,"points":["rER膜上有易位子(translocon)蛋白复合体通道","多肽链边延伸边穿过rER膜进入内质网腔，继续折叠修饰"],"check":{"q":"rER上进行蛋白质合成时，多肽链进入ER腔所依靠的结构是？","o":["A. 核孔复合体","B. 网格蛋白包被","C. 质子泵","D. 易位子(translocon)通道"],"a":"D","e":"rER上易位子构成通道，新生肽链边延伸边穿膜入ER腔。","oe":["核孔复合体介导核质之间的物质运输","网格蛋白参与膜泡形成，与肽链穿膜无关","质子泵维持溶酶体酸性，不转运新生肽链","易位子介导新生肽链穿膜进入ER腔"]},"cards":[{"front":"rER合成蛋白质的关键通道是什么？","back":"易位子(translocon)蛋白复合体；多肽链边延伸边穿过rER膜进入ER腔，继续折叠修饰","mnemonic":"边翻译边进腔","type":"流程","useImg":true,"blank":"易位子","blank2":"ER腔"}],"mem":"边翻译边进腔","big":"assets/img/ch03/big/p020.jpg"},{"i":19,"sec":"第二节 内质网","title":"易位子(translocon) (p21)","notes":"内质网易位子(translocon/translocator)：rER膜上的一种蛋白复合体，中心有一个直径2nm的'孔道'，与新合成的多肽进入ER腔有关。","page":21,"level":"掌握","img":"assets/img/ch03/p021.jpg","anim":"sec61_translocon","fig":null,"points":["rER膜上的一种蛋白复合体","中心有直径2nm的孔道，与新生多肽进入ER腔有关"],"check":{"q":"关于内质网易位子(translocon)，下列叙述正确的是？","o":["A. 位于质膜上，负责离子跨膜运输","B. 是一种运输小分子的通道蛋白","C. rER膜上的蛋白复合体，中央有孔道，与多肽进入ER腔有关","D. 由脂双层单独构成，不含蛋白质"],"a":"C","e":"易位子是rER膜上的蛋白复合体，中央有一直径2nm的孔道，与新合成多肽进入ER腔有关。","oe":["错：易位子位于rER膜而非质膜","错：其针对新生多肽而非小分子，不符合本页所学概念","对：符合笔记对易位子的描述，与笔记原文相符","错：易位子本质为蛋白复合体，不符合本页所学概念"],"basis":"rER膜上的一种蛋白复合体，中心有一个直径2nm的'孔道'"},"cards":[{"front":"易位子(translocon)的结构与功能？","back":"rER膜上的蛋白复合体，中心有直径2nm的孔道；与新合成多肽进入ER腔有关","mnemonic":"2纳米小孔，多肽进门","type":"组成数字","useImg":true,"blank":"蛋白复合体","blank2":"孔道"}],"mem":"2纳米小孔，多肽进门","big":"assets/img/ch03/big/p021.jpg","terms":[{"t":"易位子","en":"translocon / translocator","d":"内质网膜上由Sec61复合体构成的、供新生分泌蛋白跨膜进入ER腔的通道。"}]},{"i":20,"sec":"第二节 内质网","title":"易位子结构 (p22)","notes":"Cross-sectional view of the translocon channel：易位子通道的侧面结构，中心孔道允许新生肽链穿膜进入ER腔。\n\n【本页英文讲解】\n本页讲易位子（translocon）通道的结构。图中为易位子通道的侧面/横截面观，其中央孔道允许新生肽链（nascent polypeptide）穿膜进入内质网腔（ER lumen）。易位子是蛋白质共翻译转运的通道，由Sec61复合体构成。考点：新生肽链经易位子进入ER腔的机制，见翟中和教材第八章蛋白质分选与膜泡运输。","page":22,"level":"理解","img":"assets/img/ch03/p022.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于易位子(translocon)通道的叙述，正确的是（　）","o":["A. 是位于线粒体膜上的蛋白质通道","B. 只有在翻译完全结束后才开放","C. 由Sec61复合体构成，中央孔道允许新生肽链穿膜进入ER腔","D. 介导新生蛋白质进入细胞核"],"a":"C","e":"易位子由Sec61复合体构成，中央孔道允许新生肽链穿膜进入内质网腔，参与共翻译转运。","oe":["易位子位于内质网膜，而非线粒体膜。","易位子参与共翻译转运，翻译边进行边转移。","易位子由Sec61复合体构成，中央孔道让新生肽链穿膜进入内质网腔。","介导蛋白质进入细胞核的是核孔复合体。"]},"cards":null,"mem":"易位子中央孔道：新生肽链穿膜入ER腔","big":"assets/img/ch03/big/p022.jpg"},{"i":21,"sec":"第二节 内质网","title":"Sec61复合体 (p23)","notes":"Sec61 complex(Sec61α、Sec61β、Sec61γ)高度保守，从细菌到人都有，构成蛋白质转运通道的核心。\n\n【本页英文讲解】\n本页讲Sec61复合体（Sec61 complex）的组成与保守性。它由Sec61α、Sec61β、Sec61γ三个亚基组成，从细菌到人均高度保守，构成蛋白质转运通道的核心，细菌中对应SecY复合体。Sec61是内质网易位子的核心成分，负责新生肽链穿膜转运。考点：转运通道的进化保守性，见教材第八章共翻译转运。","page":23,"level":"理解","img":"assets/img/ch03/p023.jpg","anim":null,"fig":"易位子是 rER 膜上的蛋白质通道，核心为 Sec61 复合体(α/β/γ 亚基)，中央通道直径约 2 nm。新生肽链被 SRP 送到膜上后经 Sec61 进入 ER 腔；分泌蛋白完全穿入，跨膜蛋白则侧向进入脂双层。图中还可见信号肽酶在腔内切除信号肽。","points":null,"check":{"q":"关于Sec61复合体，下列叙述正确的是？","o":["A. 由Sec61α、β、γ三亚基组成，高度保守，构成蛋白转运通道核心","B. 主要负责脂类分子在膜系统间的转运","C. 是核孔复合体的主要组成成分","D. 只存在于哺乳动物细胞，细菌中不存在同源物"],"a":"A","e":"Sec61由α、β、γ三亚基组成，高度保守，是转运通道的核心。","oe":["Sec61三聚体从细菌到人高度保守，是转运通道核心","Sec61负责新生肽链的穿膜转运","核孔复合体与Sec61是两种不同结构","细菌中存在对应的SecY复合体"]},"cards":null,"mem":"Sec61(αβγ)细菌到人保守，转运通道核心","big":"assets/img/ch03/big/p023.jpg","terms":[{"t":"Sec61复合体","en":"Sec61 complex","d":"内质网膜上形成蛋白转运通道的核心复合体（α、β、γ亚基）。"}]},{"i":22,"sec":"第二节 内质网","title":"游离核糖体与膜结合核糖体 (p24-25)","notes":"细胞内几乎所有蛋白质合成都从胞质溶胶的游离多聚核糖体开始。一部分随肽链延伸(信号肽引导)转移到rER膜上继续翻译——共翻译转移(translocation and translation)。","page":24,"level":"掌握","img":"assets/img/ch03/p024.jpg","anim":null,"fig":"两类核糖体结构相同，只是所合成蛋白不同。合成分泌蛋白/膜蛋白时，信号肽把核糖体带到 rER 膜上(膜结合核糖体)；合成胞质蛋白/核蛋白时核糖体游离在胞质。“游离”与“膜结合”是可逆的，取决于正在翻译的肽链有无信号肽。","points":["几乎所有蛋白质合成都从胞质游离多聚核糖体开始","一部分随肽链延伸(信号肽引导)转移到rER膜继续翻译，即共翻译转移"],"check":{"q":"细胞内几乎所有蛋白质的合成都起始于（　）","o":["A. 细胞核内的核糖体","B. 粗面内质网膜上的结合核糖体","C. 胞质溶胶中的游离多聚核糖体","D. 线粒体内部的核糖体"],"a":"C","e":"细胞内几乎所有蛋白质都在胞质溶胶的游离多聚核糖体上起始合成，部分再转移至rER。","oe":["细胞核内不进行蛋白质的翻译过程。","膜结合核糖体由游离核糖体转移而来，并非起始场所。","几乎所有蛋白质都在胞质溶胶游离多聚核糖体起始合成，部分再转移至rER。","线粒体核糖体只合成线粒体自身的少数蛋白。"]},"cards":[{"front":"细胞内蛋白质合成最初在哪里开始？","back":"几乎所有蛋白质合成均起始于胞质溶胶的游离多聚核糖体","mnemonic":"一切从游离核糖体起步","type":"定位","useImg":false,"blank":"游离多聚核糖体","blank2":"胞质溶胶"},{"front":"什么是共翻译转移？","back":"肽链延伸中由信号肽引导，核糖体附着到rER膜上边翻译边转移入ER","mnemonic":"边合成边进门","type":"流程","useImg":true,"blank":"信号肽","blank2":"rER膜"}],"mem":"一切从游离核糖体起步","big":"assets/img/ch03/big/p024.jpg"},{"i":23,"sec":"第二节 内质网","title":"游离与膜结合核糖体 (p26)","notes":"真核细胞质中的核糖体：①游离态；②结合于内质网(粗面内质网)。两者结构相同，区别在于是否附着在ER膜上，取决于所合成蛋白是否含ER信号肽。","page":26,"level":"掌握","img":"assets/img/ch03/p026.jpg","anim":null,"fig":null,"points":["游离核糖体与膜结合核糖体结构相同","区别在于是否附着ER膜，取决于所合成蛋白是否含ER信号肽"],"check":{"q":"游离核糖体与膜结合核糖体的关系是（　）","o":["A. 结构完全不同，膜结合核糖体体积更大","B. 结构相同，区别在于是否附着ER膜，取决于所合成蛋白有无ER信号肽","C. 游离核糖体不含rRNA，膜结合核糖体含rRNA","D. 膜结合核糖体只能合成膜脂"],"a":"B","e":"真核细胞质中两类核糖体结构相同，是否附着ER膜取决于所合成蛋白是否含ER信号肽。","oe":["两者结构相同，并无体积和组成上的本质差异。","两类核糖体结构相同，是否附着ER取决于所合成蛋白是否含ER信号肽。","两类核糖体都含rRNA，都能进行蛋白质合成。","核糖体合成蛋白质，不能合成膜脂。"]},"cards":[{"front":"真核细胞质中核糖体有哪两种存在状态？","back":"游离态；结合于粗面内质网（rER）膜上","mnemonic":"游离或贴膜","type":"组成数字","useImg":true,"blank":"游离态","blank2":"粗面内质网"},{"front":"游离核糖体与膜结合核糖体结构是否相同？区别何在？","back":"结构相同；区别在于是否附着ER膜，取决于所合成蛋白是否含ER信号肽","mnemonic":"同机器，不同岗位","type":"对比","useImg":false,"blank":"ER信号肽","blank2":"ER膜"}],"mem":"游离或贴膜","big":"assets/img/ch03/big/p026.jpg"},{"i":24,"sec":"第二节 蛋白质分选","title":"蛋白质定向转运与分选 (p27)","notes":"蛋白质的定向转运(protein targeting)/蛋白分选(protein sorting)：生物体根据蛋白质自身的信号序列，将蛋白质运送到细胞的特定部位。信号序列是分选的'邮政编码'。","page":27,"level":"掌握","img":"assets/img/ch03/p027.jpg","anim":"protein_sorting_overview","fig":"核编码蛋白在胞质核糖体合成后有三条去向：①共翻译转运进入 ER(信号肽)，再经内膜系统；②翻译后转运进入线粒体、叶绿体、过氧化物酶体(导肽/转运肽)；③核孔运输进入细胞核(NLS)。图的核心是“信号序列决定目的地”。","points":["信号肽→内膜系统(ER)；导肽/转运肽→线粒体/叶绿体/过氧化物酶体；NLS→细胞核。","信号序列决定蛋白质的合成部位和运输方向。"],"check":{"q":"蛋白质分选所依据的“邮政编码”是（　）","o":["A. 内质网腔中的钙离子浓度","B. 蛋白质自身的信号序列","C. 核糖体中的rRNA序列","D. 高尔基体膜上的膜脂组成"],"a":"B","e":"生物体根据蛋白质自身的信号序列，将其运送到细胞的特定部位，信号序列即分选的密码。","oe":["钙离子浓度与信号转导有关，不是分选密码。","生物体根据蛋白质自身的信号序列将其运送到特定部位，信号序列即密码。","rRNA参与翻译过程，不充当蛋白质分选信号。","膜脂组成不决定蛋白质的运输方向。"]},"cards":[{"front":"什么是蛋白质定向转运（分选）？","back":"生物体根据蛋白质自身信号序列，将其运送到细胞特定部位的过程","mnemonic":"信号序列=邮政编码","type":"定义","useImg":false,"blank":"信号序列","blank2":"蛋白质自身信号序列"}],"mem":"信号序列=邮政编码","big":"assets/img/ch03/big/p027.jpg","terms":[{"t":"定向转运","en":"protein targeting","d":"蛋白借助信号序列被特异引导到目标区室的过程。"},{"t":"蛋白分选","en":"protein sorting","d":"在分岔点把蛋白送往不同去向的机制。"}]},{"i":25,"sec":"第二节 蛋白质分选","title":"主要蛋白分选途径 (p28)","notes":"Overview of major protein-sorting pathways in eukaryotes：核编码蛋白在胞质游离核糖体合成后，经核孔运输(核)、跨膜运输(线粒体/叶绿体/过氧化物酶体)、膜泡运输(ER→Golgi→溶酶体/质膜/分泌)到达目的地。","page":28,"level":"掌握","img":"assets/img/ch03/p028.jpg","anim":null,"fig":null,"points":["核编码蛋白在胞质游离核糖体合成","经核孔运输(核)、跨膜运输(线粒体/叶绿体/过氧化物酶体)、膜泡运输到达目的地"],"check":{"q":"核编码蛋白从胞质运往各目的地的途径包括？","o":["A. 单纯扩散、渗透、滤过","B. 复制、转录、反转录","C. 胞饮、吞噬、外排","D. 核孔运输、跨膜运输、膜泡运输"],"a":"D","e":"核编码蛋白在游离核糖体合成后，经核孔运输入核、跨膜运输进入线粒体等、膜泡运输进入内膜系统。","oe":["错：属小分子被动转运方式，不符合本页所学概念","错：属遗传信息传递过程，不符合本页所学概念","错：属膜泡运输的具体形式而非总途径","对：与笔记所列三条途径一致，与笔记原文相符"],"basis":"核孔运输(核)、跨膜运输、膜泡运输"},"cards":[{"front":"真核细胞核编码蛋白的主要分选途径有哪些？","back":"核孔运输（核）；跨膜运输（线粒体/叶绿体/过氧化物酶体）；膜泡运输（ER→Golgi→溶酶体/质膜/分泌）","mnemonic":"核孔、跨膜、膜泡三条路","type":"流程","useImg":true,"blank":"膜泡运输","blank2":"核孔运输"}],"mem":"核孔、跨膜、膜泡三条路","big":"assets/img/ch03/big/p028.jpg"},{"i":26,"sec":"第二节 蛋白质分选","title":"分选类型-共转移/后转移 (p29-30)","notes":"蛋白质分选类型：蛋白质首先在细胞质基质中合成；①后转移(post-translational)——合成完成后转运；②共转移(co-translational)——边合成边转运(入ER)。","page":30,"level":"掌握","img":"assets/img/ch03/p030.jpg","anim":null,"fig":null,"points":["蛋白质先在细胞质基质中合成","后转移(post-translational)：合成完成后转运","共转移(co-translational)：边合成边转运(入ER)"],"check":{"q":"关于蛋白质的共转移与后转移，叙述正确的是（　）","o":["A. 共转移在合成完成后进行，后转移边合成边进行","B. 共转移边合成边转运入ER，后转移在合成完成后再转运","C. 后转移专指蛋白质进入内质网","D. 两种方式都发生在细胞核内"],"a":"B","e":"蛋白质先在细胞质基质中合成，共转移边合成边进入ER，后转移则合成完成后再转运。","oe":["定义颠倒，共转移是边合成边转运。","蛋白质先在细胞质基质合成，共转移边合成边入ER，后转移合成完成后再转运。","进入ER的典型是共转移，后转移多指进入线粒体等。","蛋白质分选在细胞质与各细胞器间进行，不在核内。"]},"cards":[{"front":"蛋白质分选按转运时机分为哪两类？","back":"后转移：合成完成后转运；共转移：边合成边转运（入ER）","mnemonic":"先做完再走 vs 边走边做","type":"对比","useImg":false,"blank":"共转移","blank2":"后转移"}],"mem":"先做完再走 vs 边走边做","big":"assets/img/ch03/big/p030.jpg","terms":[{"t":"后转移","en":"post-translational translocation","d":"蛋白在胞质中完全合成后再转移进入ER；区别于边翻译边进入的共转移。"}]},{"i":27,"sec":"第二节 蛋白质分选","title":"信号肽与信号斑 (p32)","notes":"Signal peptides and signal patches：信号肽(线性氨基酸序列)和信号斑(由折叠后空间结构形成的信号)是蛋白质分选的两种信号形式。","page":32,"level":"掌握","img":"assets/img/ch03/p032.jpg","anim":null,"fig":"信号斑(信号 patch)是肽链折叠后在表面形成的三维结构，不是一段连续序列。例如溶酶体酶的三维构象形成信号斑，被 GlcNAc 磷酸转移酶识别加上 M6P。图对比了“线性信号序列”与“构象信号斑”。","points":["信号肽：线性氨基酸序列","信号斑：由折叠后空间结构形成的信号"],"check":{"q":"关于信号肽和信号斑的叙述，正确的是（　）","o":["A. 信号肽和信号斑都是线性氨基酸序列","B. 信号斑是线性序列，信号肽依赖空间结构","C. 两者均在蛋白质合成之前就已形成","D. 信号肽是线性氨基酸序列，信号斑由折叠后的空间结构形成"],"a":"D","e":"信号肽是线性氨基酸序列，信号斑由折叠后的空间结构形成，是蛋白质分选的两种信号形式。","oe":["信号斑依赖折叠后的空间结构，不是线性序列。","信号肽才是线性序列，信号斑依赖空间结构。","两者都需在肽链合成或折叠之后形成。","信号肽是线性序列，信号斑由折叠后空间构象形成，是两种分选信号形式。"]},"cards":[{"front":"蛋白质分选的两种信号形式是什么？","back":"信号肽：线性氨基酸序列；信号斑：折叠后空间结构形成的信号","mnemonic":"一线一斑","type":"对比","useImg":true,"blank":"信号肽","blank2":"信号斑"}],"mem":"一线一斑","big":"assets/img/ch03/big/p032.jpg"},{"i":28,"sec":"第二节 蛋白质分选","title":"信号序列的发现 (p33)","notes":"for the discovery that 'proteins have intrinsic signals that govern their transport and localization in the cell'——发现蛋白质具有决定其运输和定位的内在信号序列，获诺贝尔奖(Blobel)。\n\n【本页英文讲解】\n本页讲信号肽（signal sequence）的发现。Günter Blobel发现蛋白质具有决定其运输与定位的内在信号（intrinsic signals），据此提出信号假说，并获诺贝尔奖。信号序列如同蛋白质的“邮政编码”，决定其运输去向。此为蛋白质分选的核心概念与诺奖考点，见翟中和教材第八章蛋白质分选与膜泡运输。","page":33,"level":"掌握","img":"assets/img/ch03/p033.jpg","anim":null,"fig":null,"points":["Blobel发现蛋白质具有决定其运输和定位的内在信号","据此提出信号假说，获诺贝尔奖"],"check":{"q":"决定蛋白质在细胞内运输与定位的内在信号被称为？","o":["A. 分选信号(信号序列)，如同蛋白质的“邮政编码”","B. 启动子，决定基因转录的起始","C. 增强子，提高基因转录效率","D. 终止子，终止基因转录过程"],"a":"A","e":"蛋白质具有决定其运输和定位的内在信号序列，即分选信号，如同蛋白质的“邮政编码”。","oe":["对：笔记把该内在信号比作邮政编码","错：启动子为DNA元件，不符合本页所学概念","错：增强子调控转录效率，不符合本页所学概念","错：终止子不是蛋白质分选信号，不符合本页所学概念"],"basis":"蛋白质具有决定其运输和定位的内在信号"},"cards":[{"front":"谁因发现蛋白质内在信号序列而获诺贝尔奖？","back":"Blobel；发现蛋白质具有决定其运输和定位的内在信号序列","mnemonic":"Blobel=信号序列之父","type":"例证","useImg":false,"blank":"Blobel","blank2":"内在信号序列"}],"mem":"Blobel=信号序列之父","big":"assets/img/ch03/big/p033.jpg","terms":[{"t":"信号肽","en":"signal sequence / signal peptide","d":"蛋白N端一段决定其运输与定位的短序列，引导蛋白到ER后被切除。"}]},{"i":29,"sec":"第二节 蛋白质分选","title":"新生蛋白的靶向 (p34-35)","notes":"Newly made proteins are targeted to and imported into various organelles。许多遗传病中，蛋白质因分选信号异常而被错误定位。\n\n【本页英文讲解】\n本页讲新生蛋白的靶向（targeting）。新合成的蛋白质被靶向并导入各种细胞器（Newly made proteins are targeted to and imported into various organelles），这依赖其自身的分选信号。若分选信号异常，蛋白质会被错误定位，引起遗传病。考点：分选信号与疾病的关系，见教材第八章。","page":34,"level":"理解","img":"assets/img/ch03/p034.jpg","anim":null,"fig":null,"points":["信号肽位于 N 端，约 16–26 个氨基酸，中部为疏水核心。","N 端有带正电的极性区，C 端有信号肽酶识别位点。","信号肽在蛋白进入 ER 腔后被信号肽酶切除。"],"check":{"q":"若蛋白质的分选信号发生异常，最可能的后果是（　）","o":["A. 核糖体的结构发生改变","B. 蛋白质的合成速度显著加快","C. 蛋白质被错误定位，从而引起遗传病","D. 细胞膜的流动性明显增加"],"a":"C","e":"分选信号异常会使新生蛋白质被错误定位，这是许多遗传病的成因之一。","oe":["分选信号异常不引起核糖体结构改变。","分选信号影响蛋白定位，而不影响翻译速度。","分选信号异常会使新生蛋白被错误定位，是许多遗传病的成因。","信号异常影响蛋白定位，不直接改变膜的流动性。"]},"cards":null,"mem":"分选信号异常→蛋白错定位→遗传病","big":"assets/img/ch03/big/p034.jpg"},{"i":30,"sec":"第二节 蛋白质分选","title":"信号肽假说的提出 (p36)","notes":"1972年C.Milstein等从细胞中提取的免疫球蛋白分子N端比分泌到细胞外的免疫球蛋白N端多一截(信号肽)。1975年提出信号肽假说：N端信号肽引导蛋白进入ER。","page":36,"level":"掌握","img":"assets/img/ch03/p036.jpg","anim":"cotranslational","fig":null,"points":["1972年发现分泌型免疫球蛋白N端比成熟蛋白多一截(信号肽)","1975年提出信号肽假说：N端信号肽引导蛋白进入ER"],"check":{"q":"信号肽假说的核心内容是？","o":["A. C端信号肽引导蛋白返回细胞核","B. N端信号肽引导新生蛋白进入内质网","C. 信号肽仅在蛋白降解时起作用","D. 信号肽由线粒体DNA编码"],"a":"B","e":"1972年发现分泌蛋白N端多出一截，1975年提出信号肽假说，认为N端信号肽引导蛋白进入ER。","oe":["错：信号肽位于新生肽链的N端，不符合本页所学概念","对：与笔记“N端信号肽引导蛋白进入ER”一致","错：其功能是引导转运，不符合本页所学概念","错：信号肽由核基因编码，不符合本页所学概念"],"basis":"N端信号肽引导蛋白进入ER"},"cards":[{"front":"信号肽假说的核心内容是什么？","back":"1975年提出：N端信号肽引导蛋白进入ER；依据是分泌型免疫球蛋白N端多一截序列","mnemonic":"N端多一截，带路进ER","type":"定义","useImg":false,"blank":"信号肽","blank2":"N端信号肽"}],"mem":"N端多一截，带路进ER","big":"assets/img/ch03/big/p036.jpg"},{"i":31,"sec":"第二节 蛋白质分选","title":"信号序列引导蛋白 (p37)","notes":"Signal sequences direct proteins to the correct organelle——信号序列引导后面的蛋白到达正确细胞器。信号序列通常位于N端，完成使命后被切除。","page":37,"level":"掌握","img":"assets/img/ch03/p037.jpg","anim":null,"fig":"同一前体蛋白可含多种信号序列，按顺序被识别：先导肽引导入线粒体后切除，再暴露下一个信号引导到别处。图强调信号序列的“时序性”和“专一性”。","points":["信号序列引导蛋白到达正确细胞器","信号序列通常位于N端，完成使命后被切除"],"check":{"q":"关于信号序列的叙述，正确的是（　）","o":["A. 只在细胞核内发挥作用","B. 位于C端并在完成使命后保留","C. 引导蛋白质进入线粒体后转变为膜脂","D. 引导蛋白质到达正确细胞器，通常位于N端并在完成使命后被切除"],"a":"D","e":"信号序列引导后面的蛋白质到达正确细胞器，通常位于N端，完成使命后被切除。","oe":["信号序列可引导蛋白质进入多种细胞器，不限于核。","信号序列通常位于N端，且完成使命后被切除。","信号序列是肽段，不会转变为膜脂。","信号序列引导蛋白到达正确细胞器，通常位于N端，完成后被切除。"]},"cards":[{"front":"信号序列的功能是什么？","back":"引导蛋白到达正确细胞器；通常位于N端；完成任务后被切除","mnemonic":"N端车票，到站即撕","type":"功能","useImg":false,"blank":"N端","blank2":"细胞器"}],"mem":"N端车票，到站即撕","big":"assets/img/ch03/big/p037.jpg"},{"i":32,"sec":"第二节 蛋白质分选","title":"SRP信号识别颗粒 (p38)","notes":"信号识别颗粒(SRP)：由6种多肽和1个300核苷酸(7S)的RNA组成的核糖核蛋白复合物，通常在细胞质基质中。既与新生肽信号序列结合，又与核糖体大亚基结合，暂停翻译。","page":38,"level":"掌握","img":"assets/img/ch03/p038.jpg","anim":"srp_cycle","fig":null,"points":["由6种多肽和1个7S RNA组成的核糖核蛋白复合物","既与新生肽信号序列结合，又与核糖体大亚基结合，暂停翻译"],"check":{"q":"关于信号识别颗粒(SRP)，下列叙述正确的是？","o":["A. 由6种多肽和1个7S RNA组成的核糖核蛋白，可结合信号序列并暂停翻译","B. 由三脚蛋白复合体(triskelion)组装而成","C. 属于酸性水解酶，最适pH约为5","D. 是一种位于ER膜上的GTP结合蛋白"],"a":"A","e":"SRP为6种多肽加7S RNA的核糖核蛋白，结合信号肽并暂停翻译。","oe":["SRP为6肽加7S RNA的核糖核蛋白，结合信号肽暂停翻译","triskelion是网格蛋白的组成形式","酸性水解酶是溶酶体的酶，与SRP无关","SRP位于细胞质基质，并非ER膜GTP酶"]},"cards":[{"front":"SRP由什么组成？","back":"6种多肽 + 1个300核苷酸(7S)RNA；核糖核蛋白复合物；位于细胞质基质","mnemonic":"六肽一RNA，7S记牢","type":"组成数字","useImg":false,"blank":"核糖核蛋白复合物"},{"front":"SRP结合什么并产生什么效应？","back":"结合新生肽信号序列和核糖体大亚基；暂停翻译","mnemonic":"双结合，踩刹车","type":"功能","useImg":false,"blank":"信号序列","blank2":"核糖体大亚基"}],"mem":"六肽一RNA，7S记牢","big":"assets/img/ch03/big/p038.jpg"},{"i":33,"sec":"第二节 蛋白质分选","title":"SRP受体(停泊蛋白) (p39)","notes":"信号识别颗粒受体(SRP receptor)，又称停泊蛋白DP(docking protein)：位于内质网膜上，与SRP结合使核糖体停泊到ER膜上。\n\n【本页英文讲解】\n本页讲信号识别颗粒受体（SRP receptor），又称停泊蛋白DP（docking protein）。它位于内质网膜上，能与信号识别颗粒（SRP，signal recognition particle）结合，使携有信号肽的核糖体停泊到ER膜上，进而启动共翻译转运。考点：SRP与SRP受体在蛋白质靶向ER中的作用，见教材第八章。","page":39,"level":"掌握","img":"assets/img/ch03/p039.jpg","anim":null,"fig":"SRP 受体位于 rER 膜上，由 α、β 两个亚基组成。α 亚基结合 SRP，使核糖体停泊到膜上。图中 SRP-核糖体复合体与 SRP 受体结合，是“翻译暂停→停泊→继续翻译”的关键一步。","points":["又称停泊蛋白DP，位于内质网膜上","与SRP结合使核糖体停泊到ER膜上"],"check":{"q":"信号识别颗粒受体(SRP受体)又称（　）","o":["A. 钙泵，位于ER膜上把Ca2+泵入ER腔","B. 信号肽酶，位于胞质中切除信号肽","C. 易位子，位于核膜上介导核孔运输","D. 停泊蛋白DP，位于内质网膜上，与SRP结合使核糖体停泊"],"a":"D","e":"SRP受体又称停泊蛋白DP，位于内质网膜上，与SRP结合使核糖体停泊到ER膜上。","oe":["钙泵负责储钙，与SRP受体的功能无关。","信号肽酶负责切除信号肽，与SRP受体功能不同。","易位子是肽链通道，位于ER膜而非核膜，不是SRP受体。","SRP受体又称停泊蛋白DP，位于ER膜，结合SRP使核糖体停泊到ER膜上。"]},"cards":[{"front":"SRP受体又称什么？位于何处？作用是什么？","back":"又称停泊蛋白DP；位于内质网膜上；与SRP结合使核糖体停泊到ER膜","mnemonic":"ER膜上的码头，接SRP靠岸","type":"定位","useImg":true,"blank":"停泊蛋白DP","blank2":"内质网膜"}],"mem":"ER膜上的码头，接SRP靠岸","big":"assets/img/ch03/big/p039.jpg"},{"i":34,"sec":"第二节 蛋白质分选","title":"SRP与信号肽结合 (p40)","notes":"As a signal sequence emerges from the ribosome and binds to the SRP：信号肽从核糖体伸出→结合SRP→翻译暂停→SRP-核糖体复合物结合ER膜上的SRP受体→翻译恢复，肽链进入ER腔。","page":40,"level":"掌握","img":"assets/img/ch03/p040.jpg","anim":null,"fig":"SRP 与 SRP 受体都具 GTP 酶活性；GTP 水解后 SRP 从受体和信号肽上释放，翻译恢复，肽链经易位子进入 ER。图展示 SRP 的“结合—停泊—释放”循环，可重复使用。","points":["信号肽从核糖体伸出→结合SRP→翻译暂停","SRP-核糖体复合物结合ER膜上的SRP受体→翻译恢复，肽链进入ER腔"],"check":{"q":"信号肽从核糖体伸出后，正确的过程是（　）","o":["A. 直接进入ER腔，翻译过程并不暂停","B. 结合SRP使翻译暂停，复合物结合ER膜上SRP受体后翻译恢复","C. 结合SRP后翻译加速并直接进入细胞核","D. 被信号肽酶立即切除后再继续翻译"],"a":"B","e":"信号肽结合SRP使翻译暂停，SRP-核糖体复合物结合ER膜上的SRP受体后翻译恢复。","oe":["信号肽先结合SRP使翻译暂停，并非直接进入ER。","信号肽结合SRP使翻译暂停，复合物结合ER膜上SRP受体后翻译恢复。","该过程进入内质网而非细胞核，且翻译先暂停。","信号肽在肽链进入ER腔后才被信号肽酶切除。"]},"cards":[{"front":"信号肽引导肽链入ER腔的完整流程？","back":"信号肽伸出核糖体→结合SRP→翻译暂停→复合物结合ER膜SRP受体→翻译恢复→肽链入ER腔","mnemonic":"伸—结—停—泊—复—入","type":"流程","useImg":true,"blank":"信号肽","blank2":"SRP受体"}],"mem":"伸—结—停—泊—复—入","big":"assets/img/ch03/big/p040.jpg"},{"i":35,"sec":"第二节 蛋白质分选","title":"信号肽假说内容 (p41)","notes":"信号肽假说：①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽被SRP识别结合→翻译暂停；②SRP-核糖体复合物结合ER膜上SRP受体→核糖体附着ER；③翻译恢复，肽链穿膜入ER腔；④信号肽被信号肽酶切除，蛋白继续折叠。","page":41,"level":"掌握","img":"assets/img/ch03/p041.jpg","anim":null,"fig":null,"points":["Blobel 提出信号肽假说(获诺贝尔奖)：信号肽引导核糖体到 ER，蛋白边翻译边进入 ER(共翻译转运)。","实验证据：Milstein 等发现 IgG 轻链先合成带信号肽的前体，进入 ER 后被切除。","共翻译转运：翻译与穿膜同时进行；翻译后转运：翻译完成后才跨膜。"],"check":{"q":"按照信号肽假说，下列过程顺序正确的是？","o":["A. 翻译全部完成→信号肽引导成熟蛋白进入ER","B. SRP直接催化肽链折叠并切除信号肽","C. 信号肽被SRP识别→结合ER膜SRP受体→翻译恢复肽链穿膜→信号肽被切除","D. 信号肽在ER腔被切除→肽链再进入细胞质→SRP使其复位"],"a":"C","e":"信号肽假说：SRP识别→结合ER受体→翻译恢复穿膜→信号肽切除。","oe":["信号引导的是边翻译边穿膜的共翻译转运","SRP只识别结合信号肽，不催化折叠与切除","此顺序符合信号肽假说的四个步骤","错误：信号肽在肽链穿膜进入ER腔后才被信号肽酶切除"]},"cards":[{"front":"信号肽假说的四个要点？","back":"①游离核糖体合成至约80aa，N端信号肽被SRP识别，翻译暂停；②复合物结合ER膜SRP受体，核糖体附着ER；③翻译恢复，肽链穿膜入ER腔；④信号肽被信号肽酶切除，蛋白折叠","mnemonic":"游离起、SRP停、受体泊、切肽折","type":"流程","useImg":false,"blank":"信号肽","blank2":"信号肽酶"}],"mem":"游离起、SRP停、受体泊、切肽折","big":"assets/img/ch03/big/p041.jpg"},{"i":36,"sec":"第二节 蛋白质分选","title":"分泌蛋白的共翻译转移 (p42)","notes":"ER lumen/cytosol：分泌蛋白在游离核糖体起始合成→信号肽引导→附着rER→共翻译转移入ER腔。\n\n【本页英文讲解】\n本页讲分泌蛋白（secretory protein）的共翻译转移（co-translational translocation）。分泌蛋白在游离核糖体上起始合成，信号肽引导核糖体附着到粗面内质网（rER），新生肽链边合成边经易位子转移入内质网腔（ER lumen），而非留在胞质（cytosol）。考点：共翻译转运的步骤，见翟中和教材第八章。","page":42,"level":"掌握","img":"assets/img/ch03/p042.jpg","anim":null,"fig":null,"points":["分泌蛋白在游离核糖体起始合成","信号肽引导核糖体附着rER","边合成边经易位子转移入ER腔"],"check":{"q":"分泌蛋白共翻译转移的最终去向是（　）","o":["A. 翻译完成后留在胞质溶胶中","B. 先进入细胞核再分泌到胞外","C. 直接进入线粒体基质","D. 边合成边经易位子进入内质网腔"],"a":"D","e":"分泌蛋白在游离核糖体起始合成，信号肽引导附着rER，边合成边经易位子进入ER腔。","oe":["分泌蛋白经共翻译转移进入ER腔，不停留在胞质。","分泌蛋白的去向是内质网腔或胞外，并不进入细胞核。","分泌蛋白的去向是ER腔，而不是线粒体基质。","分泌蛋白在游离核糖体起始合成，信号肽引导附着rER，边合成边经易位子入ER腔。"]},"cards":[{"front":"分泌蛋白如何进入ER腔？","back":"游离核糖体起始合成→信号肽引导→附着rER→共翻译转移入ER腔","mnemonic":"边合成边进门","type":"流程","useImg":true,"blank":"共翻译转移","blank2":"游离核糖体"}],"mem":"边合成边进门","big":"assets/img/ch03/big/p042.jpg","terms":[{"t":"共翻译转移","en":"co-translational translocation","d":"肽链在核糖体上边合成边经易位子进入内质网腔的方式。"},{"t":"分泌蛋白","en":"secretory protein","d":"合成后进入ER、经内膜系统分泌到细胞外的蛋白。"},{"t":"胞质溶胶","en":"cytosol","d":"细胞膜以内、各种细胞器以外的液态基质。"}]},{"i":37,"sec":"第二节 蛋白质分选","title":"起始转移序列 (p43)","notes":"蛋白质跨膜相关概念。开始/起始转移序列(start transfer sequence)：蛋白质的信号序列，除了作为信号被识别外，还能启动肽链穿膜转移。","page":43,"level":"掌握","img":"assets/img/ch03/p043.jpg","anim":null,"fig":"起始转移序列(信号肽)既引导核糖体到膜上，又作为跨膜的“起始”信号，使肽链穿入 ER 腔。若同时还有停止转移序列，则形成单次跨膜蛋白。","points":["信号序列除作为信号被识别外，还能启动肽链穿膜转移"],"check":{"q":"关于起始转移序列的叙述，正确的是（　）","o":["A. 它既是信号序列，又能启动肽链穿膜转移","B. 它只能被信号肽酶识别，不能启动穿膜","C. 它使翻译停止并使肽链被降解","D. 它位于肽链C端并保留在胞质中"],"a":"A","e":"起始转移序列除作为信号被识别外，还能启动肽链穿膜转移。","oe":["起始转移序列除作为信号被识别外，还能启动肽链穿膜转移。","起始转移序列能启动穿膜，不只是被信号肽酶识别。","它启动转移而非使翻译停止或降解肽链。","该序列位于N端并引导穿膜，不在C端。"]},"cards":[{"front":"起始转移序列的定义？","back":"蛋白质的信号序列；除被识别外，还能启动肽链穿膜转移","mnemonic":"信号+启动穿膜，二合一","type":"定义","useImg":false,"blank":"信号序列","blank2":"肽链穿膜转移"}],"mem":"信号+启动穿膜，二合一","big":"assets/img/ch03/big/p043.jpg"},{"i":38,"sec":"第二节 蛋白质分选","title":"停止转移序列 (p44)","notes":"停止转移序列(stop transfer sequence)：肽链中某些序列与内质网膜有很强亲和力，紧密结合在膜脂双层中而不转移，使肽链停止穿膜，形成跨膜段。","page":44,"level":"掌握","img":"assets/img/ch03/p044.jpg","anim":null,"fig":"停止转移序列是一段约 20 个氨基酸的疏水序列，能“叫停”穿膜并使肽链锚定在膜上。图中起始转移序列＋停止转移序列 → 单次跨膜蛋白；只有起始序列 → 可溶性蛋白进入腔内。","points":["与内质网膜有很强亲和力，紧密结合在膜脂双层中","使肽链停止穿膜，形成跨膜段"],"check":{"q":"关于停止转移序列的叙述，正确的是（　）","o":["A. 被信号肽酶切除后肽链进入胞质","B. 与内质网膜有强亲和力，使肽链停止穿膜并形成跨膜段","C. 位于肽链N端并启动翻译起始","D. 促使肽链继续穿膜并完全进入ER腔"],"a":"B","e":"停止转移序列与内质网膜有很强的亲和力，使肽链停止穿膜，形成跨膜段。","oe":["停止转移序列不被切除，而是成为跨膜段。","停止转移序列与内质网膜有强亲和力，使肽链停止穿膜并形成跨膜段。","它位于肽链内部，不参与翻译起始。","它使穿膜停止，而不是促使肽链继续进入ER腔。"]},"cards":[{"front":"停止转移序列的定义与作用？","back":"与内质网膜强亲和力的序列；紧密结合膜脂双层不转移；使肽链停止穿膜，形成跨膜段","mnemonic":"粘住膜，刹车成跨膜段","type":"定义","useImg":true,"blank":"停止转移序列"}],"mem":"粘住膜，刹车成跨膜段","big":"assets/img/ch03/big/p044.jpg"},{"i":39,"sec":"第二节 蛋白质分选","title":"可溶性蛋白的转运 (p45)","notes":"可溶性蛋白(soluble protein)转运穿过ER膜到达ER腔：一种多肽只有N端信号序列(开始转移序列)、无停止序列→此蛋白完全进入ER腔成为可溶性蛋白。","page":45,"level":"掌握","img":"assets/img/ch03/p045.jpg","anim":null,"fig":"可溶性分泌蛋白只有起始转移序列，肽链完全穿过易位子进入 ER 腔，信号肽被切除。图对比可溶性蛋白与膜蛋白在易位子中的走向差异。","points":["只有N端信号序列(起始转移序列)、无停止序列","此蛋白完全进入ER腔，成为可溶性蛋白"],"check":{"q":"转运后完全进入ER腔成为可溶性蛋白的多肽，其结构特点是？","o":["A. 只有停止转移序列，不含N端信号序列","B. 只有N端信号序列(开始转移序列)，无停止转移序列","C. 同时含开始转移序列和停止转移序列","D. 两种序列都不含，靠自由扩散进入ER腔"],"a":"B","e":"仅有N端开始转移序列而无停止序列的多肽完全进入ER腔成可溶蛋白。","oe":["错误：缺少N端信号序列便无法启动肽链转移，不能进入ER","无停止序列故肽链完全进入ER腔","含停止序列会形成跨膜蛋白而非可溶性蛋白","错误：没有信号序列的蛋白不能定向转运进入ER腔"]},"cards":[{"front":"可溶性蛋白如何完全进入ER腔？","back":"只有N端信号序列（开始转移序列）、无停止序列；多肽完全转入ER腔成为可溶性蛋白。","mnemonic":"有头无尾，全进腔","type":"流程","useImg":true,"blank":"可溶性蛋白","blank2":"停止序列"}],"mem":"有头无尾，全进腔","big":"assets/img/ch03/big/p045.jpg"},{"i":40,"sec":"第二节 蛋白质分选","title":"跨膜蛋白的形成 (p46)","notes":"蛋白质N端有ER起始信号序列启动转移，中部还含终止转移序列。N端信号序列被切除，停止转移序列使蛋白锚在ER膜上→形成单次跨膜蛋白。","page":46,"level":"掌握","img":"assets/img/ch03/p046.jpg","anim":"transmembrane_topology","fig":null,"points":["N端有起始信号启动转移，中部含终止转移序列","N端信号被切除，停止序列使蛋白锚在ER膜上→单次跨膜蛋白"],"check":{"q":"肽链转移中，若同时含N端信号序列和中部停止转移序列，将形成？","o":["A. 单次跨膜蛋白","B. 分泌到细胞外的成熟蛋白","C. 完全进入ER腔的可溶性蛋白","D. 停留在细胞质基质的游离蛋白"],"a":"A","e":"N端信号序列加中部停止序列，切除信号后锚定膜上形成单次跨膜蛋白。","oe":["停止序列使肽链锚定于ER膜，形成单次跨膜蛋白","分泌蛋白需完全进入ER腔再外运","错误：完全进入ER腔的可溶性蛋白不含停止转移序列","该肽链已进入ER膜，不会停留胞质"]},"cards":[{"front":"单次跨膜蛋白如何形成？","back":"N端起信号序列启动转移；中部终止转移序列使肽链锚在ER膜上；N端信号被切除。","mnemonic":"头切尾锚，一次穿膜","type":"流程","useImg":true,"blank":"终止转移序列","blank2":"N端起信号序列"}],"mem":"头切尾锚，一次穿膜","big":"assets/img/ch03/big/p046.jpg"},{"i":41,"sec":"第二节 蛋白质分选","title":"多次跨膜蛋白 (p47)","notes":"一个内部的起始转移信号起起始转运作用并启动肽链转移；起始序列和停止序列都不被切除，整个多肽链作为穿膜两次的跨膜蛋白——多次跨膜蛋白的形成机制。","page":47,"level":"掌握","img":"assets/img/ch03/p047.jpg","anim":null,"fig":"跨膜蛋白的拓扑(穿膜次数、N/C 端朝向)由肽链中起始转移序列和停止转移序列的数目与位置决定。图给出单次、多次跨膜蛋白的几种拓扑类型，是理解膜蛋白结构的关键。","points":["内部的起始转移信号启动肽链转移","起始序列和停止序列都不被切除→穿膜两次的多次跨膜蛋白"],"check":{"q":"关于多次跨膜蛋白形成的叙述，正确的是（　）","o":["A. 起始转移序列被切除后形成单次跨膜蛋白","B. 内部起始转移序列启动转移，起始与停止序列均不被切除，肽链穿膜两次","C. 停止转移序列被切除后才可能多次跨膜","D. 由多条独立肽链拼接组装而成"],"a":"B","e":"内部起始转移信号启动转运且不被切除，与停止序列配合使整个多肽链穿膜两次。","oe":["起始序列不被切除，且该情形形成两次跨膜而非单次。","内部起始转移信号启动转运且不被切除，与停止序列配合使多肽链穿膜两次。","停止序列不被切除，而是形成跨膜段。","多次跨膜蛋白由一条多肽链反复穿膜形成，非多链拼接。"]},"cards":[{"front":"多次跨膜蛋白的形成机制是什么？","back":"内部起始转移信号启动转运；起始序列和停止序列均不被切除；肽链穿膜两次形成多次跨膜蛋白。","mnemonic":"内起不切，来回穿梭","type":"流程","useImg":true,"blank":"多次跨膜蛋白","blank2":"内部起始转移信号"}],"mem":"内起不切，来回穿梭","big":"assets/img/ch03/big/p047.jpg"},{"i":42,"sec":"第二节 蛋白质分选","title":"翻译后加工 (p48)","notes":"翻译完毕的蛋白多肽链必须经过后期蛋白修饰加工才能具备功能：折叠、磷酸化、糖基化修饰等。","page":48,"level":"掌握","img":"assets/img/ch03/p048.jpg","anim":null,"fig":null,"points":["翻译完毕的肽链须经后期修饰加工才具功能","包括折叠、磷酸化、糖基化等"],"check":{"q":"翻译完毕的多肽链通常还需要经过哪类过程才能成为有功能的成熟蛋白质？","o":["A. 无需任何加工即自动具备全部功能","B. 后期修饰加工，如折叠、磷酸化、糖基化等","C. 仅需切除信号肽即可具备功能","D. 必须重新水解为氨基酸后再合成"],"a":"B","e":"翻译完毕的蛋白多肽链必须经过后期蛋白修饰加工（如折叠、磷酸化、糖基化等）才能具备功能。","oe":["新生肽链一般需加工折叠才具功能，并非自动具备，错误。","正确，后期修饰加工包括折叠、磷酸化、糖基化等。","信号肽切除只是加工之一，单独切除不足以致功能，错误。","成熟加工并非把蛋白水解为氨基酸再重新合成，错误。"]},"cards":[{"front":"翻译后的多肽链为何需要加工？","back":"新生肽链须经折叠、磷酸化、糖基化等翻译后修饰才能具备功能。","mnemonic":"裸链无用，修饰成才","type":"功能","useImg":false,"blank":"翻译后修饰","blank2":"折叠"}],"mem":"裸链无用，修饰成才","big":"assets/img/ch03/big/p048.jpg"},{"i":43,"sec":"第二节 蛋白质分选","title":"rER的糖基化 (p49)","notes":"rER的功能：蛋白质修饰(post-translational modifications)——糖基化(glycosylation)，主要发生N-连接糖基化。\n\n【本页英文讲解】\n本页讲粗面内质网（rER）的糖基化功能。rER可对蛋白质进行翻译后修饰（post-translational modifications），其中主要是糖基化（glycosylation），且以N-连接糖基化为主，即糖链连接在天冬酰胺残基的酰胺氮上。糖基化有助于蛋白质正确折叠、稳定与分选。考点：N-连接与O-连接糖基化的区别，见教材第七章。","page":49,"level":"掌握","img":"assets/img/ch03/p049.jpg","anim":"n_glycosylation","fig":null,"points":["rER对蛋白进行翻译后修饰，主要是糖基化","以N-连接糖基化为主"],"check":{"q":"粗面内质网对蛋白质最主要的翻译后修饰是？","o":["A. 泛素化","B. N-连接糖基化","C. 磷酸化","D. O-连接糖基化"],"a":"B","e":"rER以N-连接糖基化为主，糖链连接在Asn残基上。","oe":["泛素化是蛋白质降解标记，非rER主要修饰","rER以N-连接糖基化为主，连于Asn残基","磷酸化不是rER对蛋白的主要修饰方式","错误：O-连接糖基化起始于高尔基体，不是rER主要修饰"]},"cards":[{"front":"rER的主要蛋白修饰功能是什么？","back":"糖基化修饰，主要为N-连接糖基化。","mnemonic":"粗面内质网，N糖加工厂","type":"功能","useImg":false,"blank":"糖基化修饰","blank2":"N-连接糖基化"}],"mem":"粗面内质网，N糖加工厂","big":"assets/img/ch03/big/p049.jpg"}],"mcq":[{"id":"ch03_mcq_1","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内膜系统不包括下列哪个？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 线粒体"],"a":"D","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成(ER/高尔基/溶酶体/内体/液泡/分泌小泡)；线粒体虽具膜但不属内膜系统。","kp":"ch03_s0_2","oe":["内质网是内膜系统的核心成员，属于内膜系统。","高尔基体由单层膜构成且起源上与ER相关，属于内膜系统。","溶酶体由单层膜包被且起源于高尔基体，属于内膜系统。","线粒体虽具膜，但不属于内膜系统，故为答案。"]},{"id":"ch03_mcq_2","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"粗面内质网(rER)的主要功能是？","o":["A. 合成脂类","B. 合成分泌蛋白和膜蛋白(膜上有核糖体)","C. 解毒","D. 储钙"],"a":"B","e":"rER膜表面有大量核糖体，合成分泌性蛋白和多种膜蛋白；sER无核糖体，合成脂类、解毒、储钙。","kp":"ch03_s0_10","oe":["合成脂类主要是光面内质网的功能，不是rER。","rER膜上附有核糖体，合成分泌蛋白和膜蛋白。","解毒是sER的功能，不是rER的主要功能。","储钙是sER的功能，不属于rER。"]},{"id":"ch03_mcq_3","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"光面内质网(sER)的功能不包括？","o":["A. 解毒","B. 储钙","C. 合成膜脂","D. 合成分泌蛋白"],"a":"D","e":"sER功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。合成分泌蛋白是rER功能。","kp":"ch03_s0_9","oe":["解毒是sER的功能，如在肝细胞中。","储钙是sER的功能，ER是细胞内重要钙库。","合成膜脂(甘油磷脂、胆固醇)是sER的功能。","合成分泌蛋白是rER的功能，不属于sER，故为答案。"]},{"id":"ch03_mcq_4","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"易位子(translocon)位于？","o":["A. 高尔基体膜","B. 粗面内质网膜","C. 溶酶体膜","D. 线粒体外膜"],"a":"B","e":"易位子是rER膜上的蛋白复合体(核心为Sec61复合体)，中心有2nm孔道，新生肽链由此进入ER腔。","kp":"ch03_s0_19","oe":["易位子位于内质网膜，不在高尔基体膜上。","易位子位于粗面内质网膜，核心为Sec61复合体。","易位子不在溶酶体膜，溶酶体蛋白由运输小泡送入。","线粒体外膜蛋白靠TOM等复合体转运，不是易位子。"]},{"id":"ch03_mcq_5","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号识别颗粒(SRP)的组成是？","o":["A. 6种多肽+1个7S RNA","B. 仅蛋白质","C. 仅RNA","D. 糖蛋白"],"a":"A","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，既结合信号肽又结合核糖体大亚基，暂停翻译。","kp":"ch03_s0_32","oe":["SRP由6种多肽和1个7S RNA组成。","SRP含有RNA，并非仅由蛋白质组成。","SRP含有蛋白质，并非仅由RNA组成。","SRP是核糖核蛋白，不是糖蛋白。"]},{"id":"ch03_mcq_6","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号肽假说中,肽链转移进入ER腔的机制是？","o":["A. 翻译后转移","B. 边翻译边转移(共翻译转移)","C. 胞吞","D. 自由扩散"],"a":"B","e":"分泌蛋白在游离核糖体起始合成→信号肽被SRP识别→附着ER→共翻译转移入ER腔，信号肽被切除。","kp":"ch03_s0_35","oe":["分泌蛋白入ER是边翻译边转移，不是翻译后转移。","肽链进入ER腔为共翻译转移，即边翻译边转移。","胞吞是摄取外源物质的方式，与肽链入ER无关。","自由扩散是小分子运输方式，不适用于肽链入ER。"]},{"id":"ch03_mcq_7","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"可溶性蛋白进入ER腔的条件是？","o":["A. 只有N端信号序列,无停止转移序列","B. 含停止转移序列","C. 无信号序列","D. 含多个起始序列"],"a":"A","e":"只含N端信号序列(开始转移序列)、无停止序列→蛋白完全进入ER腔成可溶性蛋白；有停止序列则锚在膜上成跨膜蛋白。","kp":"ch03_s0_39","oe":["只有N端信号序列而无停止转移序列，蛋白完全进入ER腔。","含停止转移序列的蛋白会锚定在膜上，成为跨膜蛋白。","无信号序列的蛋白不能进入ER腔。","含多个起始序列的说法与可溶性蛋白入腔机理不符。"]},{"id":"ch03_mcq_8","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"N-连接糖基化与O-连接糖基化的区别,错误的是？","o":["A. N-连接起始于rER,O-连接在高尔基体","B. N-连接结合Asn,O-连接结合Ser/Thr","C. N-连接来自同一寡糖前体","D. O-连接起始于内质网"],"a":"D","e":"O-连接糖基化在高尔基体进行，单糖逐个加到Ser/Thr羟基上；N-连接起始于rER，结合Asn，来自同一寡糖前体。","kp":"ch03_s0_43","oe":["N-连接起始于rER，O-连接在高尔基体，该说法正确。","N-连接结合Asn，O-连接结合Ser/Thr，该说法正确。","N-连接糖链来自同一寡糖前体，该说法正确。","O-连接糖基化在高尔基体起始，而非起始于内质网，故错误。"]},{"id":"ch03_mcq_9","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"催化ER腔内二硫键形成的酶是？","o":["A. PDI","B. Bip","C. SRP","D. Hsp70"],"a":"A","e":"PDI(蛋白二硫键异构酶)是ER驻留蛋白，催化二硫键形成与重排。Bip是分子伴侣识别错误折叠蛋白。","kp":"ch03_s0_12","oe":["PDI是ER驻留蛋白，催化二硫键的形成与重排。","Bip是分子伴侣，识别错误折叠蛋白，不催化二硫键。","SRP负责识别信号肽并暂停翻译，不催化二硫键。","Hsp70是分子伴侣，无二硫键异构酶活性。"]},{"id":"ch03_mcq_10","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"Bip蛋白的功能是？","o":["A. 催化二硫键","B. 识别未正确折叠/未组装的蛋白,帮助折叠","C. 合成脂类","D. 切除信号肽"],"a":"B","e":"Bip(binding protein)是ER驻留分子伴侣，识别不正确折叠或未组装的蛋白，防止聚集并帮助折叠。","kp":"ch03_s0_18","oe":["催化二硫键形成的是PDI，不是Bip。","Bip是ER驻留分子伴侣，识别未正确折叠或未组装的蛋白并帮助折叠。","合成脂类由sER完成，不是Bip的功能。","切除信号肽由信号肽酶完成，不是Bip。"]},{"id":"ch03_mcq_11","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内质网驻留蛋白的驻留信号是？","o":["A. KDEL序列","B. M6P","C. NLS","D. NES"],"a":"A","e":"Bip、PDI等ER驻留蛋白含C端KDEL(内质网驻留信号)，被保留在ER中。M6P是溶酶体分选信号。","kp":"ch03_s0_9","oe":["ER驻留蛋白C端的KDEL序列是其内质网驻留信号。","M6P是溶酶体酶的分选信号，不是ER驻留信号。","NLS是核定位信号，引导蛋白进入细胞核。","NES是核输出信号，与ER驻留无关。"]},{"id":"ch03_mcq_12","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"2004年诺贝尔化学奖授予的发现是？","o":["A. 泛素介导的蛋白质降解","B. 水通道","C. RNAi","D. 端粒酶"],"a":"A","e":"2004年诺贝尔化学奖授予Ciechanover、Hershko、Rose，发现泛素介导的蛋白质降解。","kp":"ch03_s0_28","oe":["2004年诺贝尔化学奖表彰发现泛素介导的蛋白质降解。","水通道研究获2003年诺贝尔化学奖，年份不符。","RNAi研究获2006年诺贝尔生理学或医学奖，非化学奖。","端粒酶研究获2009年诺贝尔生理学或医学奖，非化学奖。"]}],"judge":[{"id":"ch03_judge_1","modI":0,"q":"内膜系统包括内质网、高尔基体、溶酶体，但不包括线粒体和叶绿体。","a":"对","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成；线粒体、叶绿体不属内膜系统。","kp":"ch03_s0_2","oe":["内膜系统由单层膜包被、结构与功能相关的细胞器组成，不含线粒体、叶绿体。","误把线粒体、叶绿体也列入内膜系统，因其为双层膜细胞器，故判错。"]},{"id":"ch03_judge_2","modI":0,"q":"粗面内质网表面附着大量核糖体，主要合成分泌蛋白和膜蛋白。","a":"对","e":"rER膜上有核糖体与易位子，合成分泌蛋白和膜蛋白；sER无核糖体。","kp":"ch03_s0_9","oe":["粗面内质网膜上附着核糖体与易位子，合成分泌蛋白和膜蛋白。","误以为核糖体附着于高尔基体或sER，混淆粗面与光面内质网，故判错。"]},{"id":"ch03_judge_3","modI":0,"q":"光面内质网的功能包括解毒、储钙和合成膜脂。","a":"对","e":"sER三大功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。","kp":"ch03_s0_13","oe":["光面内质网具解毒、储钙(Ca库)和合成膜脂三大功能。","误将解毒储钙归为粗面内质网功能，或否认其合成膜脂，故判错。"]},{"id":"ch03_judge_4","modI":0,"q":"易位子(translocon)位于高尔基体膜上，介导蛋白质进入高尔基体腔。","a":"错","e":"易位子位于粗面内质网(rER)膜上，核心为Sec61复合体，介导新生肽链进入ER腔。","kp":"ch03_s0_19","oe":["若以为易位子在高尔基体膜上则判对，混淆了蛋白质转运位点。","易位子位于粗面内质网膜上，核心为Sec61复合体，介导肽链进入ER腔。"]}],"fill":[{"id":"ch03_fill_1","modI":0,"q":"内膜系统是在结构、功能乃至发生上相关的、由________膜围绕成的细胞器,包括内质网、________、溶酶体等。","a":"单层,高尔基体","kp":"ch03_s0_2","oe":["内膜系统各细胞器均由单层膜包被，区别于双层膜的线粒体和核膜。","高尔基体属内膜系统，参与蛋白质加工、分选和运输，故为答案。"]},{"id":"ch03_fill_2","modI":0,"q":"粗面内质网表面分布大量________,主要合成分泌蛋白；光面内质网的功能有解毒、储钙和________。","a":"核糖体,合成膜脂","kp":"ch03_s0_9","oe":["粗面内质网表面附着大量核糖体，是合成分泌蛋白和膜蛋白的场所。","光面内质网能合成磷脂、胆固醇等膜脂，故第三空填合成膜脂。"]},{"id":"ch03_fill_3","modI":0,"q":"rER膜上的蛋白复合体________(核心为Sec61)中心有直径2nm孔道,使新生肽链进入ER腔。","a":"易位子(translocon)","kp":"ch03_s0_21","oe":["易位子位于rER膜上，由Sec61构成孔道，供新生肽链进入ER腔。"]},{"id":"ch03_fill_12","modI":0,"q":"内质网驻留蛋白Bip和PDI属于________,其中PDI催化________的形成。","a":"分子伴侣(ER驻留蛋白),二硫键","kp":"ch03_s0_40","oe":["Bip和PDI是内质网驻留的分子伴侣，协助蛋白折叠并防止聚集。","PDI催化肽链半胱氨酸间二硫键的形成与重排，故填二硫键。"]}],"short":[{"id":"ch03_short_2","modI":0,"q":"简述内质网的功能。","a":"内质网分粗面内质网(rER)和光面内质网(sER)：\n\n【rER功能】\n①蛋白质合成——膜上有易位子，新生肽链共翻译转移入ER腔；\n②蛋白质的N-连接糖基化修饰；\n③新生多肽的折叠与装配(二硫键形成，PDI催化)；\n④蛋白质质量监控(只有正确折叠的蛋白才能离开ER)；\n⑤错误折叠蛋白经ERAD途径降解。\n\n【sER功能】\n①解毒(肝细胞，细胞色素P450)；\n②储钙(Ca库，Ca2+-ATPase泵入Ca2+，参与信号传递)；\n③合成膜脂(甘油磷脂和胆固醇)。\n\n【其他】\nER是内膜系统的重要组分，膜脂在ER合成后运往其他膜；ER驻留蛋白含KDEL信号。","kp":"ch03_s0_11"}],"calc":[{"id":"ch03_calc_1","modI":0,"q":"论述内膜系统的组成、膜泡运输途径及其生物学意义。","a":"内膜系统是真核细胞分室化的结构基础,膜泡运输实现区室间物质交流","steps":"【组成】\n由单层膜围绕、结构功能发生上相关的细胞器：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)。\n\n【膜泡运输途径】\n①分泌途径(向外)：ER→高尔基体(CGN→中间→TGN)→分泌小泡→质膜/胞外或溶酶体；\n②胞吞途径(向内)：质膜→早期胞内体→晚期胞内体→溶酶体；\n③回收途径：逃逸蛋白经COPI小泡返回ER。\n\n【意义】\n①实现细胞分室化，各细胞器功能专一、效率高；\n②完成蛋白质的合成、加工、分选和运输(分泌蛋白、膜蛋白、溶酶体酶)；\n③实现物质的摄取(胞吞)与降解(溶酶体)；\n④维持细胞器膜的特性和动态平衡；\n⑤是真核细胞比原核细胞复杂高效的根本原因。","kp":"ch03_s0_0"},{"id":"ch03_calc_2","modI":0,"q":"论述内质网的蛋白质质量监控体系及其意义。","a":"ER质量监控确保只有正确折叠的蛋白才能离开ER,错误蛋白被降解","steps":"【监控体系组成】\n①分子伴侣：Bip(识别错误折叠/未组装蛋白)、Hsp70家族；\n②折叠酶：PDI(催化二硫键形成与重排)；\n③糖基化系统：N-连接糖基化参与折叠监控；\n④ER驻留信号KDEL使Bip/PDI留在ER。\n\n【监控机制】\n①新生肽链进入ER腔→分子伴侣帮助折叠；\n②正确折叠和装配的蛋白→允许离开ER运往高尔基体；\n③错误折叠蛋白→被Bip滞留→反复尝试折叠；\n④长期不能正确折叠→逆向转运至胞质(ERAD)→泛素化→26S蛋白酶体降解。\n\n【意义】\n①保证分泌蛋白和膜蛋白的质量；\n②防止错误折叠蛋白聚集造成细胞损伤；\n③与多种疾病相关(如囊性纤维化CFTR突变、α1-抗胰蛋白酶缺乏症等折叠病)；\n④维持细胞稳态。","kp":"ch03_s0_18"}],"term":[{"id":"ch03_term_1","modI":0,"term":"内膜系统(Endomembrane System)","def":"①在结构、功能乃至发生上相关的、由单层膜围绕成的细胞器或细胞结构（定义）。②组成：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)（组成）。③特点：膜相互流动、可相互转化（特点）。④意义：是真核细胞分室化的基础（意义）。","kps":"踩分点:①定义(1分)②组成(2分)③意义(1分)","kp":"ch03_s0_2"},{"id":"ch03_term_2","modI":0,"term":"粗面内质网(rER)","def":"①膜表面分布大量核糖体的内质网，多呈扁囊状（定义）。②功能：合成分泌性蛋白和膜蛋白；蛋白质N-连接糖基化；新生肽折叠与装配；蛋白质质量监控（功能）。③膜上有易位子(translocon)介导肽链进入ER腔（结构）。","kps":"踩分点:①定义(1分)②功能(2分)③易位子(1分)","kp":"ch03_s0_10"},{"id":"ch03_term_3","modI":0,"term":"光面内质网(sER)","def":"①表面无核糖体的内质网（定义）。②功能：解毒(肝细胞细胞色素P450)；储钙(Ca库，Ca2+-ATPase泵入，参与信号传递)；合成膜脂(甘油磷脂和胆固醇)（功能）。","kps":"踩分点:①定义(1分)②三大功能(3分)","kp":"ch03_s0_9"},{"id":"ch03_term_4","modI":0,"term":"易位子(Translocon)","def":"①rER膜上的蛋白复合体，中心有直径2nm的孔道（定义）。②核心为Sec61复合体(Sec61α/β/γ)，高度保守（结构）。③功能：介导新生肽链进入ER腔（功能）。","kps":"踩分点:①定义(1分)②Sec61(1分)③功能(1分)","kp":"ch03_s0_19"},{"id":"ch03_term_7","modI":0,"term":"分子伴侣(Molecular Chaperone)","def":"①能识别并结合正在合成或部分折叠的多肽、帮助其折叠装配的蛋白（定义）。②特点：不构成最终产物的一部分；高度保守(如Hsp70)（特点）。③举例：Bip、Hsp70、伴侣蛋白GroEL/GroES（举例）。④意义：帮助蛋白正确折叠、防止聚集（意义）。","kps":"踩分点:①定义(1分)②特点(1分)③举例(1分)④意义(1分)","kp":"ch03_s0_4"},{"id":"ch03_term_8","modI":0,"term":"Bip蛋白","def":"①内质网驻留的分子伴侣(binding protein)（定义）。②功能：识别不正确折叠或未组装的蛋白，防止聚集，帮助折叠（功能）。③含KDEL内质网驻留信号，被保留在ER中（特点）。","kps":"踩分点:①定义(1分)②功能(2分)③KDEL(1分)","kp":"ch03_s0_0"},{"id":"ch03_term_15","modI":0,"term":"分子伴侣介导的蛋白折叠","def":"①分子伴侣通过反复结合与释放，帮助新生多肽折叠的机制（定义）。②与伴侣蛋白(GroEL/GroES)的隔离腔室折叠方式不同（区别）。③最终三维构象仍由氨基酸序列决定（特点）。","kps":"踩分点:①定义(1分)②与伴侣蛋白区别(2分)③序列决定构象(1分)","kp":"ch03_s0_18"}]},{"i":1,"name":"模块二：蛋白质分选与降解","slides":[{"i":0,"sec":"第二节 蛋白质分选","title":"N-糖基化过程 (p50)","notes":"内质网腔面，寡糖链连在插入膜内的磷酸多萜醇(dolichol)上，当与糖基化有关的氨基酸残基天冬酰胺(Asn)出现后，通过膜上的糖基转移酶将寡糖链转移到Asn残基上。","page":50,"level":"掌握","img":"assets/img/ch03/p050.jpg","anim":"glycosylation","fig":"图显示 N-连接糖基化：磷酸多萜醇(dolichol)先在内质网膜上组装寡糖前体，再整体转移给新生肽链的 Asn 残基。这是 ER 内最主要的糖基化方式。","points":["N-连接糖基化起始于 rER：糖链连到 Asn 的酰胺氮上，供体是磷酸多萜醇。","O-连接糖基化发生在高尔基体：糖链连到 Ser/Thr 的羟基氧上。","N-糖基化在 ER 先加核心糖链，到 Golgi 再加工修饰。"],"check":{"q":"关于N-连接糖基化起始过程的叙述，正确的是？","o":["A. 起始于胞质，糖链直接连到赖氨酸残基上","B. 发生在高尔基体，糖链连到Ser/Thr羟基氧上","C. 起始于rER腔，寡糖链由磷酸多萜醇转移至Asn残基","D. 由游离单糖直接加到肽链的谷氨酸残基上"],"a":"C","e":"N-连接糖基化起始于rER腔，寡糖链先连在磷酸多萜醇上，再由糖基转移酶转移到Asn残基；O-连接则在高尔基体连接Ser/Thr羟基。","oe":["N-糖基化在rER腔起始，且不连到赖氨酸，错误。","这是O-连接糖基化，发生在高尔基体，非N-连接，错误。","正确，N-糖基化始于rER，供体为磷酸多萜醇，受体为Asn。","糖链并非以游离单糖加到谷氨酸，受体是Asn，错误。"]},"cards":[{"front":"N-糖基化过程中寡糖链如何转移？","back":"ER腔面寡糖链连在磷酸多萜醇上；Asn残基出现后，糖基转移酶将寡糖链转移到Asn上。","mnemonic":"多萜醇载糖，酶转给Asn","type":"流程","useImg":true,"blank":"磷酸多萜醇","blank2":"糖基转移酶"}],"mem":"多萜醇载糖，酶转给Asn","big":"assets/img/ch03/big/p050.jpg","terms":[{"t":"磷酸多萜醇","en":"dolichol","d":"ER膜中的脂质载体，先携带寡糖再转移到天冬酰胺残基上，起始N-糖基化。"}]},{"i":1,"sec":"第二节 蛋白质分选","title":"N-连接糖基化位点 (p51)","notes":"一旦新生肽链上的天冬酰胺残基(Asn-X-Ser/Thr)进入rER腔，在糖基转移酶作用下进行蛋白N-糖基化修饰。N-连接寡糖的核心糖链结构保守。","page":51,"level":"掌握","img":"assets/img/ch03/p051.jpg","anim":null,"fig":null,"points":["新生肽链上的天冬酰胺残基(Asn-X-Ser/Thr)进入rER腔后被糖基化","在糖基转移酶作用下进行N-糖基化，核心糖链结构保守"],"check":{"q":"蛋白质发生N-连接糖基化的识别位点（序列）通常是？","o":["A. Lys-X-Arg","B. Asn-X-Ser/Thr","C. Ser-X-Asn","D. Gly-X-Gly"],"a":"B","e":"新生肽链上出现Asn-X-Ser/Thr序列并进入rER腔后，在糖基转移酶作用下进行N-糖基化；N-连接寡糖的核心糖链结构保守。","oe":["Lys-X-Arg不是糖基化位点，与N-糖基化无关，错误。","正确，N-糖基化位点为Asn-X-Ser/Thr，其中X为任意氨基酸残基。","序列顺序错误，其核心天冬酰胺而非丝氨酸起首，故错误。","Gly-X-Gly常与胶原等结构相关，不是N-糖基化位点，错误。"]},"cards":[{"front":"N-连接糖基化的识别位点是什么？","back":"Asn-X-Ser/Thr；进入rER腔后由糖基转移酶催化，核心糖链结构保守。","mnemonic":"天冬酰胺，X后带丝苏","type":"定位","useImg":false,"blank":"Asn-X-Ser/Thr","blank2":"糖基转移酶"}],"mem":"天冬酰胺，X后带丝苏","big":"assets/img/ch03/big/p051.jpg","terms":[{"t":"N-连接糖基化位点","en":"Asn-X-Ser/Thr","d":"序列为Asn-X-Ser/Thr的天冬酰胺残基，是N-糖链的连接位点。"}]},{"i":2,"sec":"第二节 蛋白质分选","title":"N-连接vs O-连接糖基化 (p52)","notes":"N-连接 vs O-连接糖基化：①合成部位——N-连接起始于粗面内质网，O-连接在高尔基体；②合成方式——N-连接来自同一个寡糖前体，O-连接一个个单糖加上去；③结合的氨基酸残基——N-连接为Asn，O-连接为Ser/Thr。","page":52,"level":"掌握","img":"assets/img/ch03/p052.jpg","anim":null,"fig":null,"points":["N-连接起始于粗面内质网，O-连接在高尔基体","N-连接来自同一寡糖前体，O-连接逐个加单糖","N-连接连Asn，O-连接连Ser/Thr"],"check":{"q":"关于N-连接与O-连接糖基化，下列叙述正确的是？","o":["A. N-连接连接Ser/Thr；O-连接连接Asn","B. 两者都起始于高尔基体并最终完成于内质网","C. N-连接起始于粗面内质网、连接Asn；O-连接在高尔基体、连接Ser/Thr","D. O-连接来自同一寡糖前体，N-连接逐个添加单糖"],"a":"C","e":"N-连接起于rER连Asn；O-连接起于高尔基体连Ser/Thr。","oe":["错误：N-连接连Asn、O-连接连Ser/Thr，该项恰好颠倒","错误：并非两者都起始于高尔基体，N-连接起始于粗面内质网","正确：N-连接在rER连Asn，O-连接在高尔基体连Ser/Thr","错误：N-连接来自同一寡糖前体，O-连接逐个加单糖，该项颠倒"]},"cards":[{"front":"N-连接与O-连接糖基化的三大区别？","back":"部位：N在rER，O在高尔基；方式：N用同一寡糖前体，O逐个加单糖；残基：N为Asn，O为Ser/Thr。","mnemonic":"N内O高，N整O零，N天O丝","type":"对比","useImg":false,"blank":"寡糖前体","blank2":"高尔基"}],"mem":"N内O高，N整O零，N天O丝","big":"assets/img/ch03/big/p052.jpg"},{"i":3,"sec":"第二节 蛋白质分选","title":"糖基化的生物学功能 (p53)","notes":"蛋白质糖基化的生物学功能：细胞内负责糖链合成与加工的酶类均为管家基因编码。①促进蛋白质折叠(如抗体IgG或质膜糖蛋白血凝素)；②影响蛋白稳定性、半衰期；③参与细胞识别、免疫；④溶酶体酶的M6P分选信号。","page":53,"level":"掌握","img":"assets/img/ch03/p053.jpg","anim":null,"fig":null,"points":["促进蛋白质折叠","影响蛋白稳定性与半衰期","参与细胞识别、免疫","提供溶酶体酶的M6P分选信号"],"check":{"q":"下列属于蛋白质糖基化生物学功能的是？","o":["A. 为蛋白质合成提供氨基酸","B. 直接为细胞提供能量","C. 促进折叠、影响稳定性、参与识别与M6P分选","D. 作为遗传信息的储存形式"],"a":"C","e":"糖基化可促进蛋白质折叠、影响其稳定性与半衰期、参与细胞识别与免疫，并形成M6P分选信号。","oe":["错：糖链不是氨基酸来源，不符合本页所学概念","错：糖链并不直接为细胞提供能量","对：均为笔记所列糖基化功能，与笔记原文相符","错：遗传信息储存于核酸，不符合本页所学概念"],"basis":"①促进蛋白质折叠；②影响稳定性；③参与识别；④M6P分选信号"},"cards":[{"front":"蛋白质糖基化有哪些生物学功能？","back":"①促进蛋白质折叠；②影响蛋白稳定性与半衰期；③参与细胞识别与免疫；④提供溶酶体酶M6P分选信号","mnemonic":"折、稳、识、分（分选）","type":"功能","useImg":false,"blank":"M6P分选信号","blank2":"细胞识别与免疫"}],"mem":"折、稳、识、分（分选）","big":"assets/img/ch03/big/p053.jpg"},{"i":4,"sec":"第二节 蛋白质分选","title":"新生肽的折叠与装配 (p54)","notes":"ER的功能：新生多肽的折叠(folding)与装配(assembly)——分子间/分子内的二硫键(2Cys-SH→Cys-S-S-Cys)在ER腔形成。\n\n【本页英文讲解】\n本页讲内质网（ER）对新生多肽的折叠（folding）与装配（assembly）功能。在ER腔中，多肽链折叠并装配成有功能的构象，同时形成分子间或分子内的二硫键（disulfide bond），即由两个半胱氨酸巯基2Cys-SH氧化为Cys-S-S-Cys。这是ER作为蛋白质加工与质量控制细胞器的重要功能，联系教材第七章。","page":54,"level":"掌握","img":"assets/img/ch03/p054.jpg","anim":"chaperone_folding","fig":null,"points":["ER腔中进行新生多肽的折叠与装配","分子间/分子内二硫键在ER腔形成"],"check":{"q":"ER腔内新生多肽折叠装配时，二硫键的形成属于？","o":["A. 丝氨酸羟基被磷酸化的过程","B. 两个赖氨酸氨基之间的缩合","C. 两个半胱氨酸巯基氧化为Cys-S-S-Cys","D. 天冬酰胺残基连接寡糖链的过程"],"a":"C","e":"ER腔内二硫键由两个半胱氨酸巯基氧化为Cys-S-S-Cys。","oe":["错误：磷酸化与二硫键无关，二硫键由半胱氨酸巯基氧化形成","错误：二硫键由半胱氨酸巯基形成，与赖氨酸氨基无关","二硫键由两个半胱氨酸巯基氧化形成","错误：天冬酰胺连接寡糖链属于糖基化，并非二硫键形成"]},"cards":[{"front":"内质网在新生肽加工中的核心功能是什么？","back":"新生多肽的折叠与装配；分子内/间二硫键在ER腔内形成","mnemonic":"ER=折叠车间+装配线","type":"功能","useImg":true,"blank":"折叠与装配","blank2":"二硫键"}],"mem":"ER=折叠车间+装配线","big":"assets/img/ch03/big/p054.jpg"},{"i":5,"sec":"第二节 蛋白质分选","title":"二硫键在ER腔形成 (p55)","notes":"In eukaryotic cells, disulfide bonds are formed only in the lumen of the ER——真核细胞中二硫键只在ER腔内形成，由二硫键异构酶(PDI)催化。\n\n【本页英文讲解】\n本页讲二硫键（disulfide bond）在真核细胞中的形成场所。二硫键只在ER腔内形成（disulfide bonds form only in the ER lumen），由二硫键异构酶（PDI，protein disulfide isomerase）催化。PDI既能催化二硫键形成，也能纠正错误配对。考点：ER腔的氧化环境及PDI功能，见教材第七章。","page":55,"level":"掌握","img":"assets/img/ch03/p055.jpg","anim":null,"fig":"二硫键(S–S)在 ER 腔内形成，连接两个 Cys，稳定蛋白质三维结构。图说明 ER 腔的氧化环境有利于二硫键形成，这是胞质(还原环境)中难以进行的。","points":["真核细胞中二硫键只在ER腔内形成","由二硫键异构酶(PDI)催化"],"check":{"q":"真核细胞中二硫键形成的场所及催化酶分别是？","o":["A. 细胞质基质，由激酶催化","B. 细胞核内，由连接酶催化","C. 内质网腔，由二硫键异构酶(PDI)催化","D. 线粒体基质，由氧化酶催化"],"a":"C","e":"真核细胞中二硫键只在ER腔内形成，由二硫键异构酶（PDI）催化，PDI还能纠正错误配对。","oe":["二硫键不在胞质形成，胞质为还原环境，错误。","细胞核不是二硫键形成场所，连接酶也不符，错误。","正确，二硫键在ER腔由PDI催化形成与重排。","线粒体并非二硫键形成的主要场所，酶也不符，错误。"]},"cards":[{"front":"真核细胞中二硫键在何处形成？由什么酶催化？","back":"只在ER腔内形成；由二硫键异构酶（PDI）催化","mnemonic":"二硫键只认ER腔","type":"定位","useImg":true,"blank":"二硫键异构酶","blank2":"ER腔内"}],"mem":"二硫键只认ER腔","big":"assets/img/ch03/big/p055.jpg"},{"i":6,"sec":"第二节 蛋白质分选","title":"PDI蛋白 (p56)","notes":"PDI(蛋白二硫键异构酶)是ER驻留蛋白，存在于所有真核细胞，尤其丰富于分泌细胞，催化二硫键的形成与重排。","page":56,"level":"掌握","img":"assets/img/ch03/p056.jpg","anim":null,"fig":"蛋白二硫键异构酶(PDI)催化二硫键的形成、重排和还原，帮助蛋白折叠到正确构象。图显示 PDI 在 ER 腔中反复作用，是 ER 驻留蛋白(含 KDEL)。","points":["PDI是ER驻留蛋白，丰富于分泌细胞","催化二硫键的形成与重排"],"check":{"q":"关于蛋白二硫键异构酶(PDI)的叙述，正确的是？","o":["A. 是溶酶体酶，负责降解错误折叠蛋白","B. 是胞质游离蛋白，仅催化二硫键断裂","C. 是ER驻留蛋白，催化二硫键形成与重排","D. 是核内蛋白，参与DNA复制"],"a":"C","e":"PDI是ER驻留蛋白，存在于所有真核细胞，尤其丰富于分泌细胞，催化二硫键的形成与重排。","oe":["降解错误折叠蛋白由蛋白酶体等负责，PDI不担当，错误。","PDI是ER驻留蛋白而非胞质游离蛋白，也非仅断裂，错误。","正确，PDI为ER驻留蛋白，催化二硫键形成与重排。","PDI位于内质网且不参与DNA复制，与题意功能不符，错误。"]},"cards":[{"front":"PDI是什么？分布有何特点？","back":"蛋白二硫键异构酶；ER驻留蛋白，存在于所有真核细胞，分泌细胞中尤其丰富；催化二硫键形成与重排","mnemonic":"PDI=二硫键的裁缝","type":"定义","useImg":false,"blank":"蛋白二硫键异构酶","blank2":"ER驻留蛋白"}],"mem":"PDI=二硫键的裁缝","big":"assets/img/ch03/big/p056.jpg"},{"i":7,"sec":"第二节 蛋白质分选","title":"Bip蛋白 (p57)","notes":"Bip(binding protein)：ER驻留蛋白，识别不正确折叠的蛋白或未组装的蛋白，防止其聚集，帮助其正确折叠。属于分子伴侣。","page":57,"level":"掌握","img":"assets/img/ch03/p057.jpg","anim":null,"fig":"Bip 是 ER 腔中的分子伴侣(Hsp70 家族)，结合新生肽链的疏水区，防止错误聚集并帮助折叠。图说明 Bip 也参与未折叠蛋白反应(UPR)和 ERAD 的识别。","points":["Bip是ER驻留蛋白、分子伴侣","识别不正确折叠或未组装的蛋白，防止聚集、帮助正确折叠"],"check":{"q":"Bip蛋白的主要功能是？","o":["A. 将H+泵入溶酶体维持酸性","B. 识别错误折叠或未组装蛋白，防止聚集并帮助折叠","C. 在糖链上加上甘露糖-6-磷酸标志","D. 催化二硫键的形成与重排"],"a":"B","e":"Bip是ER驻留的分子伴侣，能识别错误折叠或未组装的蛋白，防止其聚集并帮助其正确折叠。","oe":["泵H+的是溶酶体膜质子泵，与Bip无关，错误。","正确，Bip识别错误折叠或未组装蛋白，防聚集助折叠。","加M6P标志的是高尔基体中的磷酸转移酶，错误。","催化二硫键形成与重排的是PDI，不是Bip，错误。"]},"cards":[{"front":"Bip蛋白的功能是什么？属于哪类蛋白？","back":"ER驻留分子伴侣；识别错误折叠或未组装蛋白，防止其聚集，帮助正确折叠","back2":"","mnemonic":"Bip=ER里的纠错员","type":"功能","useImg":false,"blank":"分子伴侣","blank2":"错误折叠或未组装蛋白"}],"mem":"Bip=ER里的纠错员","big":"assets/img/ch03/big/p057.jpg"},{"i":8,"sec":"第二节 蛋白质分选","title":"分子伴侣 (p58)","notes":"分子伴侣(Molecular chaperones)：细胞中一些蛋白分子可识别并结合正在合成、部分折叠的多肽，帮助新生多肽折叠、装配，但不构成最终产物的一部分。","page":58,"level":"掌握","img":"assets/img/ch03/p058.jpg","anim":null,"fig":null,"points":["分子伴侣帮助蛋白折叠/组装，但不构成最终产物。","ER 腔中的伴侣：Bip、钙联蛋白、钙网蛋白等。","分子伴侣还负责识别错误折叠蛋白，送交 ERAD 降解。"],"check":{"q":"关于分子伴侣的叙述，正确的是？","o":["A. 仅存在于原核细胞中","B. 是最终产物蛋白的组成亚基","C. 帮助新生多肽折叠装配，但不构成最终产物的一部分","D. 直接决定蛋白质的氨基酸序列"],"a":"C","e":"分子伴侣识别并结合正在合成、部分折叠的多肽，帮助其折叠装配，但本身不构成最终产物的一部分。","oe":["分子伴侣在真核、原核细胞中普遍存在，错误。","分子伴侣并非最终产物的组成亚基，错误。","正确，分子伴侣辅助折叠装配，但不构成最终产物。","氨基酸序列由基因决定，非分子伴侣决定，错误。"]},"cards":[{"front":"什么是分子伴侣？","back":"能识别并结合正在合成或部分折叠的多肽，帮助其折叠、装配，但不构成最终产物一部分的蛋白","mnemonic":"帮忙不入职（不成为产物）","type":"定义","useImg":false,"blank":"帮助其折叠、装配","blank2":"正在合成或部分折叠的多肽"}],"mem":"帮忙不入职（不成为产物）","big":"assets/img/ch03/big/p058.jpg"},{"i":9,"sec":"第二节 蛋白质分选","title":"分子伴侣的结构特点 (p59)","notes":"分子伴侣结构特点：高度保守性——Hsp70广泛存在于真核、原核生物中(细菌、果蝇、酵母、哺乳动物)，同源性高。Hsp70家族成员协助蛋白折叠。","page":59,"level":"掌握","img":"assets/img/ch03/p059.jpg","anim":null,"fig":null,"points":["分子伴侣高度保守，Hsp70广泛存在于真核、原核生物，同源性高","Hsp70家族成员协助蛋白折叠"],"check":{"q":"体现分子伴侣结构高度保守性的典型例子是？","o":["A. 血红蛋白仅在某些细胞中表达","B. Hsp70广泛存在于细菌、酵母、果蝇、哺乳动物中且同源性高","C. 网格蛋白只存在于哺乳动物","D. 抗体分子高度可变"],"a":"B","e":"分子伴侣高度保守，Hsp70广泛存在于细菌、酵母、果蝇、哺乳动物等真核与原核生物中，同源性高。","oe":["血红蛋白表达有组织特异性，与分子伴侣保守性无关，错误。","正确，Hsp70跨物种广泛存在且同源性高，体现保守性。","网格蛋白并非只存在于哺乳动物，也不体现该保守性，错误。","抗体高度可变，与分子伴侣高度保守相反，错误。"]},"cards":[{"front":"分子伴侣的结构特点是什么？举例说明。","back":"高度保守；如Hsp70广泛存在于真核、原核生物（细菌、果蝇、酵母、哺乳动物），同源性高，协助蛋白折叠","mnemonic":"Hsp70=进化保守的折叠助手","type":"组成/例证","useImg":false,"blank":"Hsp70","blank2":"协助蛋白折叠"}],"mem":"Hsp70=进化保守的折叠助手","big":"assets/img/ch03/big/p059.jpg"},{"i":10,"sec":"第二节 蛋白质分选","title":"伴侣蛋白介导的折叠 (p60)","notes":"Chaperonin-mediated protein folding vs Chaperone-mediated protein folding：伴侣蛋白(如GroEL/GroES)形成隔离腔室帮助折叠；分子伴侣(如Hsp70)反复结合释放。\n\n【本页英文讲解】\n本页对比伴侣蛋白与分子伴侣介导的蛋白质折叠。伴侣蛋白（chaperonin，如GroEL/GroES）形成隔离腔室，将底物蛋白与胞质隔离后帮助其折叠；分子伴侣（chaperone，如Hsp70）则通过反复结合与释放底物来防止错误聚集、帮助折叠。二者均不改变最终构象信息。考点：两类折叠辅助蛋白的区别，见教材第七章。","page":60,"level":"理解","img":"assets/img/ch03/p060.jpg","anim":null,"fig":"伴侣介导的折叠：新生肽链先与伴侣结合，逐步折叠并释放；若多次尝试仍不能正确折叠，则被识别并降解(质量控制)。图强调“折叠—监控—降解”的平衡。","points":null,"check":{"q":"伴侣蛋白(chaperonin，如GroEL/GroES)帮助蛋白折叠的主要特点是？","o":["A. 靠反复结合与释放底物完成折叠","B. 形成隔离腔室，使底物与胞质隔离后折叠","C. 通过泛素化标记底物后降解","D. 直接提供蛋白质折叠的构象信息"],"a":"B","e":"伴侣蛋白（如GroEL/GroES）形成隔离腔室帮助底物折叠；分子伴侣（如Hsp70）则靠反复结合与释放底物，二者均不提供构象信息。","oe":["反复结合释放是Hsp70等分子伴侣的特点，非伴侣蛋白，错误。","正确，伴侣蛋白形成隔离腔室使底物隔离折叠。","泛素化降解属ERAD途径，与折叠辅助无关，错误。","折叠构象信息由氨基酸序列决定，伴侣不提供，错误。"]},"cards":null,"mem":"伴侣蛋白GroEL有隔离腔；伴侣Hsp70反复结合","big":"assets/img/ch03/big/p060.jpg"},{"i":11,"sec":"第二节 蛋白质分选","title":"折叠信息由序列决定 (p61)","notes":"However, the final 3-D shape of the protein is still specified by its amino acid sequence——分子伴侣帮助折叠，但最终三维构象仍由氨基酸序列决定。\n\n【本页英文讲解】\n本页强调蛋白质折叠的信息来源。分子伴侣虽能帮助折叠，但蛋白质最终的三维构象（final 3-D shape）仍由其氨基酸序列（amino acid sequence）决定，即一级结构决定高级结构。分子伴侣只提供折叠环境、防止错误聚集，不提供构象信息。考点：“序列决定构象”与分子伴侣作用的本质，见教材第七章。","page":61,"level":"理解","img":"assets/img/ch03/p061.jpg","anim":null,"fig":null,"points":["蛋白质折叠靠非共价键：氢键、离子键、疏水作用(范德华力)。","疏水核心是折叠的主要驱动力：疏水残基埋在内，亲水残基露在外。","折叠信息由一级结构(氨基酸序列)决定(Anfinsen 实验)。"],"check":{"q":"关于蛋白质折叠信息来源的叙述，正确的是？","o":["A. 由二硫键数量随机决定","B. 最终三维构象由分子伴侣提供","C. 最终三维构象由氨基酸序列决定","D. 由高尔基体的糖基化决定"],"a":"C","e":"分子伴侣虽帮助折叠，但蛋白质最终的三维构象仍由氨基酸序列决定，即一级结构决定高级结构（Anfinsen原理）。","oe":["二硫键帮助稳定构象，但不决定折叠信息，错误。","分子伴侣只提供折叠环境，不提供构象信息，错误。","正确，最终三维构象由氨基酸序列决定，即一级结构决定高级结构。","糖基化是修饰，不决定整体三维构象信息，错误。"]},"cards":null,"mem":"伴侣助折叠，但三维构象由氨基酸序列决定","big":"assets/img/ch03/big/p061.jpg"},{"i":12,"sec":"第二节 蛋白质分选","title":"蛋白质质量监控 (p62)","notes":"The process that monitors protein quality following protein synthesis——ER的质量监控系统：只有正确折叠和装配的蛋白才能离开ER，错误折叠蛋白被滞留并降解。","page":62,"level":"掌握","img":"assets/img/ch03/p062.jpg","anim":"er_quality","fig":"内质网的质量监控系统检查蛋白是否折叠正确：正确折叠的才能进入高尔基体；错误折叠的被滞留、反复折叠或送交 ERAD 降解。图是“质检—放行/销毁”的分支。","points":["ER质量监控：只有正确折叠和装配的蛋白才能离开ER","错误折叠蛋白被滞留并降解"],"check":{"q":"内质网质量监控系统对蛋白质的处理方式是？","o":["A. 只有正确折叠和装配的蛋白才能离开ER，错误折叠蛋白被滞留并降解","B. 所有合成的蛋白均可离开ER","C. 错误折叠蛋白立即被分泌到胞外","D. 蛋白离开ER不经过任何检查"],"a":"A","e":"ER质量监控系统只允许正确折叠和装配的蛋白离开ER，错误折叠的蛋白被滞留并降解。","oe":["正确，正确折叠装配者才能离开，错误者被滞留降解。","并非所有蛋白都能离开ER，须通过质量监控，错误。","错误折叠蛋白被滞留降解，而非分泌到胞外，错误。","蛋白离开ER须经严格质量监控，并非无检查，错误。"]},"cards":[{"front":"ER蛋白质质量监控系统的核心规则是什么？","back":"只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被滞留并降解","mnemonic":"折对才放行，折错就销毁","type":"流程","useImg":false,"blank":"正确折叠和装配","blank2":"错误折叠蛋白"}],"mem":"折对才放行，折错就销毁","big":"assets/img/ch03/big/p062.jpg"},{"i":13,"sec":"第二节 蛋白质分选","title":"ER驻留信号 (p63)","notes":"Bip & PDI属于内质网驻留蛋白(ER-resident protein)：具内质网驻留信号序列(ER retention signal，如KDEL)，使其被保留在ER中而不被分泌。\n\n【本页英文讲解】\n本页讲内质网驻留蛋白（ER-resident protein）与驻留信号。Bip、PDI等属于ER驻留蛋白，它们含内质网驻留信号序列（ER retention signal），如KDEL序列，使其被保留在ER中而不被分泌到细胞外。考点：KDEL等驻留/回收信号的种类与作用，见教材第八章。","page":63,"level":"掌握","img":"assets/img/ch03/p063.jpg","anim":null,"fig":null,"points":["Bip、PDI属于内质网驻留蛋白","具内质网驻留信号序列(如KDEL)，使其保留在ER中而不被分泌"],"check":{"q":"Bip、PDI等内质网驻留蛋白不被分泌，是因为含有？","o":["A. 一段引导入ER的N端信号肽","B. M6P标志","C. 多聚泛素链","D. KDEL等内质网驻留信号序列"],"a":"D","e":"Bip、PDI含KDEL驻留信号，被保留在ER中而不被分泌。","oe":["N端信号肽引导入ER后即被切除","错误：M6P是将溶酶体酶靶向运往溶酶体的分选标志","多聚泛素链是蛋白质的降解信号，不是ER驻留信号","KDEL等驻留信号使蛋白被保留在ER中"]},"cards":[{"front":"内质网驻留蛋白（如Bip、PDI）为什么不被分泌出ER？","back":"因其带有内质网驻留信号序列（如KDEL），使其被保留在ER中而不被分泌。","mnemonic":"KDEL——Keep in ER","type":"功能","useImg":false,"blank":"内质网驻留信号序列","blank2":"KDEL"}],"mem":"KDEL——Keep in ER","big":"assets/img/ch03/big/p063.jpg","terms":[{"t":"ER驻留信号","en":"ER retention signal","d":"ER驻留蛋白C端的回收信号（如KDEL/HDEL），逃逸到高尔基体后被识别并回收回ER。"}]},{"i":14,"sec":"第二节 蛋白质分选","title":"ER质量监控体制 (p64)","notes":"内质网蛋白质的质量监控体制：Only proteins that are properly folded and assembled can leave the ER——只有正确折叠和装配的蛋白才能离开ER，保证蛋白质量。","page":64,"level":"掌握","img":"assets/img/ch03/p064.jpg","anim":null,"fig":null,"points":["只有正确折叠和装配的蛋白才能离开ER，保证蛋白质量"],"check":{"q":"内质网蛋白质质量监控体制的核心内容是？","o":["A. 未折叠蛋白被直接分泌到细胞外","B. 蛋白能否离开ER与其折叠状态无关","C. 所有新合成的蛋白均可自由离开ER","D. 只有正确折叠和装配的蛋白才能离开ER"],"a":"D","e":"ER质控确保只有正确折叠装配的蛋白才能离开ER。","oe":["错误：未折叠蛋白被质量监控滞留，不会分泌到细胞外","折叠状态正是能否离开的决定因素","错误：并非所有蛋白都能离开，错误折叠蛋白被滞留降解","ER质控保证仅正确折叠装配的蛋白可离开"]},"cards":[{"front":"内质网蛋白质质量监控体制的核心原则是什么？","back":"只有正确折叠和装配的蛋白才能离开ER，从而保证蛋白质质量。","mnemonic":"折好才放行，ER是质检关卡","type":"功能","useImg":false,"blank":"正确折叠和装配","blank2":"蛋白质质量"}],"mem":"折好才放行，ER是质检关卡","big":"assets/img/ch03/big/p064.jpg"},{"i":15,"sec":"第二节 蛋白质分选","title":"错误折叠蛋白的降解 (p65)","notes":"The export and degradation of misfolded ER proteins：错误折叠的ER蛋白被逆向转运到胞质，经泛素-蛋白酶体系统降解(ERAD途径)。\n\n【本页英文讲解】\n本页讲错误折叠蛋白的降解（ERAD，ER-associated degradation）。错误折叠的内质网蛋白被逆向转运（retrotranslocation）到胞质，经泛素化后被泛素-蛋白酶体系统（ubiquitin-proteasome system）降解。这是内质网的质量控制机制，可防止错误蛋白堆积。考点：ERAD途径的步骤，见教材第八章。","page":65,"level":"掌握","img":"assets/img/ch03/p065.jpg","anim":"erad","fig":"错误折叠蛋白的降解途径(ERAD)：蛋白经 Sec61 易位子从 ER 腔/膜逆向转运到胞质 → N-聚糖酶切除糖链 → 泛素化 → 26S 蛋白酶体降解。图的关键是“逆向易位”和“泛素-蛋白酶体”。","points":["错误折叠的ER蛋白被逆向转运到胞质","经泛素-蛋白酶体系统降解（ERAD途径）"],"check":{"q":"内质网中错误折叠蛋白的降解途径(ERAD)主要是？","o":["A. 直接分泌到细胞外","B. 逆向转运到胞质，经泛素化后被蛋白酶体降解","C. 在ER内被ATP合成酶分解","D. 在ER腔内直接被溶酶体酶消化"],"a":"B","e":"错误折叠的ER蛋白经逆向转运到胞质，泛素化后由泛素-蛋白酶体系统降解，即ERAD途径。","oe":["错误折叠蛋白被降解而非分泌到胞外，错误。","正确，ERAD经逆向转运、泛素化后由蛋白酶体降解。","ATP合成酶不参与蛋白质降解，机制错误。","错误折叠ER蛋白并非在腔内直接消化，而需逆向转运，错误。"]},"cards":[{"front":"错误折叠的ER蛋白通过什么途径被降解？","back":"逆向转运到胞质，经泛素-蛋白酶体系统降解，即ERAD途径。","mnemonic":"折错就退货：出ER→泛素化→蛋白酶体","type":"流程","useImg":false,"blank":"ERAD途径","blank2":"泛素-蛋白酶体系统"}],"mem":"折错就退货：出ER→泛素化→蛋白酶体","big":"assets/img/ch03/big/p065.jpg","terms":[{"t":"逆向转运","en":"retrotranslocation","d":"错误折叠的内质网蛋白被从ER逆向运回胞质的过程。"},{"t":"泛素-蛋白酶体系统","en":"ubiquitin-proteasome system","d":"用泛素标记靶蛋白并由蛋白酶体将其降解的胞内降解系统。"}]},{"i":16,"sec":"第二节 蛋白质分选","title":"2004年诺贝尔化学奖 (p66)","notes":"2004年诺贝尔化学奖授予Aaron Ciechanover、Avram Hershko、Irwin Rose——发现泛素介导的蛋白质降解。\n\n【本页英文讲解】\n本页讲2004年诺贝尔化学奖。该奖授予Aaron Ciechanover、Avram Hershko与Irwin Rose，表彰他们发现泛素（ubiquitin）介导的蛋白质降解（ubiquitin-mediated）。泛素标签引导靶蛋白被蛋白酶体（proteasome）降解。此为蛋白质降解与质量控制的经典考点，与ERAD途径相联系，见教材第八章。","page":66,"level":"掌握","img":"assets/img/ch03/p066.jpg","anim":null,"fig":null,"points":["2004年诺贝尔化学奖授予Ciechanover、Hershko、Rose","表彰发现泛素介导的蛋白质降解"],"check":{"q":"泛素介导的蛋白质降解过程中，多聚泛素链的作用是？","o":["A. 为蛋白质合成提供能量","B. 直接催化肽键的水解","C. 引导蛋白质进入细胞核","D. 作为降解信号，引导靶蛋白进入蛋白酶体"],"a":"D","e":"多聚泛素链作为降解信号标记靶蛋白，引导其被蛋白酶体识别并降解，实现蛋白质质量控制。","oe":["错：泛素化消耗能量而非供能，不符合本页所学概念","错：肽键水解由蛋白酶体催化，不符合本页所学概念","错：泛素化过程与蛋白核输入无关","对：笔记指出泛素标签引导蛋白酶体降解"],"basis":"泛素标签引导靶蛋白被蛋白酶体降解"},"cards":[{"front":"2004年诺贝尔化学奖表彰了什么发现？获奖者是谁？","back":"发现泛素介导的蛋白质降解；获奖者为Ciechanover、Hershko、Rose。","mnemonic":"","type":"例证","useImg":false,"blank":"泛素介导的蛋白质降解","blank2":"Ciechanover、Hershko、Rose"}],"mem":"2004诺奖：泛素介导蛋白降解(蛋白酶体)","big":"assets/img/ch03/big/p066.jpg"},{"i":17,"sec":"第二节 蛋白质分选","title":"泛素 (p67)","notes":"泛素(ubiquitin)：由76个氨基酸组成的多肽，8.5×10³小分子球蛋白，高度保守，普遍存在于真核细胞，故名泛素。作为降解标签。","page":67,"level":"掌握","img":"assets/img/ch03/p067.jpg","anim":null,"fig":null,"points":["由76个氨基酸组成的多肽，8.5×10³小分子球蛋白","高度保守、普遍存在于真核细胞，作为降解标签"],"check":{"q":"关于泛素(ubiquitin)，下列叙述正确的是？","o":["A. 由76个氨基酸组成、高度保守的小分子球蛋白，作为降解标签","B. 是一种最适pH约为5的酸性水解酶","C. 由20种氨基酸随机聚合而成的长链多糖","D. 只存在于细菌细胞中的一类膜蛋白"],"a":"A","e":"泛素由76个氨基酸组成，高度保守，作为蛋白降解标签。","oe":["泛素76个氨基酸、高度保守，作降解标签","错误：泛素是降解标签蛋白，本身并不是酸性水解酶","错误：泛素是由氨基酸组成的蛋白质，不是长链多糖","错误：泛素普遍存在于真核细胞，并非只见于细菌"]},"cards":[{"front":"泛素（ubiquitin）的组成与特点是什么？","back":"由76个氨基酸组成的多肽，约8.5×10³小分子球蛋白；高度保守，普遍存在于真核细胞，作为降解标签。","mnemonic":"76个氨基酸，无处不在故称泛素","type":"组成数字","useImg":false,"blank":"降解标签","blank2":"76个氨基酸"}],"mem":"76个氨基酸，无处不在故称泛素","big":"assets/img/ch03/big/p067.jpg"},{"i":18,"sec":"第二节 蛋白质分选","title":"泛素化过程 (p68)","notes":"靶蛋白泛素化过程：泛素分子共价结合到靶蛋白的赖氨酸残基上。三种酶：泛素活化酶(E1)、泛素结合酶(E2)、泛素连接酶(E3)。多聚泛素链是降解信号。","page":68,"level":"掌握","img":"assets/img/ch03/p068.jpg","anim":"ubiquitin_proteasome","fig":"泛素化级联：E1(泛素活化酶，耗 ATP)活化泛素 → E2(结合酶) → E3(连接酶)把泛素连到靶蛋白的 Lys 上；多轮反应形成多聚泛素链。泛素由 76 个氨基酸组成，多聚泛素链是降解信号。","points":["泛素共价结合到靶蛋白的赖氨酸残基上","三种酶：泛素活化酶E1、结合酶E2、连接酶E3","多聚泛素链是降解信号"],"check":{"q":"靶蛋白泛素化时，泛素共价结合的部位和催化该过程的酶是？","o":["A. 靶蛋白的赖氨酸残基，由E1、E2、E3依次催化","B. 靶蛋白的丝氨酸残基，由蛋白酶体催化","C. 靶蛋白的N端，由激酶催化","D. 靶蛋白的羧基端，由水解酶催化"],"a":"A","e":"泛素共价结合到靶蛋白的赖氨酸残基上，由泛素活化酶E1、结合酶E2、连接酶E3依次催化。","oe":["对：笔记明确结合Lys且需三种酶","错：结合位点不是丝氨酸，不符合本页所学概念","错：N端非泛素结合位点，不符合本页所学概念","错：泛素结合反应与水解酶无关，不符合本页所学概念"],"basis":"泛素分子共价结合到靶蛋白的赖氨酸残基上。三种酶：E1、E2、E3"},"cards":[{"front":"靶蛋白泛素化涉及哪三种酶？泛素结合在何处？","back":"E1泛素活化酶、E2泛素结合酶、E3泛素连接酶；泛素共价结合到靶蛋白的赖氨酸残基上，多聚泛素链为降解信号。","mnemonic":"E1活化、E2结合、E3连接；挂链即判死刑","type":"流程","useImg":false,"blank":"赖氨酸残基","blank2":"多聚泛素链"}],"mem":"E1活化、E2结合、E3连接；挂链即判死刑","big":"assets/img/ch03/big/p068.jpg"},{"i":19,"sec":"第二节 蛋白质分选","title":"26S蛋白酶体 (p69)","notes":"26S蛋白酶体是大型蛋白酶复合体，可将泛素化的蛋白质分解成短肽。需要待降解底物蛋白、多个泛素分子、2个ATP，经三种酶催化。","page":69,"level":"掌握","img":"assets/img/ch03/p069.jpg","anim":"proteasome","fig":"26S 蛋白酶体由 20S 催化核心(α7β7β7α7 圆筒)和两个 19S 调节帽组成。19S 帽识别多聚泛素链、去泛素化并解析叠底物，底物进入 20S 腔被切成短肽。图强调“识别—解析叠—降解”三步。","points":["26S蛋白酶体是大型蛋白酶复合体，将泛素化蛋白分解成短肽","需待降解底物、多个泛素分子、2个ATP，经三种酶催化"],"check":{"q":"关于26S蛋白酶体降解泛素化蛋白，下列叙述正确的是？","o":["A. 可将泛素化的蛋白质分解成短肽，该过程需要2个ATP","B. 仅在细胞核内起作用，细胞质中不分布","C. 属于溶酶体内的一类酸性水解酶","D. 可将蛋白完全水解为游离氨基酸，且不需要ATP"],"a":"A","e":"26S蛋白酶体将泛素化蛋白降解为短肽，过程需要2个ATP。","oe":["26S蛋白酶体将泛素化蛋白降解为短肽并耗2个ATP","蛋白酶体分布广泛，主要在细胞质和核","蛋白酶体不是溶酶体内的酸性水解酶","错误：26S蛋白酶体将蛋白降解为短肽，且过程需要ATP供能"]},"cards":[{"front":"26S蛋白酶体降解泛素化蛋白需要哪些条件？","back":"需待降解底物蛋白、多个泛素分子、2个ATP，经三种酶催化，将泛素化蛋白分解成短肽。","mnemonic":"底物+泛素+2ATP，三酶催化","type":"流程","useImg":false,"blank":"泛素化蛋白","blank2":"三种酶催化"}],"mem":"底物+泛素+2ATP，三酶催化","big":"assets/img/ch03/big/p069.jpg"},{"i":20,"sec":"第二节 蛋白质分选","title":"蛋白酶体 (p70-71)","notes":"蛋白酶体(proteasome)：细胞内降解蛋白质的大分子复合体，由约50种亚基组成，具有蛋白酶活性。26S蛋白酶体包含一个20S催化核心和两个19S调节帽。相对分子量2×10⁶-2.4×10⁶。","page":70,"level":"掌握","img":"assets/img/ch03/p070.jpg","anim":null,"fig":null,"points":["蛋白酶体由约50种亚基组成，具蛋白酶活性","26S含一个20S催化核心和两个19S调节帽"],"check":{"q":"26S蛋白酶体的结构组成是？","o":["A. 由约50种核糖体蛋白组成的翻译机器","B. 两个20S催化核心和一个19S调节帽","C. 一个20S催化核心和两个19S调节帽","D. 由网格蛋白三脚复合体组成的笼状结构"],"a":"C","e":"26S蛋白酶体由1个20S催化核心与2个19S调节帽组成。","oe":["蛋白酶体不是核糖体，不参与翻译","错误：应为1个20S催化核心与2个19S调节帽，该项颠倒","26S蛋白酶体由一个20S核心加两个19S帽组成","网格蛋白构成包被小泡，不是蛋白酶体"]},"cards":[{"front":"26S蛋白酶体的结构组成是什么？","back":"由一个20S催化核心和两个19S调节帽组成；蛋白酶体由约50种亚基组成，具蛋白酶活性，相对分子量2×10⁶-2.4×10⁶。","mnemonic":"1个20S芯+2个19S帽","type":"组成数字","useImg":true,"blank":"20S催化核心","blank2":"19S调节帽"}],"mem":"1个20S芯+2个19S帽","big":"assets/img/ch03/big/p070.jpg"},{"i":21,"sec":"第二节 蛋白质分选","title":"ER功能小结 (p72)","notes":"Summary: ER功能——蛋白质合成、脂类合成。rER合成分泌性蛋白和多种膜蛋白，膜上有易位子与多肽进入内质网有关；sER合成脂类、解毒、储钙。ER还负责蛋白折叠、修饰、质量监控。","page":72,"level":"掌握","img":"assets/img/ch03/p072.jpg","anim":null,"fig":null,"points":["rER合成分泌性蛋白和多种膜蛋白（经易位子入腔）","sER合成脂类、解毒、储钙","ER还负责蛋白折叠、修饰与质量监控"],"check":{"q":"下列关于内质网功能的叙述，正确的是？","o":["A. rER负责脂类合成，sER负责分泌蛋白合成","B. rER合成分泌蛋白和膜蛋白，sER合成脂类、解毒、储钙","C. 内质网只参与蛋白质合成，不参与折叠","D. sER膜上没有核糖体，因此不能合成任何物质"],"a":"B","e":"内质网负责蛋白质与脂类合成，rER合成分泌蛋白和膜蛋白，sER合成脂类、解毒并储存钙。","oe":["错：二者功能表述对调，不符合本页所学概念","对：与笔记rER、sER分工一致","错：ER参与蛋白折叠与质量监控","错：sER可合成脂类等物质，不符合本页所学概念"],"basis":"rER合成分泌性蛋白和多种膜蛋白…sER合成脂类、解毒、储钙"},"cards":[{"front":"内质网的两大合成功能分别由哪种ER承担？","back":"rER：合成分泌性蛋白和多种膜蛋白；sER：合成脂类、解毒、储钙","mnemonic":"粗网出蛋白，滑网管脂毒钙","type":"功能","useImg":false,"blank":"rER","blank2":"sER"},{"front":"内质网在蛋白质合成后还承担哪些加工任务？","back":"蛋白折叠、修饰、质量监控；膜上有易位子，与多肽进入内质网有关","mnemonic":"折叠修饰加质检，易位子来把门开","type":"功能","useImg":false,"blank":"易位子","blank2":"蛋白折叠、修饰、质量监控"}],"mem":"粗网出蛋白，滑网管脂毒钙","big":"assets/img/ch03/big/p072.jpg"},{"i":22,"sec":"第三节 高尔基体","title":"高尔基体形态结构 (p73)","notes":"3.2 高尔基体的形态结构与功能。高尔基体(Golgi body)又称高尔基器(Golgi apparatus)或高尔基复合体(Golgi complex)，由一系列扁平膜囊和囊泡组成。","page":73,"level":"掌握","img":"assets/img/ch03/p073.jpg","anim":null,"fig":null,"points":["高尔基体又称高尔基器或高尔基复合体","由一系列扁平膜囊和囊泡组成"],"check":{"q":"高尔基体的基本形态结构是？","o":["A. 由微管蛋白组成的纤维束","B. 由一系列扁平膜囊和囊泡组成","C. 由双层膜围成的管状嵴","D. 由单层膜围成的球形水解酶囊泡"],"a":"B","e":"高尔基体又称高尔基器或高尔基复合体，由一系列扁平膜囊和囊泡组成。","oe":["微管纤维束是细胞骨架结构，非高尔基体，错误。","正确，高尔基体由扁平膜囊和囊泡构成。","双层膜包围具嵴的结构是线粒体，错误。","单层膜球形水解酶囊泡是溶酶体，错误。"]},"cards":[{"front":"高尔基体的别名和基本组成是什么？","back":"又称高尔基器或高尔基复合体；由一系列扁平膜囊和囊泡组成","mnemonic":"高尔基，膜囊堆，囊泡围着转","type":"组成数字","useImg":true,"blank":"高尔基复合体","blank2":"扁平膜囊和囊泡"}],"mem":"高尔基，膜囊堆，囊泡围着转","big":"assets/img/ch03/big/p073.jpg"},{"i":23,"sec":"第三节 高尔基体","title":"高尔基体结构 (p74)","notes":"The structure and functions of Golgi complex：由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性。动物细胞高尔基体通常位于核附近。","page":74,"level":"掌握","img":"assets/img/ch03/p074.jpg","anim":null,"fig":null,"points":["由顺面、中间膜囊、反面的扁平膜囊堆叠而成，具极性","动物细胞高尔基体通常位于核附近"],"check":{"q":"关于高尔基体膜囊极性划分的叙述，正确的是？","o":["A. 仅分为内、外两层","B. 分为基质和嵴两部分","C. 分为顺面cis、中间膜囊medial和反面trans，具极性","D. 无极性，各膜囊完全相同"],"a":"C","e":"高尔基体由顺面、中间膜囊和反面的扁平膜囊堆叠而成，具极性，动物细胞中通常位于核附近。","oe":["分为内、外两层是线粒体膜的描述，错误。","基质和嵴是线粒体的结构划分，错误。","正确，高尔基体由顺面、中间膜囊、反面三部分构成且具极性。","高尔基体各膜囊有极性差异，并非完全相同，错误。"]},"cards":[{"front":"高尔基体由哪三个区室组成？其极性如何？","back":"顺面(cis)、中间膜囊(medial)、反面(trans)；具极性","mnemonic":"顺中反，一条龙","type":"组成数字","useImg":true,"blank":"极性","blank2":"顺面(cis)"},{"front":"动物细胞高尔基体通常位于何处？","back":"通常位于细胞核附近","mnemonic":"核边安家","type":"定位","useImg":false,"blank":"细胞核附近"}],"mem":"顺中反，一条龙","big":"assets/img/ch03/big/p074.jpg","terms":[{"t":"顺面","en":"cis","d":"高尔基体靠近ER的入口侧。"},{"t":"中间膜囊","en":"medial","d":"高尔基体顺面与反面之间的中部膜囊。"},{"t":"反面","en":"trans","d":"高尔基体远离ER的出口侧，蛋白质在此完成分选。"}]},{"i":24,"sec":"第三节 高尔基体","title":"动植细胞高尔基体 (p75)","notes":"The Golgi apparatus in animal and plant cells：动物细胞高尔基体多为单个，植物细胞有多个分散的高尔基体(参与细胞壁合成)。\n\n【本页英文讲解】\n本页讲动物细胞与植物细胞高尔基体（Golgi apparatus）的差异。动物细胞高尔基体通常为单个或少数，位于核附近；植物细胞则含多个分散的高尔基体，参与细胞壁成分的合成与分泌。考点：动植物高尔基体在数量、分布与功能上的差异，见教材第七章内膜系统。","page":75,"level":"理解","img":"assets/img/ch03/p075.jpg","anim":null,"fig":null,"points":null,"check":{"q":"关于动物细胞与植物细胞高尔基体的差异，正确的是？","o":["A. 动物细胞有多个分散的高尔基体，植物细胞只有一个","B. 只有动物细胞才有高尔基体，植物细胞没有","C. 动物细胞高尔基体多为单个，植物细胞有多个分散的高尔基体参与细胞壁合成","D. 植物细胞高尔基体不参与分泌，只负责储存钙"],"a":"C","e":"动物细胞高尔基体多为单个，植物细胞有多个并参与细胞壁合成。","oe":["错误：动物多为单个高尔基体，植物有多个，该项颠倒","错误：植物细胞同样具有高尔基体，只是数量与分布不同","数量分布及植物参与细胞壁合成均正确","植物高尔基体参与细胞壁合成与分泌"]},"cards":null,"mem":"动物高尔基单个；植物多个分散，参与壁合成","big":"assets/img/ch03/big/p075.jpg"},{"i":25,"sec":"第三节 高尔基体","title":"高尔基体的极性区室 (p76)","notes":"高尔基体顺面膜囊(cis Golgi)/顺面网状结构(CGN)——顺面最外侧，接收内质网合成的新物质；中间膜囊；反面膜囊(trans Golgi)/反面网状结构(TGN)——输出端，分选运往溶酶体、质膜、胞外。","page":76,"level":"掌握","img":"assets/img/ch03/p076.jpg","anim":"golgi_polarity","fig":"高尔基体的“极性”：从顺面到反面，酶的种类和膜脂组成逐渐变化。图显示不同膜囊含不同的糖基转移酶，货物依次经过并逐步加工；TGN 处有分选信号识别。","points":["高尔基体分顺面(CGN)、中间膜囊、反面(TGN)三个区。","CGN 接收 ER 来的小泡并回收 ER 驻留蛋白(KDEL/HDEL 受体)。","中间膜囊进行糖基化修饰；TGN 是分选中心，决定货物去溶酶体/分泌泡/质膜。"],"check":{"q":"关于高尔基体各极性区室的功能，下列叙述正确的是？","o":["A. TGN只回收KDEL蛋白，不参与分泌过程","B. CGN是分选中心，TGN负责接收ER来的物质","C. 中间膜囊负责接收ER小泡，CGN负责糖基化修饰","D. CGN接收ER小泡并可回收ER驻留蛋白，TGN是分选中心"],"a":"D","e":"CGN接收ER小泡并回收驻留蛋白，中间膜囊糖基化，TGN分选输出。","oe":["TGN分选运往溶酶体、质膜或胞外","错误：接收与分选功能颠倒，CGN接收、TGN分选输出","接收ER小泡的是CGN，糖基化在中间膜囊","CGN接收与回收，TGN负责分选输出"]},"cards":[{"front":"高尔基体顺面(CGN)和反面(TGN)的功能分别是什么？","back":"CGN：接收内质网合成的新物质；TGN：输出端，分选运往溶酶体、质膜、胞外","mnemonic":"顺面收货，反面发货","type":"功能","useImg":true,"blank":"TGN","blank2":"CGN"}],"mem":"顺面收货，反面发货","big":"assets/img/ch03/big/p076.jpg"},{"i":26,"sec":"第三节 高尔基体","title":"高尔基体功能1-糖基化 (p77)","notes":"高尔基体的功能1：蛋白质的糖基化——O-连接糖基化(O-linked glycosylation)在高尔基体进行：单糖逐个加到Ser/Thr羟基上。","page":77,"level":"掌握","img":"assets/img/ch03/p077.jpg","anim":null,"fig":"高尔基体的主要功能之一是糖基化：N-连接糖链在 ER 加上核心后，到高尔基体被修剪和延伸；O-连接糖链则在高尔基体直接连到 Ser/Thr。图对比 N-与 O-糖基化的部位和糖基。","points":["O-连接糖基化在高尔基体进行","单糖逐个加到Ser/Thr羟基上"],"check":{"q":"O-连接糖基化发生的主要场所及连接方式是？","o":["A. 线粒体，糖链加到谷氨酸上","B. 高尔基体，单糖逐个加到Ser/Thr的羟基上","C. 细胞质，糖链加到赖氨酸上","D. 内质网腔，寡糖链加到Asn酰胺氮上"],"a":"B","e":"O-连接糖基化在高尔基体进行，单糖逐个加到Ser/Thr的羟基上。","oe":["线粒体不是糖基化主要场所，受体残基也不对，错误。","正确，O-连接糖基化在高尔基体进行，连到丝氨酸苏氨酸羟基。","糖链并不连到赖氨酸，且场所不对，错误。","加到Asn酰胺氮的是N-连接糖基化，发生在rER，错误。"]},"cards":[{"front":"O-连接糖基化在哪里进行？糖基加到什么氨基酸上？","back":"在高尔基体进行；单糖逐个加到Ser/Thr羟基上","mnemonic":"O连高尔基，丝苏挂糖衣","type":"定位","useImg":false,"blank":"Ser/Thr","blank2":"Ser/Thr羟基"}],"mem":"O连高尔基，丝苏挂糖衣","big":"assets/img/ch03/big/p077.jpg"},{"i":27,"sec":"第三节 高尔基体","title":"N-连接糖基化完成于高尔基体 (p78)","notes":"ER Golgi：N-连接的糖基化起始于内质网，最终完成于高尔基体。糖链在高尔基体被进一步加工、修饰。","page":78,"level":"掌握","img":"assets/img/ch03/p078.jpg","anim":null,"fig":"糖蛋白从 ER 到高尔基体的加工流程：ER 加核心 N-糖链 → 高尔基体顺面切除部分甘露糖 → 中间膜囊加 GlcNAc/半乳糖 → 反面加唾液酸。图强调糖链是“逐步加工”的。","points":["N-连接的糖基化起始于内质网","最终完成于高尔基体，糖链被进一步加工修饰"],"check":{"q":"关于N-连接糖基化的发生部位，下列叙述正确的是？","o":["A. 起始和完成都在溶酶体中进行","B. 从始至终都在细胞质基质中完成","C. 起始于高尔基体，最终完成于内质网","D. 起始于内质网，最终完成于高尔基体"],"a":"D","e":"N-连接糖基化起始于内质网，最终在高尔基体加工完成。","oe":["溶酶体负责降解，不进行N-连接糖基化","糖基化在ER与高尔基体膜系统腔内进行","错误：N-连接起始于内质网、完成于高尔基体，该项颠倒","N-连接起始于ER，糖链在高尔基体进一步加工完成"]},"cards":[{"front":"N-连接糖基化的起始和完成部位分别在哪里？","back":"起始于内质网，最终完成于高尔基体；糖链在高尔基体进一步加工修饰","mnemonic":"N糖起于ER，成于高尔基","type":"流程","useImg":false,"blank":"内质网","blank2":"高尔基体"}],"mem":"N糖起于ER，成于高尔基","big":"assets/img/ch03/big/p078.jpg"},{"i":28,"sec":"第三节 高尔基体","title":"糖胺聚糖合成 (p79)","notes":"由一个或多个糖胺聚糖(glycosaminoglycan)结合到核心蛋白的丝氨酸(Ser)残基上，直接与Ser羟基结合的是N-乙酰半乳糖胺等。形成蛋白聚糖。","page":79,"level":"理解","img":"assets/img/ch03/p079.jpg","anim":null,"fig":"蛋白聚糖(proteoglycan)在高尔基体中组装：核心蛋白上连接多条糖胺聚糖(GAG)链。图显示糖链的硫酸化修饰在高尔基体完成，产物分泌到细胞外基质。","points":null,"check":{"q":"蛋白聚糖中，糖胺聚糖直接结合的氨基酸残基及第一个糖基是？","o":["A. 核心蛋白的Cys巯基，直接结合岩藻糖","B. 核心蛋白的Lys氨基，直接结合甘露糖","C. 核心蛋白的Ser羟基，直接结合N-乙酰半乳糖胺","D. 核心蛋白的Asn酰胺氮，直接结合葡萄糖"],"a":"C","e":"糖胺聚糖结合核心蛋白Ser羟基，首个糖基为N-乙酰半乳糖胺。","oe":["错误：Cys巯基参与二硫键形成，不与糖胺聚糖结合","错误：糖胺聚糖结合Ser羟基，Lys氨基不是结合位点","糖胺聚糖结合Ser羟基，首糖为N-乙酰半乳糖胺","Asn酰胺氮是N-连接糖基化位点"]},"cards":null,"mem":"糖胺聚糖接核心蛋白Ser→形成蛋白聚糖","big":"assets/img/ch03/big/p079.jpg","terms":[{"t":"糖胺聚糖","en":"glycosaminoglycan, GAG","d":"由重复二糖单位组成的长链多糖，连在核心蛋白的丝氨酸上构成蛋白聚糖。"}]}],"mcq":[{"id":"ch03_mcq_13","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素由多少个氨基酸组成？","o":["A. 76个","B. 100个","C. 50个","D. 200个"],"a":"A","e":"泛素由76个氨基酸组成，8.5×10³小分子球蛋白，高度保守，普遍存在于真核细胞。","kp":"ch03_s1_17","oe":["泛素由76个氨基酸组成，是高度保守的小分子球蛋白。","泛素并非由100个氨基酸组成，数目不对。","泛素并非由50个氨基酸组成，数目不对。","泛素并非由200个氨基酸组成，数目不对。"]},{"id":"ch03_mcq_14","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素化需要哪三种酶？","o":["A. E1、E2、E3","B. 激酶、磷酸酶、连接酶","C. PDI、Bip、SRP","D. 蛋白酶、核酸酶、脂肪酶"],"a":"A","e":"泛素活化酶(E1)、泛素结合酶(E2)、泛素连接酶(E3)。多聚泛素链是降解信号。","kp":"ch03_s1_18","oe":["泛素化需泛素活化酶E1、泛素结合酶E2和泛素连接酶E3。","激酶、磷酸酶、连接酶不是泛素化的三种酶。","PDI、Bip、SRP与泛素化过程无关。","蛋白酶、核酸酶、脂肪酶是水解酶，不参与泛素化。"]},{"id":"ch03_mcq_15","mod":"模块二：蛋白质分选与降解","modI":1,"q":"26S蛋白酶体的结构是？","o":["A. 一个20S催化核心+两个19S调节帽","B. 仅20S","C. 仅19S","D. 单链蛋白"],"a":"A","e":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，由约50种亚基构成，降解泛素化蛋白。","kp":"ch03_s1_19","oe":["26S蛋白酶体由20S催化核心和两个19S调节帽组成。","26S蛋白酶体不只含20S，还含19S调节帽。","26S蛋白酶体并非仅由19S组成。","26S蛋白酶体是多亚基复合体，不是单链蛋白。"]},{"id":"ch03_mcq_16","mod":"模块二：蛋白质分选与降解","modI":1,"q":"高尔基体的极性区室中,接收内质网物质的是？","o":["A. 顺面(CGN)","B. 反面(TGN)","C. 中间膜囊","D. 溶酶体"],"a":"A","e":"顺面网状结构(CGN)接收内质网新物质；反面膜囊(TGN)是输出端，分选运往溶酶体/质膜/胞外。","kp":"ch03_s1_25","oe":["顺面网状结构(CGN)接收内质网运来的新物质。","反面(TGN)是输出端，分选运往溶酶体、质膜或胞外。","中间膜囊负责加工修饰，不接收ER来向物质。","溶酶体不是高尔基体的极性区室。"]},{"id":"ch03_mcq_17","mod":"模块二：蛋白质分选与降解","modI":1,"q":"O-连接糖基化发生在？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 细胞核"],"a":"B","e":"O-连接糖基化在高尔基体进行(单糖逐个加到Ser/Thr)；N-连接起始于ER、完成于高尔基体。","kp":"ch03_s1_2","oe":["内质网主要进行N-连接糖基化，不是O-连接。","O-连接糖基化在高尔基体进行，单糖加到Ser/Thr上。","溶酶体负责分解，不进行O-连接糖基化。","细胞核不是糖基化场所，糖基化在内质网和高尔基体。"]},{"id":"ch03_mcq_18","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体内部维持酸性环境(pH≈5)依靠？","o":["A. H+泵(质子泵)","B. Na+/K+泵","C. Ca2+泵","D. 水通道"],"a":"A","e":"溶酶体膜上的H+-pumps将H+泵入，维持内部pH≈5，使酸性水解酶活性最高。","kp":"ch03_s1_19","oe":["溶酶体膜上的H+泵将H+泵入，维持腔内pH约5。","Na+/K+泵维持细胞内外钠钾梯度，不使溶酶体酸化。","Ca2+泵与溶酶体酸性环境的维持无关。","水通道只转运水，不参与溶酶体酸化。"]},{"id":"ch03_mcq_19","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体酶的靶向分选信号是？","o":["A. 6-磷酸甘露糖(M6P)","B. KDEL","C. NLS","D. 信号肽"],"a":"A","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别分选到溶酶体。","kp":"ch03_s1_3","oe":["溶酶体酶的靶向分选信号是6-磷酸甘露糖(M6P)。","KDEL是ER驻留信号，使蛋白滞留在内质网。","NLS是核定位信号，引导蛋白进入细胞核。","信号肽引导蛋白进入内质网，不是溶酶体靶向信号。"]},{"id":"ch03_mcq_20","mod":"模块二：蛋白质分选与降解","modI":1,"q":"细胞自噬(autophagy)是指？","o":["A. 吞噬外源细菌","B. 降解细胞自身老化废弃的细胞器和大分子","C. 分泌蛋白","D. 细胞分裂"],"a":"B","e":"自噬是细胞在自噬相关基因调控下，对自身受损或需淘汰更新的物质(线粒体、过氧化物酶体等)进行降解再利用。","kp":"ch03_s1_24","oe":["吞噬外源细菌是吞噬作用，不属于自噬。","自噬是降解细胞自身老化废弃的细胞器和大分子。","分泌蛋白属于分泌途径，与自噬不同。","细胞分裂属于增殖过程，与自噬的降解功能无关。"]},{"id":"ch03_mcq_21","mod":"模块二：蛋白质分选与降解","modI":1,"q":"N-连接糖基化连接的氨基酸残基是？","o":["A. 天冬酰胺(Asn)","B. 丝氨酸(Ser)","C. 苏氨酸(Thr)","D. 赖氨酸(Lys)"],"a":"A","e":"N-连接糖基化连接Asn(序列Asn-X-Ser/Thr)；O-连接连接Ser/Thr羟基。","kp":"ch03_s1_2","oe":["N-连接糖基化连接的氨基酸残基是天冬酰胺(Asn)。","丝氨酸是O-连接糖基化的连接位点。","苏氨酸也是O-连接糖基化的连接位点。","赖氨酸不参与N-连接糖基化，N-连接位点是天冬酰胺。"]},{"id":"ch03_mcq_22","mod":"模块二：蛋白质分选与降解","modI":1,"q":"膜脂(甘油磷脂和胆固醇)主要在何处合成？","o":["A. 光面内质网","B. 高尔基体","C. 线粒体","D. 细胞核"],"a":"A","e":"sER合成构成细胞所需的绝大多数膜脂(甘油磷脂和胆固醇)，再运往其他膜。","kp":"ch03_s1_28","oe":["光面内质网合成甘油磷脂和胆固醇等膜脂。","高尔基体主要加工分选，不主要负责合成膜脂。","线粒体主要供能，膜脂合成主要在内质网。","细胞核不合成膜脂，膜脂合成主要在内质网。"]},{"id":"ch03_mcq_23","mod":"模块二：蛋白质分选与降解","modI":1,"q":"微粒体(microsome)是？","o":["A. 完整线粒体","B. 破碎内质网自我融合形成的囊泡","C. 溶酶体","D. 高尔基体"],"a":"B","e":"微粒体是体外实验中细胞匀浆和差速离心得到的、由分离的内质网自我融合形成的球形囊泡，是研究ER的模型。","kp":"ch03_s1_20","oe":["微粒体是由内质网形成的囊泡，不是完整线粒体。","微粒体是破碎内质网自我融合形成的囊泡。","微粒体来源于内质网，不是溶酶体。","微粒体来源于破碎的内质网，不是高尔基体。"]},{"id":"ch03_mcq_24","mod":"模块二：蛋白质分选与降解","modI":1,"q":"sER的储钙功能依靠？","o":["A. Ca2+-ATPase将钙泵入ER","B. 钙通道外流","C. Na+/K+泵","D. 质子泵"],"a":"A","e":"ER膜上的Ca2+-ATPase将细胞基质中的钙泵入ER储存，使ER腔钙浓度高达3mM，参与信号传递。","kp":"ch03_s1_21","oe":["ER膜上的Ca2+-ATPase将钙泵入ER储存。","钙通道外流会释放钙，与储钙作用相反。","Na+/K+泵与ER的储钙功能无关。","质子泵维持溶酶体酸性，不负责ER储钙。"]},{"id":"ch03_mcq_25","mod":"模块二：蛋白质分选与降解","modI":1,"q":"ER质量监控的意义是？","o":["A. 所有蛋白都能离开ER","B. 只有正确折叠和装配的蛋白才能离开ER","C. 错误折叠蛋白直接分泌","D. 阻止所有蛋白合成"],"a":"B","e":"ER质量监控：只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被逆向转运至胞质经泛素-蛋白酶体降解(ERAD)。","kp":"ch03_s1_14","oe":["并非所有蛋白都能离开ER，只有正确折叠装配者可以。","ER质量监控确保只有正确折叠和装配的蛋白才能离开ER。","错误折叠蛋白被滞留降解，不会直接分泌。","质量监控是筛选而非阻止所有蛋白质的合成。"]}],"judge":[{"id":"ch03_judge_5","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个7S RNA组成。","a":"对","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，识别信号肽并使翻译暂停。","kp":"ch03_s1_13","oe":["SRP由6种多肽和1个300核苷酸(7S)RNA组成，识别信号肽并暂停翻译。","误记SRP组分数或RNA类型，如说由6种RNA组成，故判错。"]},{"id":"ch03_judge_6","modI":1,"q":"N-连接糖基化起始于内质网，O-连接糖基化发生在高尔基体。","a":"对","e":"N-连接起始于rER、结合Asn；O-连接在高尔基体进行、结合Ser/Thr。","kp":"ch03_s1_27","oe":["N-连接糖基化起始于rER并结合Asn，O-连接发生在高尔基体并结合Ser/Thr。","误以为两者都在同一部位发生，或把N、O连接地点与氨基酸记反，故判错。"]},{"id":"ch03_judge_7","modI":1,"q":"泛素由76个氨基酸组成，泛素化需要E1、E2、E3三种酶。","a":"对","e":"泛素由76个氨基酸组成；E1活化酶、E2结合酶、E3连接酶共同完成泛素化。","kp":"ch03_s1_18","oe":["泛素由76个氨基酸组成，泛素化需E1活化、E2结合、E3连接三种酶。","误记泛素氨基酸数或所需酶的种类与数量，如说只需E1、E2，故判错。"]},{"id":"ch03_judge_8","modI":1,"q":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，降解泛素化蛋白。","a":"对","e":"26S蛋白酶体=20S催化核心+两个19S调节帽，识别多聚泛素链并降解蛋白。","kp":"ch03_s1_20","oe":["26S蛋白酶体由20S催化核心和两个19S调节帽组成，降解泛素化蛋白。","误把核心与调节帽的沉降系数或数量记错，如20S帽、19S核心，故判错。"]}],"fill":[{"id":"ch03_fill_4","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个________组成,识别新生肽的________并使翻译暂停。","a":"7S RNA,信号肽","kp":"ch03_s1_4","oe":["SRP含1分子7S RNA和6种多肽，7S RNA是其特征性核酸成分。","SRP识别新生肽N端的信号肽并结合，使翻译暂停。"]},{"id":"ch03_fill_5","modI":1,"q":"N-连接糖基化连接________残基,起始于________；O-连接糖基化连接________残基,发生在________。","a":"天冬酰胺(Asn),内质网,丝氨酸/苏氨酸(Ser/Thr),高尔基体","kp":"ch03_s1_2","oe":["N-连接糖基化发生于天冬酰胺残基的酰胺氮上，故填Asn。","N-连接糖基化在内质网腔内起始，先接核心寡糖再加工。","O-连接糖基化连接丝氨酸或苏氨酸残基的羟基氧，故填Ser/Thr。","O-连接糖基化主要在高尔基体中进行，故填高尔基体。"]},{"id":"ch03_fill_6","modI":1,"q":"ER驻留蛋白的驻留信号是________；溶酶体酶的分选信号是________。","a":"KDEL序列,6-磷酸甘露糖(M6P)","kp":"ch03_s1_13","oe":["ER驻留蛋白C端的KDEL序列被受体识别，经COPI小泡回收回ER。","溶酶体酶在高尔基体被标记6-磷酸甘露糖，经M6P受体分选入溶酶体。"]},{"id":"ch03_fill_7","modI":1,"q":"泛素由________个氨基酸组成；泛素化需要________、________、________三种酶。","a":"76,E1(活化酶),E2(结合酶),E3(连接酶)","kp":"ch03_s1_18","oe":["泛素是由76个氨基酸组成的小分子调控蛋白，故填76。","E1以ATP供能活化泛素，形成E1-泛素硫酯键。","E2承接并携带活化泛素，与E3协同完成泛素连接。","E3识别底物并催化泛素连接到靶蛋白的赖氨酸残基上。"]},{"id":"ch03_fill_8","modI":1,"q":"26S蛋白酶体由20S________和两个19S________组成,降解泛素化的蛋白质。","a":"催化核心,调节帽","kp":"ch03_s1_19","oe":["20S为圆柱形复合体，含蛋白酶活性位点，是降解肽链的催化核心。","两个19S调节帽位于20S两端，负责识别、解折叠并送入底物。"]}],"short":[{"id":"ch03_short_1","modI":1,"q":"简述信号肽假说及分泌蛋白共翻译转移的过程。","a":"信号肽假说(1975年提出)：\n\n【过程】\n①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽(signal peptide)伸出；\n②信号识别颗粒(SRP，6种多肽+7S RNA)识别并结合信号肽及核糖体大亚基→翻译暂停；\n③SRP-核糖体复合物结合内质网膜上的SRP受体(停泊蛋白DP)；\n④核糖体附着到rER膜上，SRP释放，翻译恢复；\n⑤肽链边延伸边穿过易位子(translocon，核心Sec61)进入ER腔；\n⑥信号肽被信号肽酶切除，蛋白在ER腔折叠、修饰。\n\n【证据】1972年Milstein发现细胞内的免疫球蛋白N端比分泌到胞外的多一截(信号肽)。\n\n【意义】解释了分泌蛋白、膜蛋白如何定向进入ER。","kp":"ch03_s1_13"},{"id":"ch03_short_3","modI":1,"q":"简述蛋白质糖基化的类型、部位和生物学功能。","a":"蛋白质糖基化类型：\n\n【N-连接糖基化】\n• 合成部位：起始于粗面内质网；\n• 结合残基：天冬酰胺(Asn)，序列Asn-X-Ser/Thr；\n• 方式：来自同一个寡糖前体(连在磷酸多萜醇上)整体转移。\n\n【O-连接糖基化】\n• 合成部位：高尔基体；\n• 结合残基：丝氨酸/苏氨酸(Ser/Thr)羟基；\n• 方式：一个个单糖加上去。\n\n【生物学功能】\n①促进蛋白质折叠(如抗体IgG、质膜糖蛋白血凝素)；\n②影响蛋白稳定性、半衰期和运输；\n③参与细胞识别与免疫(如血型抗原)；\n④溶酶体酶的M6P分选信号；\n⑤负责糖链合成加工的酶均为管家基因编码。","kp":"ch03_s1_3"},{"id":"ch03_short_4","modI":1,"q":"简述泛素-蛋白酶体系统降解蛋白质的机制。","a":"泛素-蛋白酶体系统(2004年诺贝尔化学奖)：\n\n【泛素】\n由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞。\n\n【泛素化过程】\n①E1(泛素活化酶)消耗ATP激活泛素；\n②E2(泛素结合酶)接受活化泛素；\n③E3(泛素连接酶)识别靶蛋白并将泛素转移至靶蛋白的赖氨酸残基；\n④多轮循环形成多聚泛素链(降解信号)。\n\n【蛋白酶体降解】\n26S蛋白酶体=20S催化核心+两个19S调节帽，由约50种亚基组成。\n①19S帽识别多聚泛素链；\n②去折叠、去泛素化；\n③20S核心催化降解为短肽；\n④泛素可回收再利用。\n\n【意义】\n调控细胞周期、凋亡、信号转导等；错误折叠蛋白(ERAD)也经此降解。","kp":"ch03_s1_20"},{"id":"ch03_short_5","modI":1,"q":"比较N-连接和O-连接糖基化。","a":"N-连接 vs O-连接糖基化：\n\n| 特征 | N-连接 | O-连接 |\n|---|---|---|\n| 合成部位 | 起始于粗面内质网(完成于高尔基体) | 高尔基体 |\n| 合成方式 | 来自同一个寡糖前体整体转移 | 一个个单糖加上去 |\n| 结合残基 | 天冬酰胺Asn(Asn-X-Ser/Thr) | 丝氨酸/苏氨酸Ser/Thr羟基 |\n| 前体 | 磷酸多萜醇(dolichol)连接的寡糖 | 单糖核苷酸 |\n\n【共同点】\n①都属于蛋白质翻译后修饰；\n②都由糖基转移酶催化；\n③糖链都位于细胞外侧/ER腔侧。\n\n【生物学功能】\n促进折叠、影响稳定性与半衰期、参与细胞识别与免疫、M6P分选信号等。","kp":"ch03_s1_2"}],"calc":[],"term":[{"id":"ch03_term_5","modI":1,"term":"信号肽(Signal Peptide)","def":"①位于分泌蛋白N端、引导蛋白进入ER的短肽序列（定义）。②特点：通常位于N端，完成使命后被信号肽酶切除（特点）。③机制：被SRP识别→核糖体停泊到ER膜→共翻译转移（机制）。④证据：1972年Milstein发现细胞内免疫球蛋白N端比胞外多一截（证据）。","kps":"踩分点:①定义(1分)②特点(1分)③机制(1分)④证据(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_6","modI":1,"term":"信号识别颗粒(SRP)","def":"①由6种多肽和1个300核苷酸(7S)RNA组成的核糖核蛋白复合物（定义）。②功能：既结合新生肽信号序列，又结合核糖体大亚基，使翻译暂停（功能）。③作用：将核糖体引导到ER膜的SRP受体(停泊蛋白DP)上（作用）。","kps":"踩分点:①组成(1分)②功能(2分)③与SRP受体(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_9","modI":1,"term":"泛素(Ubiquitin)","def":"①由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞（定义）。②功能：作为蛋白质降解的标签，共价结合到靶蛋白赖氨酸残基上（功能）。③泛素化需E1/E2/E3三种酶，多聚泛素链是降解信号（机制）。④发现获2004年诺贝尔化学奖（意义）。","kps":"踩分点:①定义(1分)②功能(1分)③三种酶(1分)④诺贝尔奖(1分)","kp":"ch03_s1_17"},{"id":"ch03_term_10","modI":1,"term":"蛋白酶体(Proteasome)","def":"①细胞内降解蛋白质的大分子复合体，由约50种亚基组成（定义）。②结构：26S蛋白酶体=20S催化核心+两个19S调节帽（结构）。③功能：识别多聚泛素链，将泛素化蛋白降解为短肽（功能）。","kps":"踩分点:①定义(1分)②结构(2分)③功能(1分)","kp":"ch03_s1_20"},{"id":"ch03_term_16","modI":1,"term":"ER驻留信号(KDEL)","def":"①内质网驻留蛋白C端的一段回收信号序列(KDEL)（定义）。②功能：使Bip、PDI等驻留蛋白被保留在ER中而不被分泌（功能）。③机制：逃逸到高尔基体的驻留蛋白经KDEL受体识别，由COPI小泡回收回ER（机制）。","kps":"踩分点:①定义(1分)②功能(1分)③回收机制(2分)","kp":"ch03_s1_13"}]},{"i":2,"name":"模块三：高尔基体与溶酶体","slides":[{"i":0,"sec":"第三节 高尔基体","title":"高尔基体功能2-分选枢纽 (p80)","notes":"高尔基体功能2：蛋白质加工、修饰、分类装载运输的分选站(枢纽作用)。通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖蛋白的信号序列和受体之间的相互作用。","page":80,"level":"掌握","img":"assets/img/ch03/p080.jpg","anim":null,"fig":"TGN 是细胞内蛋白质分选的“交通枢纽”：根据货物携带的信号，把它们分装到不同小泡——去溶酶体(M6P 信号)、去分泌泡(调节性分泌)、去质膜(组成性分泌)。图是分选的“多岔路口”。","points":["高尔基体是蛋白质加工、修饰、分类装载运输的分选枢纽","经膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外","依赖蛋白信号序列与受体之间的相互作用"],"check":{"q":"高尔基体作为分选站将蛋白运往不同目的地，主要依赖？","o":["A. 细胞质基质中的随机扩散运动","B. 核糖体对mRNA的重新翻译过程","C. 溶酶体酸性水解酶的催化作用","D. 蛋白的信号序列与受体之间的相互作用"],"a":"D","e":"高尔基体是分选枢纽，依赖信号序列与受体的相互作用定向运输。","oe":["错误：分选依赖信号序列与受体的特异识别，而非随机扩散","错误：分选发生在翻译之后，与mRNA重新翻译无直接关系","错误：酸性水解酶负责降解，不参与高尔基体的分选","分选依赖信号序列与受体的特异相互作用"]},"cards":[{"front":"高尔基体作为分选枢纽的功能是什么？","back":"蛋白质加工、修饰、分类装载运输；通过膜泡运往溶酶体、质膜或胞外","mnemonic":"加工分类再装车，信号受体来配对","type":"功能","useImg":false,"blank":"分类装载运输","blank2":"溶酶体"}],"mem":"加工分类再装车，信号受体来配对","big":"assets/img/ch03/big/p080.jpg"},{"i":1,"sec":"第四节 溶酶体","title":"溶酶体概述 (p81)","notes":"3.3 溶酶体(Lysosomes)：存在于几乎所有动物细胞中，植物细胞对应液泡。单层膜，内含多种酸性水解酶类(酶活性最适pH为5左右)。是细胞的'消化系统'。","page":81,"level":"掌握","img":"assets/img/ch03/p081.jpg","anim":null,"fig":null,"points":["存在于几乎所有动物细胞中，植物细胞对应液泡","单层膜，含多种酸性水解酶（最适pH约5）","是细胞的“消化系统”"],"check":{"q":"关于溶酶体，下列叙述正确的是？","o":["A. 不含水解酶，主要功能是储存Ca²⁺","B. 双层膜，含多种最适pH呈碱性的水解酶","C. 单层膜，含多种最适pH约5的酸性水解酶，是细胞的消化系统","D. 仅存在于植物细胞，动物细胞中不含溶酶体"],"a":"C","e":"溶酶体单层膜，含酸性水解酶，最适pH约5，是细胞的消化系统。","oe":["错误：溶酶体含有大量酸性水解酶，并非只储存Ca²⁺","溶酶体为单层膜且酶最适pH为酸性","溶酶体单层膜、酸性水解酶最适pH约5","溶酶体存在于动物细胞，植物对应液泡"]},"cards":[{"front":"溶酶体的结构特点和酶的最适pH是多少？","back":"单层膜；含多种酸性水解酶，最适pH约5","mnemonic":"单膜酸酶pH五","type":"组成数字","useImg":false,"blank":"酸性水解酶","blank2":"单层膜"},{"front":"溶酶体存在于哪些细胞？植物细胞对应什么结构？","back":"几乎存在于所有动物细胞；植物细胞对应液泡","mnemonic":"动物溶酶体，植物用液泡","type":"对比","useImg":false,"blank":"液泡","blank2":"动物细胞"}],"mem":"单膜酸酶pH五","big":"assets/img/ch03/big/p081.jpg"},{"i":2,"sec":"第四节 溶酶体","title":"溶酶体的异质性 (p82)","notes":"溶酶体是异质性细胞器：不同来源、不同发育阶段的溶酶体形态大小、所含水解酶类都可能不同。根据生理阶段分为：初级溶酶体(刚形成)、次级溶酶体(正在消化)、残余小体。","page":82,"level":"掌握","img":"assets/img/ch03/p082.jpg","anim":null,"fig":"溶酶体的三种状态：初级溶酶体(新形成、未消化)→次级溶酶体(正在消化胞吞物或自噬物)→残余体(消化后残渣)。图强调溶酶体是“动态变化”的细胞器。","points":["溶酶体是异质性细胞器：不同来源/发育阶段形态大小、酶种类不同。","初级溶酶体：只含酸性水解酶，无消化作用。","次级溶酶体：正在消化(含底物)；分自噬溶酶体、异噬溶酶体。"],"check":{"q":"关于初级溶酶体与次级溶酶体的叙述，正确的是？","o":["A. 次级溶酶体不含水解酶","B. 初级溶酶体正在消化底物","C. 残余小体是最初形成的溶酶体","D. 初级溶酶体只含酸性水解酶，尚无消化作用"],"a":"D","e":"溶酶体是异质性细胞器，初级溶酶体刚形成、只含酸性水解酶而无消化作用，次级溶酶体正在消化，残余小体为消化后残留。","oe":["次级溶酶体含水解酶并正在消化，错误。","正在消化底物的是次级溶酶体，错误。","残余小体是消化后的残留结构，并非最初形成，错误。","正确，初级溶酶体只含酸性水解酶，尚无消化作用。"]},"cards":[{"front":"溶酶体按生理阶段分为哪三类？","back":"初级溶酶体（刚形成）；次级溶酶体（正在消化）；残余小体","mnemonic":"初生→消化→残渣","type":"流程","useImg":false,"blank":"初级溶酶体","blank2":"次级溶酶体"},{"front":"为什么说溶酶体是异质性细胞器？","back":"来源、发育阶段不同，其形态大小和所含水解酶类均可不同","mnemonic":"","type":"定义","useImg":false,"blank":"水解酶类","blank2":"发育阶段"}],"mem":"初生→消化→残渣","big":"assets/img/ch03/big/p082.jpg"},{"i":3,"sec":"第四节 溶酶体","title":"溶酶体电镜图 (p83)","notes":"小鼠膀胱上皮细胞中的溶酶体——电镜显示其单层膜包围的、含水解酶的囊泡结构。","page":83,"level":"理解","img":"assets/img/ch03/p083.jpg","anim":null,"fig":null,"points":null,"check":{"q":"电镜下溶酶体的典型形态特征是？","o":["A. 由双层膜包围、含嵴的结构","B. 无膜包围的致密颗粒","C. 由蛋白质纤维组成的管状结构","D. 由单层膜包围、内含水解酶的囊泡"],"a":"D","e":"电镜显示溶酶体为单层膜包围、内含水解酶的囊泡结构。","oe":["具有双层膜并含嵴的结构是线粒体，与溶酶体不符，错误。","溶酶体有膜包围，并非无膜致密颗粒，错误。","蛋白质纤维管状结构属细胞骨架，错误。","正确，溶酶体是单层膜包围、含水解酶的囊泡。"]},"cards":null,"mem":"溶酶体：单层膜囊泡，内含水解酶","big":"assets/img/ch03/big/p083.jpg"},{"i":4,"sec":"第四节 溶酶体","title":"溶酶体的消化类型 (p84)","notes":"溶酶体的消化类型：phagocytosis(吞噬)——细菌、微小生物、衰老红细胞；autophagy(自噬)——细胞本身老化废弃的部分，如线粒体、过氧化物酶体、生物大分子。","page":84,"level":"掌握","img":"assets/img/ch03/p084.jpg","anim":"lysosome_formation","fig":"溶酶体的形成有两条途径：①内体途径——胞吞物经早期/晚期内体与溶酶体融合；②自噬途径——细胞内结构被自噬体包裹后与溶酶体融合。图显示两条来源最终都汇入溶酶体。","points":["吞噬：细菌、微小生物、衰老红细胞","自噬：细胞本身老化废弃的部分，如线粒体、过氧化物酶体、生物大分子"],"check":{"q":"溶酶体消化细胞自身衰老细胞器(如线粒体)的过程称为？","o":["A. 胞饮(pinocytosis)","B. 受体介导的内吞","C. 吞噬(phagocytosis)","D. 自噬(autophagy)"],"a":"D","e":"自噬消化细胞自身老化废弃的细胞器与生物大分子。","oe":["错误：胞饮主要摄取细胞外的液体物质，非消化自身细胞器","受体介导内吞摄取特定生物大分子","吞噬针对细菌、衰老红细胞等外来物","自噬指消化细胞本身老化废弃的部分"]},"cards":[{"front":"溶酶体的两种消化类型及其对象分别是什么？","back":"吞噬：细菌、微小生物、衰老红细胞；自噬：老化细胞器（线粒体、过氧化物酶体）、生物大分子","mnemonic":"外来叫吞噬，内耗叫自噬","type":"对比","useImg":false,"blank":"自噬","blank2":"吞噬"}],"mem":"外来叫吞噬，内耗叫自噬","big":"assets/img/ch03/big/p084.jpg","terms":[{"t":"胞饮","en":"pinocytosis","d":"细胞摄入液体和溶质的小泡内吞方式。"},{"t":"吞噬","en":"phagocytosis","d":"细胞摄入大颗粒（如细菌）的内吞方式。"}]},{"i":5,"sec":"第四节 溶酶体","title":"溶酶体的特点 (p85)","notes":"特点② Lysosomes contain plenty of acid hydrolases(酸性水解酶)，可消化各种生物大分子。酶在酸性环境(pH≈5)下活性最高。\n\n【本页英文讲解】\n本页讲溶酶体（lysosome）的特点。溶酶体含有大量酸性水解酶（acid hydrolases），可消化蛋白质、核酸、多糖、脂类等各种生物大分子；这些酶在酸性环境（pH≈5）下活性最高，而溶酶体膜上的质子泵维持腔内酸性。考点：溶酶体酶的最适pH及其与细胞质（pH≈7.2）的差异，见教材第七章。","page":85,"level":"掌握","img":"assets/img/ch03/p085.jpg","anim":null,"fig":"溶酶体含酸性水解酶(如酸性磷酸酶)，最适 pH≈5。图显示溶酶体膜上的 H⁺ 泵维持腔内酸性；酸性磷酸酶是溶酶体的标志酶。水解酶可分解蛋白质、核酸、脂类、糖类等。","points":["含大量酸性水解酶，可消化蛋白质、核酸、多糖、脂类等","酶在酸性环境(pH≈5)下活性最高"],"check":{"q":"溶酶体酸性水解酶活性最高的pH及维持其酸性的机制是？","o":["A. pH≈7.2，由细胞质中的缓冲对维持","B. pH≈9，由细胞膜上的钠钾泵维持","C. pH≈5，由核孔复合体维持腔内酸性","D. pH≈5，由溶酶体膜上的质子泵维持"],"a":"D","e":"溶酶体酸性水解酶最适pH约5，腔内酸性由质子泵维持。","oe":["pH7.2为细胞质环境，非溶酶体腔内","错误：钠钾泵不维持溶酶体酸性，其酸性由质子泵维持","核孔复合体与溶酶体pH维持无关","酶最适pH约5，腔内酸性由质子泵维持"]},"cards":[{"front":"溶酶体为什么能消化各种生物大分子？","back":"含大量酸性水解酶；在酸性环境（pH≈5）下活性最高","mnemonic":"酸酶酸中才干活","type":"功能","useImg":false,"blank":"酸性水解酶","blank2":"酸性环境"}],"mem":"酸酶酸中才干活","big":"assets/img/ch03/big/p085.jpg","terms":[{"t":"酸性水解酶","en":"acid hydrolases","d":"溶酶体内最适pH偏酸、能水解蛋白质/核酸/脂类等的水解酶；溶酶体含大量此类酶。"}]},{"i":6,"sec":"第四节 溶酶体","title":"溶酶体膜的质子泵 (p86)","notes":"③溶酶体膜：H+-pumps(质子泵)将H+泵入溶酶体，维持内部质子浓度(pH≈5)；膜蛋白高度糖基化保护膜不被自身水解酶消化。","page":86,"level":"掌握","img":"assets/img/ch03/p086.jpg","anim":"lysosome_proton_pump","fig":null,"points":["膜上H⁺泵将H⁺泵入，维持内腔pH≈5","膜蛋白高度糖基化，保护膜不被自身水解酶消化"],"check":{"q":"溶酶体膜上质子泵的作用及膜的保护机制是？","o":["A. 泵入Ca2+维持中性环境","B. 泵出H+使内部呈碱性","C. 泵入H+维持内部pH≈5，膜蛋白高度糖基化防止自身消化","D. 泵入H+使内部pH≈7，膜蛋白为脂类"],"a":"C","e":"溶酶体膜的H+泵将H+泵入，维持内部pH≈5；膜蛋白高度糖基化，保护膜不被自身水解酶消化。","oe":["溶酶体靠H+泵而非Ca2+泵，内部为酸性，错误。","质子泵泵入H+而非泵出，内部呈酸性，错误。","正确，质子泵维持pH≈5，糖基化膜蛋白保护膜。","溶酶体内部呈酸性约pH5，而非中性pH7，故错误。"]},"cards":[{"front":"溶酶体膜如何维持内部酸性并自我保护？","back":"H+泵泵入H+维持pH≈5；膜蛋白高度糖基化，防止被自身水解酶消化","mnemonic":"泵酸护糖衣","type":"组成数字","useImg":true,"blank":"H+泵","blank2":"膜蛋白高度糖基化"}],"mem":"泵酸护糖衣","big":"assets/img/ch03/big/p086.jpg"},{"i":7,"sec":"第四节 溶酶体","title":"溶酶体的功能 (p87)","notes":"The Functions of Lysosomes——消化：'清道夫'，清除无用的生物大分子、衰老的细胞器、凋亡细胞及吞噬的营养大分子颗粒等。","page":87,"level":"掌握","img":"assets/img/ch03/p087.jpg","anim":null,"fig":null,"points":["消化“清道夫”：清除无用的生物大分子、衰老的细胞器、凋亡细胞及吞噬的营养大分子颗粒"],"check":{"q":"溶酶体的“清道夫”功能主要体现为？","o":["A. 清除无用的生物大分子、衰老细胞器及吞噬的营养颗粒","B. 复制DNA并分配染色体","C. 合成蛋白质并分泌到胞外","D. 合成ATP为细胞供能"],"a":"A","e":"溶酶体作为清道夫，消化清除无用的生物大分子、衰老细胞器、凋亡细胞及吞噬的营养颗粒等。","oe":["正确，溶酶体清除无用大分子、衰老细胞器等。","DNA复制与染色体分配属细胞核功能，错误。","合成并分泌蛋白质是内质网与高尔基体的功能，错误。","合成ATP主要由线粒体完成，并非溶酶体的功能，错误。"]},"cards":[{"front":"溶酶体作为'清道夫'主要清除哪些物质？","back":"无用生物大分子；衰老细胞器；凋亡细胞；吞噬的营养大分子颗粒","mnemonic":"废料、旧件、死细胞、外来货","type":"功能","useImg":false,"blank":"衰老细胞器","blank2":"凋亡细胞"}],"mem":"废料、旧件、死细胞、外来货","big":"assets/img/ch03/big/p087.jpg"},{"i":8,"sec":"第四节 溶酶体","title":"中性粒细胞吞噬 (p88)","notes":"A phagocytic white blood cell(a neutrophil) ingesting a bacterium——中性粒细胞吞噬细菌，溶酶体参与杀菌消化。\n\n【本页英文讲解】\n本页讲中性粒细胞（neutrophil）的吞噬作用。吞噬性白细胞（中性粒细胞）摄入细菌（ingesting a bacterium），形成吞噬体后与溶酶体融合，由溶酶体酶将细菌杀死并消化。这体现了溶酶体的消化与防御功能。考点：吞噬（phagocytosis）过程及溶酶体在其中的作用，见教材第七章。","page":88,"level":"理解","img":"assets/img/ch03/p088.jpg","anim":null,"fig":null,"points":null,"check":{"q":"中性粒细胞吞噬细菌后，杀灭并消化细菌的过程是？","o":["A. 细菌在线粒体中被氧化分解","B. 细菌直接在胞质中被核糖体降解","C. 细菌被高尔基体直接分泌到胞外","D. 吞噬体与溶酶体融合，由溶酶体酶杀菌消化"],"a":"D","e":"中性粒细胞吞噬细菌形成吞噬体，与溶酶体融合后由溶酶体酶将细菌杀死并消化。","oe":["线粒体不参与对细菌的吞噬消化，错误。","核糖体负责蛋白质合成，不降解细菌，错误。","高尔基体不直接分泌细菌到胞外，错误。","正确，吞噬体与溶酶体融合，溶酶体酶杀菌消化。"]},"cards":null,"mem":"中性粒细胞吞菌，吞噬体+溶酶体杀菌消化","big":"assets/img/ch03/big/p088.jpg"},{"i":9,"sec":"第四节 溶酶体","title":"溶酶体与蛋白存量调节 (p89)","notes":"细胞处于不同分化阶段、不同生理状态下需要特定蛋白维持生命活动。真核细胞对蛋白质存量的调节，除泛素降解途径外，溶酶体是另一个重要途径。","page":89,"level":"掌握","img":"assets/img/ch03/p089.jpg","anim":null,"fig":null,"points":["真核细胞对蛋白质存量的调节，除泛素降解途径外，溶酶体是另一个重要途径"],"check":{"q":"真核细胞调节蛋白质存量的两条主要降解途径是？","o":["A. 糖酵解途径与三羧酸循环","B. 转录途径与翻译途径","C. 泛素-蛋白酶体途径与溶酶体途径","D. 有氧呼吸与无氧呼吸"],"a":"C","e":"真核细胞对蛋白质存量的调节除泛素降解途径外，溶酶体是另一个重要的降解途径。","oe":["错：二者属于细胞的糖代谢途径，不符合本页所学概念","错：二者属于基因表达的过程，不符合本页所学概念","对：笔记指出溶酶体是另一重要途径","错：二者属于细胞的能量代谢方式"],"basis":"除泛素降解途径外，溶酶体是另一个重要途径"},"cards":[{"front":"真核细胞调节蛋白质存量的两条降解途径是什么？","back":"泛素降解途径；溶酶体途径","mnemonic":"泛素+溶酶体，双保险","type":"对比","useImg":false,"blank":"泛素降解途径","blank2":"溶酶体途径"}],"mem":"泛素+溶酶体，双保险","big":"assets/img/ch03/big/p089.jpg"},{"i":10,"sec":"第四节 溶酶体","title":"细胞自噬 (p90)","notes":"细胞自噬与生物大分子、细胞器的降解：自噬相关基因调控下，对细胞内受损或需要淘汰更新的物质进行再利用。在自噬信号刺激下形成自噬体，与溶酶体融合降解。","page":90,"level":"掌握","img":"assets/img/ch03/p090.jpg","anim":"autophagy","fig":null,"points":["自噬相关基因调控下，对细胞内受损或需淘汰更新的物质进行再利用","自噬体形成后与溶酶体融合降解"],"check":{"q":"细胞自噬降解细胞内物质的基本过程是？","o":["A. 自噬体直接与细胞膜融合将物质排出","B. 自噬相关基因调控下形成自噬体，与溶酶体融合后降解","C. 自噬体进入细胞核内降解","D. 自噬体与线粒体融合产生ATP"],"a":"B","e":"在自噬信号刺激下，自噬相关基因调控形成自噬体，与溶酶体融合后降解受损或需淘汰更新的物质。","oe":["自噬体与溶酶体融合而非直接排出胞外，错误。","正确，自噬体与溶酶体融合降解胞内物质。","自噬降解在溶酶体中进行而不在细胞核内，故错误。","自噬体与溶酶体融合，而非与线粒体融合产ATP，错误。"]},"cards":[{"front":"细胞自噬的基本过程是什么？","back":"自噬信号刺激下形成自噬体；自噬体与溶酶体融合降解；受自噬相关基因调控，实现物质再利用","mnemonic":"包起来→送溶酶体→回收","type":"流程","useImg":true,"blank":"自噬体","blank2":"溶酶体"}],"mem":"包起来→送溶酶体→回收","big":"assets/img/ch03/big/p090.jpg"},{"i":11,"sec":"第四节 溶酶体","title":"M6P分选信号 (p91)","notes":"Mannose 6-phosphate(6-磷酸甘露糖,M6P)残基把蛋白靶向到溶酶体：溶酶体酶在rER合成并N-糖基化后，在高尔基体CGN被磷酸化形成M6P标志，被M6P受体识别并分选到溶酶体。","page":91,"level":"掌握","img":"assets/img/ch03/p091.jpg","anim":"m6p_sorting","fig":null,"points":["溶酶体酶在rER合成并进行N-连接糖基化","在高尔基体CGN磷酸化形成M6P标志","M6P被M6P受体识别并分选到溶酶体"],"check":{"q":"溶酶体酶被靶向运往溶酶体所依赖的分选标志是？","o":["A. 多聚泛素链","B. 6-磷酸甘露糖(M6P)标志","C. KDEL序列","D. N端信号肽"],"a":"B","e":"溶酶体酶在高尔基体CGN形成M6P标志，经M6P受体分选。","oe":["错误：多聚泛素链是蛋白质的降解信号，不是溶酶体分选标志","正确：M6P是溶酶体酶被靶向运往溶酶体的分选标志","KDEL是内质网驻留蛋白的驻留信号","N端信号肽引导共翻译转运进入ER"]},"cards":[{"front":"M6P标志如何把溶酶体酶靶向到溶酶体？","back":"酶在rER合成并N-糖基化；在高尔基体CGN磷酸化形成M6P；被M6P受体识别并分选至溶酶体","mnemonic":"合成→糖基化→打M6P标签→受体签收","type":"流程","useImg":true,"blank":"M6P受体","blank2":"高尔基体"}],"mem":"合成→糖基化→打M6P标签→受体签收","big":"assets/img/ch03/big/p091.jpg"},{"i":12,"sec":"第四节 溶酶体","title":"M6P分选机制 (p92)","notes":"溶酶体蛋白除其特有的分选信号斑(signal patch)外，还有M6P标志。Phosphorylation of mannose residues——甘露糖残基磷酸化形成M6P。\n\n【本页英文讲解】\n本页讲溶酶体酶的分选机制与M6P标志。溶酶体蛋白除具有特有的分选信号斑（signal patch）外，还带有甘露糖-6-磷酸（M6P，mannose-6-phosphate）标志，由甘露糖残基磷酸化（phosphorylation）形成。M6P标志被高尔基体膜的M6P受体识别，从而分选运送至溶酶体。考点：M6P途径，见教材第八章。","page":92,"level":"掌握","img":"assets/img/ch03/p092.jpg","anim":null,"fig":"溶酶体酶在 ER 进行 N-糖基化后，在高尔基体顺面由 GlcNAc 磷酸转移酶识别其三维“信号斑”，把甘露糖磷酸化成 M6P。图强调识别的是构象信号斑，而非线性序列。","points":["溶酶体蛋白除信号斑外，还有M6P标志","M6P由甘露糖残基磷酸化形成"],"check":{"q":"溶酶体酶分选所依赖的标志是？","o":["A. 葡萄糖-6-磷酸","B. 甘露糖-6-磷酸(M6P)","C. 信号肽","D. 泛素标签"],"a":"B","e":"溶酶体蛋白除分选信号斑外还带M6P标志，由甘露糖残基磷酸化形成，被高尔基体M6P受体识别后分选运送。","oe":["葡萄糖-6-磷酸参与糖代谢，非分选标志，错误。","正确，溶酶体酶分选的标志是甘露糖-6-磷酸M6P。","信号肽引导蛋白进入ER，非溶酶体分选标志，错误。","泛素标签引导蛋白酶体降解，非溶酶体分选，错误。"]},"cards":[{"front":"溶酶体蛋白分选除信号斑外还有什么标志？","back":"M6P标志；由甘露糖残基磷酸化形成。","mnemonic":"溶酶体酶贴M6P邮票，寄往溶酶体。","type":"定义","useImg":false,"blank":"M6P标志","blank2":"甘露糖残基磷酸化"}],"mem":"溶酶体酶贴M6P邮票，寄往溶酶体。","big":"assets/img/ch03/big/p092.jpg","terms":[{"t":"M6P","en":"mannose-6-phosphate","d":"溶酶体酶的标志性糖基修饰（甘露糖-6-磷酸），被M6P受体识别后靶向运往溶酶体。"}]},{"i":13,"sec":"第四节 溶酶体","title":"M6P途径 (p93)","notes":"依赖于M6P途径的溶酶体产生：溶酶体酶在rER合成/N-连接糖基化修饰→Golgi(CTN)由N-乙酰葡萄糖胺磷酸转移酶催化加上M6P→M6P受体识别→包装入运输小泡→运往溶酶体。","page":93,"level":"掌握","img":"assets/img/ch03/p093.jpg","anim":null,"fig":"依赖 M6P 途径的溶酶体酶产生：ER 加 N-糖链 → 高尔基体加 M6P 标志 → M6P 受体在 TGN 结合 → 衣被小泡运到内体 → 酸性环境下受体释放酶 → 酶去磷酸化成成熟溶酶体酶，受体回收。","points":["溶酶体酶rER合成/N-糖基化→高尔基体加M6P(由N-乙酰葡萄糖胺磷酸转移酶催化)→M6P受体识别→包装入运输小泡→运往溶酶体"],"check":{"q":"M6P途径中，给溶酶体酶加上M6P标志的酶是？","o":["A. 质子泵","B. N-乙酰葡萄糖胺磷酸转移酶","C. 泛素连接酶","D. 二硫键异构酶PDI"],"a":"B","e":"溶酶体酶在rER合成并N-糖基化后，于高尔基体由N-乙酰葡萄糖胺磷酸转移酶催化加上M6P，再由M6P受体识别运送。","oe":["质子泵维持溶酶体酸性，不参与加M6P，错误。","正确，N-乙酰葡萄糖胺磷酸转移酶催化加M6P标志。","泛素连接酶参与泛素化降解，非M6P途径，错误。","PDI催化二硫键的形成与重排，与M6P标志无关，错误。"]},"cards":[{"front":"M6P途径产生溶酶体酶的主要步骤是什么？","back":"rER合成并N-连接糖基化；Golgi中N-乙酰葡萄糖胺磷酸转移酶催化加M6P；M6P受体识别；包装入运输小泡；运往溶酶体。","mnemonic":"合成→加签→识别→打包→送达。","type":"流程","useImg":true,"blank":"N-乙酰葡萄糖胺磷酸转移酶","blank2":"M6P受体"},{"front":"M6P标志在哪个细胞器、由什么酶催化形成？","back":"高尔基体；N-乙酰葡萄糖胺磷酸转移酶催化。","mnemonic":"高尔基贴签，磷酸转移酶执笔。","type":"定位","useImg":false,"blank":"高尔基体","blank2":"N-乙酰葡萄糖胺磷酸转移酶"}],"mem":"合成→加签→识别→打包→送达。","big":"assets/img/ch03/big/p093.jpg"},{"i":14,"sec":"第四节 溶酶体","title":"溶酶体酶分选多样化 (p94)","notes":"溶酶体酶分选途径多样化：依赖于M6P的分选途径效率不高，部分带M6P标志的溶酶体酶会通过运输小泡直接分泌到胞外，再由细胞重新摄取(旁路)。","page":94,"level":"理解","img":"assets/img/ch03/p094.jpg","anim":null,"fig":"部分溶酶体酶不依赖 M6P 分选，而是靠其他信号或与其他蛋白结合被运到溶酶体。图说明分选途径的多样性：M6P 是主要途径但非唯一。","points":null,"check":{"q":"溶酶体酶分选途径多样化的表现是？","o":["A. 部分带M6P的酶经运输小泡分泌到胞外，再被细胞重新摄取","B. 溶酶体酶全部在胞质中游离去溶酶体","C. 所有溶酶体酶都100%准确运入溶酶体","D. 溶酶体酶不经高尔基体直接入溶酶体"],"a":"A","e":"M6P分选途径效率不高，部分带M6P标志的溶酶体酶会经运输小泡直接分泌到胞外，再由细胞重新摄取（旁路）。","oe":["正确，部分酶分泌到胞外后被重新摄取，体现多样化。","溶酶体酶并非在胞质游离，而经膜泡运输，错误。","M6P分选效率不高，并非100%准确入溶酶体，错误。","溶酶体酶需经高尔基体加工加M6P，错误。"]},"cards":null,"mem":"M6P分选效率不高，部分酶旁路分泌再摄取","big":"assets/img/ch03/big/p094.jpg"},{"i":15,"sec":"第四节 溶酶体","title":"M6P分选途径图 (p95)","notes":"溶酶体酶的M6P分选途径示意图：展示从rER合成、Golgi修饰加M6P、M6P受体分选、运输小泡、到溶酶体的完整路径。","page":95,"level":"理解","img":"assets/img/ch03/p095.jpg","anim":null,"fig":"综合图：溶酶体酶在 ER 合成并糖基化，在高尔基体获得 M6P，由 M6P 受体在 TGN 分选，经内体转运到溶酶体，受体可循环使用。图是 M6P 分选途径的完整流程图。","points":null,"check":{"q":"溶酶体酶M6P分选途径的正确顺序是？","o":["A. 胞质合成→直接进入溶酶体","B. Golgi合成→rER加M6P→溶酶体→M6P受体识别","C. 溶酶体合成→Golgi加工→分泌到胞外","D. rER合成/N-糖基化→Golgi加M6P→M6P受体识别→运输小泡→溶酶体"],"a":"D","e":"M6P途径为：rER合成并N-糖基化→Golgi加M6P→M6P受体识别→包装入运输小泡→运往溶酶体。","oe":["溶酶体酶需经ER、Golgi加工分选，非直接进入，错误。","蛋白合成起始于rER而非Golgi，顺序颠倒，错误。","溶酶体酶并非在溶酶体内合成，也不会直接分泌胞外，错误。","正确，符合rER→Golgi加M6P→受体→运输小泡→溶酶体顺序。"]},"cards":null,"mem":"M6P途径：rER→Golgi加M6P→受体分选→溶酶体","big":"assets/img/ch03/big/p095.jpg"},{"i":16,"sec":"第五节 液泡","title":"植物液泡 (p96)","notes":"Plant cell vacuoles植物液泡：Plant vacuoles have some of the same acid hydrolases——植物液泡含一些与溶酶体相同的酸性水解酶，功能类似溶酶体；还参与储存、膨压维持、色素积累。","page":96,"level":"掌握","img":"assets/img/ch03/p096.jpg","anim":null,"fig":null,"points":["植物液泡含与溶酶体相同的酸性水解酶，功能类似溶酶体","还参与储存、膨压维持、色素积累"],"check":{"q":"关于植物液泡的叙述，正确的是？","o":["A. 是光合作用的场所","B. 不含任何水解酶，只储存水分","C. 含与溶酶体相同的酸性水解酶，还参与储存、膨压维持和色素积累","D. 是合成蛋白质的主要场所"],"a":"C","e":"植物液泡含一些与溶酶体相同的酸性水解酶，功能类似溶酶体，还参与储存、膨压维持和色素积累。","oe":["光合作用场所是叶绿体，不是液泡，错误。","液泡含有酸性水解酶，并非只储存水分，错误。","正确，植物液泡含酸性水解酶并有储存、膨压等功能。","蛋白质合成主要在核糖体，非液泡，错误。"]},"cards":[{"front":"植物液泡与溶酶体有何相似之处？","back":"含相同的酸性水解酶；功能类似溶酶体。","mnemonic":"植物液泡是植物版溶酶体。","type":"对比","useImg":false,"blank":"酸性水解酶","blank2":"溶酶体"},{"front":"植物液泡除类似溶酶体功能外还参与哪些功能？","back":"储存；维持膨压；色素积累。","mnemonic":"存、压、色三件事。","type":"功能","useImg":false,"blank":"维持膨压","blank2":"色素积累"}],"mem":"植物液泡是植物版溶酶体。","big":"assets/img/ch03/big/p096.jpg"}],"mcq":[],"judge":[{"id":"ch03_judge_9","modI":2,"q":"溶酶体内部呈碱性(pH≈8)，其水解酶在碱性条件下活性最高。","a":"错","e":"溶酶体内部呈酸性(pH≈5)，由H+泵维持，酸性水解酶在此条件下活性最高。","kp":"ch03_s2_5","oe":["若以为溶酶体内部呈碱性则判对，误记了其pH与酶最适条件。","溶酶体内部呈酸性(pH≈5)，由H+泵维持，酸性水解酶在最适酸性下活性最高。"]},{"id":"ch03_judge_10","modI":2,"q":"溶酶体酶的分选信号是6-磷酸甘露糖(M6P)。","a":"对","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别并分选到溶酶体。","kp":"ch03_s2_11","oe":["溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别分选至溶酶体。","误记为信号肽或KDEL等分选信号，混淆不同细胞器的定位机制，故判错。"]}],"fill":[{"id":"ch03_fill_9","modI":2,"q":"高尔基体顺面网状结构(CGN)接收________合成的物质,反面膜囊(TGN)将物质分选运往________、质膜或胞外。","a":"内质网,溶酶体","kp":"ch03_s2_0","oe":["CGN接收内质网经COPII小泡送来的物质，故第一空填内质网。","TGN将溶酶体酶等分选运往溶酶体，此外还运往质膜或胞外。"]},{"id":"ch03_fill_10","modI":2,"q":"溶酶体含多种________水解酶(最适pH约为________),膜上的________维持其酸性环境。","a":"酸性,5,H+泵(质子泵)","kp":"ch03_s2_1","oe":["溶酶体含多种酸性水解酶，最适pH约为5，故第一空填酸性。","溶酶体腔内pH约为5，是酸性水解酶的最适pH，故填5。","溶酶体膜上的V型H+泵泵入H+，维持腔内酸性环境。"]},{"id":"ch03_fill_11","modI":2,"q":"溶酶体的消化类型包括________(吞噬外源物质)和________(降解自身老化细胞器)。","a":"phagocytosis(吞噬),autophagy(自噬)","kp":"ch03_s2_4","oe":["溶酶体消化吞噬小泡进入的外源物质，属异体吞噬phagocytosis。","自噬体包裹自身衰老细胞器，与溶酶体融合后被降解。"]}],"short":[{"id":"ch03_short_6","modI":2,"q":"简述高尔基体的结构和功能。","a":"高尔基体(Golgi complex)结构：\n由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性：\n①顺面网状结构(CGN)——接收内质网合成的新物质；\n②中间膜囊——加工修饰；\n③反面网状结构(TGN)——输出端，分选运往溶酶体、质膜或胞外。\n\n高尔基体功能：\n①蛋白质的糖基化——O-连接糖基化在此进行；N-连接糖基化在此完成加工；\n②糖胺聚糖/蛋白聚糖的合成；\n③蛋白质加工、修饰；\n④分类装载运输的分选站(枢纽作用)——通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖信号序列与受体的相互作用；\n⑤植物细胞高尔基体参与细胞壁合成。\n\n【意义】高尔基体是内膜系统的'分拣中心'。","kp":"ch03_s2_0"}],"calc":[{"id":"ch03_calc_3","modI":2,"q":"论述溶酶体的形成、功能及其与疾病的关系。","a":"溶酶体是细胞的消化系统,其酶经M6P途径分选形成,功能异常导致溶酶体贮积症","steps":"【形成(M6P途径)】\n①溶酶体酶在rER合成并进行N-连接糖基化；\n②在高尔基体CGN，由N-乙酰葡萄糖胺磷酸转移酶催化加上6-磷酸甘露糖(M6P)标志；\n③M6P受体识别并结合溶酶体酶；\n④包装入网格蛋白有被小泡→运往胞内体→溶酶体。\n(部分经M6P非依赖途径)\n\n【功能】\n①消化：'清道夫'，清除无用生物大分子、衰老细胞器、凋亡细胞及吞噬的营养大分子；\n②吞噬(phagocytosis)：消化细菌等外源物质；\n③自噬(autophagy)：降解自身老化废弃的细胞器和蛋白；\n④参与蛋白质存量调节(除泛素途径外的另一途径)；\n⑤维持内部酸性环境(H+泵，pH≈5)。\n\n【疾病】\n溶酶体酶缺陷→底物不能被降解→溶酶体贮积症(如泰-萨克斯病、戈谢病、I细胞病等)，表现为神经退行、肝脾肿大等。","kp":"ch03_s2_2"}],"term":[{"id":"ch03_term_11","modI":2,"term":"高尔基体(Golgi Complex)","def":"①由扁平膜囊和囊泡组成的细胞器，具极性(cis/medial/trans)（定义）。②功能：蛋白质O-连接糖基化、N-连接糖基化加工；蛋白质分选装载运输的枢纽；糖胺聚糖合成（功能）。③CGN接收ER物质，TGN输出到溶酶体/质膜/胞外（极性）。","kps":"踩分点:①定义(1分)②功能(2分)③极性区室(1分)","kp":"ch03_s2_0"},{"id":"ch03_term_12","modI":2,"term":"溶酶体(Lysosome)","def":"①单层膜包围、含多种酸性水解酶的细胞器，是细胞的消化系统（定义）。②特点：内部酸性(pH≈5，H+泵维持)；膜高度糖基化保护；异质性（特点）。③功能：吞噬消化外源物质、自噬降解自身老化细胞器、参与蛋白存量调节（功能）。④酶经M6P途径分选（分选）。","kps":"踩分点:①定义(1分)②特点(1分)③功能(2分)④M6P(1分)","kp":"ch03_s2_1"},{"id":"ch03_term_13","modI":2,"term":"M6P分选途径","def":"①通过6-磷酸甘露糖(M6P)标志将溶酶体酶靶向到溶酶体的途径（定义）。②过程：溶酶体酶在rER合成/N-糖基化→高尔基体CGN由N-乙酰葡萄糖胺磷酸转移酶加上M6P→M6P受体识别→包装入运输小泡→溶酶体（过程）。③意义：保证溶酶体酶正确分选（意义）。","kps":"踩分点:①定义(1分)②过程(2分)③意义(1分)","kp":"ch03_s2_15"},{"id":"ch03_term_14","modI":2,"term":"细胞自噬(Autophagy)","def":"①细胞在自噬相关基因调控下，降解自身受损或需淘汰更新的物质(细胞器、大分子)并再利用的过程（定义）。②过程：形成自噬体→与溶酶体融合→降解（过程）。③意义：清除受损细胞器、维持稳态、应对饥饿（意义）。","kps":"踩分点:①定义(1分)②过程(1分)③意义(2分)","kp":"ch03_s2_10"}]}],"mcq":[{"id":"ch03_mcq_1","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内膜系统不包括下列哪个？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 线粒体"],"a":"D","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成(ER/高尔基/溶酶体/内体/液泡/分泌小泡)；线粒体虽具膜但不属内膜系统。","kp":"ch03_s0_2","oe":["内质网是内膜系统的核心成员，属于内膜系统。","高尔基体由单层膜构成且起源上与ER相关，属于内膜系统。","溶酶体由单层膜包被且起源于高尔基体，属于内膜系统。","线粒体虽具膜，但不属于内膜系统，故为答案。"]},{"id":"ch03_mcq_2","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"粗面内质网(rER)的主要功能是？","o":["A. 合成脂类","B. 合成分泌蛋白和膜蛋白(膜上有核糖体)","C. 解毒","D. 储钙"],"a":"B","e":"rER膜表面有大量核糖体，合成分泌性蛋白和多种膜蛋白；sER无核糖体，合成脂类、解毒、储钙。","kp":"ch03_s0_18","oe":["合成脂类主要是光面内质网的功能，不是rER。","rER膜上附有核糖体，合成分泌蛋白和膜蛋白。","解毒是sER的功能，不是rER的主要功能。","储钙是sER的功能，不属于rER。"]},{"id":"ch03_mcq_3","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"光面内质网(sER)的功能不包括？","o":["A. 解毒","B. 储钙","C. 合成膜脂","D. 合成分泌蛋白"],"a":"D","e":"sER功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。合成分泌蛋白是rER功能。","kp":"ch03_s0_13","oe":["解毒是sER的功能，如在肝细胞中。","储钙是sER的功能，ER是细胞内重要钙库。","合成膜脂(甘油磷脂、胆固醇)是sER的功能。","合成分泌蛋白是rER的功能，不属于sER，故为答案。"]},{"id":"ch03_mcq_4","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"易位子(translocon)位于？","o":["A. 高尔基体膜","B. 粗面内质网膜","C. 溶酶体膜","D. 线粒体外膜"],"a":"B","e":"易位子是rER膜上的蛋白复合体(核心为Sec61复合体)，中心有2nm孔道，新生肽链由此进入ER腔。","kp":"ch03_s0_19","oe":["易位子位于内质网膜，不在高尔基体膜上。","易位子位于粗面内质网膜，核心为Sec61复合体。","易位子不在溶酶体膜，溶酶体蛋白由运输小泡送入。","线粒体外膜蛋白靠TOM等复合体转运，不是易位子。"]},{"id":"ch03_mcq_5","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号识别颗粒(SRP)的组成是？","o":["A. 6种多肽+1个7S RNA","B. 仅蛋白质","C. 仅RNA","D. 糖蛋白"],"a":"A","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，既结合信号肽又结合核糖体大亚基，暂停翻译。","kp":"ch03_s0_32","oe":["SRP由6种多肽和1个7S RNA组成。","SRP含有RNA，并非仅由蛋白质组成。","SRP含有蛋白质，并非仅由RNA组成。","SRP是核糖核蛋白，不是糖蛋白。"]},{"id":"ch03_mcq_6","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"信号肽假说中,肽链转移进入ER腔的机制是？","o":["A. 翻译后转移","B. 边翻译边转移(共翻译转移)","C. 胞吞","D. 自由扩散"],"a":"B","e":"分泌蛋白在游离核糖体起始合成→信号肽被SRP识别→附着ER→共翻译转移入ER腔，信号肽被切除。","kp":"ch03_s0_35","oe":["分泌蛋白入ER是边翻译边转移，不是翻译后转移。","肽链进入ER腔为共翻译转移，即边翻译边转移。","胞吞是摄取外源物质的方式，与肽链入ER无关。","自由扩散是小分子运输方式，不适用于肽链入ER。"]},{"id":"ch03_mcq_7","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"可溶性蛋白进入ER腔的条件是？","o":["A. 只有N端信号序列,无停止转移序列","B. 含停止转移序列","C. 无信号序列","D. 含多个起始序列"],"a":"A","e":"只含N端信号序列(开始转移序列)、无停止序列→蛋白完全进入ER腔成可溶性蛋白；有停止序列则锚在膜上成跨膜蛋白。","kp":"ch03_s0_39","oe":["只有N端信号序列而无停止转移序列，蛋白完全进入ER腔。","含停止转移序列的蛋白会锚定在膜上，成为跨膜蛋白。","无信号序列的蛋白不能进入ER腔。","含多个起始序列的说法与可溶性蛋白入腔机理不符。"]},{"id":"ch03_mcq_8","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"N-连接糖基化与O-连接糖基化的区别,错误的是？","o":["A. N-连接起始于rER,O-连接在高尔基体","B. N-连接结合Asn,O-连接结合Ser/Thr","C. N-连接来自同一寡糖前体","D. O-连接起始于内质网"],"a":"D","e":"O-连接糖基化在高尔基体进行，单糖逐个加到Ser/Thr羟基上；N-连接起始于rER，结合Asn，来自同一寡糖前体。","kp":"ch03_s1_2","oe":["N-连接起始于rER，O-连接在高尔基体，该说法正确。","N-连接结合Asn，O-连接结合Ser/Thr，该说法正确。","N-连接糖链来自同一寡糖前体，该说法正确。","O-连接糖基化在高尔基体起始，而非起始于内质网，故错误。"]},{"id":"ch03_mcq_9","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"催化ER腔内二硫键形成的酶是？","o":["A. PDI","B. Bip","C. SRP","D. Hsp70"],"a":"A","e":"PDI(蛋白二硫键异构酶)是ER驻留蛋白，催化二硫键形成与重排。Bip是分子伴侣识别错误折叠蛋白。","kp":"ch03_s1_6","oe":["PDI是ER驻留蛋白，催化二硫键的形成与重排。","Bip是分子伴侣，识别错误折叠蛋白，不催化二硫键。","SRP负责识别信号肽并暂停翻译，不催化二硫键。","Hsp70是分子伴侣，无二硫键异构酶活性。"]},{"id":"ch03_mcq_10","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"Bip蛋白的功能是？","o":["A. 催化二硫键","B. 识别未正确折叠/未组装的蛋白,帮助折叠","C. 合成脂类","D. 切除信号肽"],"a":"B","e":"Bip(binding protein)是ER驻留分子伴侣，识别不正确折叠或未组装的蛋白，防止聚集并帮助折叠。","kp":"ch03_s1_7","oe":["催化二硫键形成的是PDI，不是Bip。","Bip是ER驻留分子伴侣，识别未正确折叠或未组装的蛋白并帮助折叠。","合成脂类由sER完成，不是Bip的功能。","切除信号肽由信号肽酶完成，不是Bip。"]},{"id":"ch03_mcq_11","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"内质网驻留蛋白的驻留信号是？","o":["A. KDEL序列","B. M6P","C. NLS","D. NES"],"a":"A","e":"Bip、PDI等ER驻留蛋白含C端KDEL(内质网驻留信号)，被保留在ER中。M6P是溶酶体分选信号。","kp":"ch03_s1_13","oe":["ER驻留蛋白C端的KDEL序列是其内质网驻留信号。","M6P是溶酶体酶的分选信号，不是ER驻留信号。","NLS是核定位信号，引导蛋白进入细胞核。","NES是核输出信号，与ER驻留无关。"]},{"id":"ch03_mcq_12","mod":"模块一：真核细胞分室化与内质网","modI":0,"q":"2004年诺贝尔化学奖授予的发现是？","o":["A. 泛素介导的蛋白质降解","B. 水通道","C. RNAi","D. 端粒酶"],"a":"A","e":"2004年诺贝尔化学奖授予Ciechanover、Hershko、Rose，发现泛素介导的蛋白质降解。","kp":"ch03_s1_16","oe":["2004年诺贝尔化学奖表彰发现泛素介导的蛋白质降解。","水通道研究获2003年诺贝尔化学奖，年份不符。","RNAi研究获2006年诺贝尔生理学或医学奖，非化学奖。","端粒酶研究获2009年诺贝尔生理学或医学奖，非化学奖。"]},{"id":"ch03_mcq_13","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素由多少个氨基酸组成？","o":["A. 76个","B. 100个","C. 50个","D. 200个"],"a":"A","e":"泛素由76个氨基酸组成，8.5×10³小分子球蛋白，高度保守，普遍存在于真核细胞。","kp":"ch03_s1_17","oe":["泛素由76个氨基酸组成，是高度保守的小分子球蛋白。","泛素并非由100个氨基酸组成，数目不对。","泛素并非由50个氨基酸组成，数目不对。","泛素并非由200个氨基酸组成，数目不对。"]},{"id":"ch03_mcq_14","mod":"模块二：蛋白质分选与降解","modI":1,"q":"泛素化需要哪三种酶？","o":["A. E1、E2、E3","B. 激酶、磷酸酶、连接酶","C. PDI、Bip、SRP","D. 蛋白酶、核酸酶、脂肪酶"],"a":"A","e":"泛素活化酶(E1)、泛素结合酶(E2)、泛素连接酶(E3)。多聚泛素链是降解信号。","kp":"ch03_s1_18","oe":["泛素化需泛素活化酶E1、泛素结合酶E2和泛素连接酶E3。","激酶、磷酸酶、连接酶不是泛素化的三种酶。","PDI、Bip、SRP与泛素化过程无关。","蛋白酶、核酸酶、脂肪酶是水解酶，不参与泛素化。"]},{"id":"ch03_mcq_15","mod":"模块二：蛋白质分选与降解","modI":1,"q":"26S蛋白酶体的结构是？","o":["A. 一个20S催化核心+两个19S调节帽","B. 仅20S","C. 仅19S","D. 单链蛋白"],"a":"A","e":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，由约50种亚基构成，降解泛素化蛋白。","kp":"ch03_s1_19","oe":["26S蛋白酶体由20S催化核心和两个19S调节帽组成。","26S蛋白酶体不只含20S，还含19S调节帽。","26S蛋白酶体并非仅由19S组成。","26S蛋白酶体是多亚基复合体，不是单链蛋白。"]},{"id":"ch03_mcq_16","mod":"模块二：蛋白质分选与降解","modI":1,"q":"高尔基体的极性区室中,接收内质网物质的是？","o":["A. 顺面(CGN)","B. 反面(TGN)","C. 中间膜囊","D. 溶酶体"],"a":"A","e":"顺面网状结构(CGN)接收内质网新物质；反面膜囊(TGN)是输出端，分选运往溶酶体/质膜/胞外。","kp":"ch03_s1_25","oe":["顺面网状结构(CGN)接收内质网运来的新物质。","反面(TGN)是输出端，分选运往溶酶体、质膜或胞外。","中间膜囊负责加工修饰，不接收ER来向物质。","溶酶体不是高尔基体的极性区室。"]},{"id":"ch03_mcq_17","mod":"模块二：蛋白质分选与降解","modI":1,"q":"O-连接糖基化发生在？","o":["A. 内质网","B. 高尔基体","C. 溶酶体","D. 细胞核"],"a":"B","e":"O-连接糖基化在高尔基体进行(单糖逐个加到Ser/Thr)；N-连接起始于ER、完成于高尔基体。","kp":"ch03_s1_2","oe":["内质网主要进行N-连接糖基化，不是O-连接。","O-连接糖基化在高尔基体进行，单糖加到Ser/Thr上。","溶酶体负责分解，不进行O-连接糖基化。","细胞核不是糖基化场所，糖基化在内质网和高尔基体。"]},{"id":"ch03_mcq_18","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体内部维持酸性环境(pH≈5)依靠？","o":["A. H+泵(质子泵)","B. Na+/K+泵","C. Ca2+泵","D. 水通道"],"a":"A","e":"溶酶体膜上的H+-pumps将H+泵入，维持内部pH≈5，使酸性水解酶活性最高。","kp":"ch03_s2_6","oe":["溶酶体膜上的H+泵将H+泵入，维持腔内pH约5。","Na+/K+泵维持细胞内外钠钾梯度，不使溶酶体酸化。","Ca2+泵与溶酶体酸性环境的维持无关。","水通道只转运水，不参与溶酶体酸化。"]},{"id":"ch03_mcq_19","mod":"模块二：蛋白质分选与降解","modI":1,"q":"溶酶体酶的靶向分选信号是？","o":["A. 6-磷酸甘露糖(M6P)","B. KDEL","C. NLS","D. 信号肽"],"a":"A","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别分选到溶酶体。","kp":"ch03_s2_11","oe":["溶酶体酶的靶向分选信号是6-磷酸甘露糖(M6P)。","KDEL是ER驻留信号，使蛋白滞留在内质网。","NLS是核定位信号，引导蛋白进入细胞核。","信号肽引导蛋白进入内质网，不是溶酶体靶向信号。"]},{"id":"ch03_mcq_20","mod":"模块二：蛋白质分选与降解","modI":1,"q":"细胞自噬(autophagy)是指？","o":["A. 吞噬外源细菌","B. 降解细胞自身老化废弃的细胞器和大分子","C. 分泌蛋白","D. 细胞分裂"],"a":"B","e":"自噬是细胞在自噬相关基因调控下，对自身受损或需淘汰更新的物质(线粒体、过氧化物酶体等)进行降解再利用。","kp":"ch03_s2_10","oe":["吞噬外源细菌是吞噬作用，不属于自噬。","自噬是降解细胞自身老化废弃的细胞器和大分子。","分泌蛋白属于分泌途径，与自噬不同。","细胞分裂属于增殖过程，与自噬的降解功能无关。"]},{"id":"ch03_mcq_21","mod":"模块二：蛋白质分选与降解","modI":1,"q":"N-连接糖基化连接的氨基酸残基是？","o":["A. 天冬酰胺(Asn)","B. 丝氨酸(Ser)","C. 苏氨酸(Thr)","D. 赖氨酸(Lys)"],"a":"A","e":"N-连接糖基化连接Asn(序列Asn-X-Ser/Thr)；O-连接连接Ser/Thr羟基。","kp":"ch03_s1_2","oe":["N-连接糖基化连接的氨基酸残基是天冬酰胺(Asn)。","丝氨酸是O-连接糖基化的连接位点。","苏氨酸也是O-连接糖基化的连接位点。","赖氨酸不参与N-连接糖基化，N-连接位点是天冬酰胺。"]},{"id":"ch03_mcq_22","mod":"模块二：蛋白质分选与降解","modI":1,"q":"膜脂(甘油磷脂和胆固醇)主要在何处合成？","o":["A. 光面内质网","B. 高尔基体","C. 线粒体","D. 细胞核"],"a":"A","e":"sER合成构成细胞所需的绝大多数膜脂(甘油磷脂和胆固醇)，再运往其他膜。","kp":"ch03_s0_16","oe":["光面内质网合成甘油磷脂和胆固醇等膜脂。","高尔基体主要加工分选，不主要负责合成膜脂。","线粒体主要供能，膜脂合成主要在内质网。","细胞核不合成膜脂，膜脂合成主要在内质网。"]},{"id":"ch03_mcq_23","mod":"模块二：蛋白质分选与降解","modI":1,"q":"微粒体(microsome)是？","o":["A. 完整线粒体","B. 破碎内质网自我融合形成的囊泡","C. 溶酶体","D. 高尔基体"],"a":"B","e":"微粒体是体外实验中细胞匀浆和差速离心得到的、由分离的内质网自我融合形成的球形囊泡，是研究ER的模型。","kp":"ch03_s0_11","oe":["微粒体是由内质网形成的囊泡，不是完整线粒体。","微粒体是破碎内质网自我融合形成的囊泡。","微粒体来源于内质网，不是溶酶体。","微粒体来源于破碎的内质网，不是高尔基体。"]},{"id":"ch03_mcq_24","mod":"模块二：蛋白质分选与降解","modI":1,"q":"sER的储钙功能依靠？","o":["A. Ca2+-ATPase将钙泵入ER","B. 钙通道外流","C. Na+/K+泵","D. 质子泵"],"a":"A","e":"ER膜上的Ca2+-ATPase将细胞基质中的钙泵入ER储存，使ER腔钙浓度高达3mM，参与信号传递。","kp":"ch03_s0_15","oe":["ER膜上的Ca2+-ATPase将钙泵入ER储存。","钙通道外流会释放钙，与储钙作用相反。","Na+/K+泵与ER的储钙功能无关。","质子泵维持溶酶体酸性，不负责ER储钙。"]},{"id":"ch03_mcq_25","mod":"模块二：蛋白质分选与降解","modI":1,"q":"ER质量监控的意义是？","o":["A. 所有蛋白都能离开ER","B. 只有正确折叠和装配的蛋白才能离开ER","C. 错误折叠蛋白直接分泌","D. 阻止所有蛋白合成"],"a":"B","e":"ER质量监控：只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被逆向转运至胞质经泛素-蛋白酶体降解(ERAD)。","kp":"ch03_s1_14","oe":["并非所有蛋白都能离开ER，只有正确折叠装配者可以。","ER质量监控确保只有正确折叠和装配的蛋白才能离开ER。","错误折叠蛋白被滞留降解，不会直接分泌。","质量监控是筛选而非阻止所有蛋白质的合成。"]}],"judge":[{"id":"ch03_judge_1","modI":0,"q":"内膜系统包括内质网、高尔基体、溶酶体，但不包括线粒体和叶绿体。","a":"对","e":"内膜系统由单层膜围绕、结构功能发生上相关的细胞器组成；线粒体、叶绿体不属内膜系统。","kp":"ch03_s0_2","oe":["内膜系统由单层膜包被、结构与功能相关的细胞器组成，不含线粒体、叶绿体。","误把线粒体、叶绿体也列入内膜系统，因其为双层膜细胞器，故判错。"]},{"id":"ch03_judge_2","modI":0,"q":"粗面内质网表面附着大量核糖体，主要合成分泌蛋白和膜蛋白。","a":"对","e":"rER膜上有核糖体与易位子，合成分泌蛋白和膜蛋白；sER无核糖体。","kp":"ch03_s0_9","oe":["粗面内质网膜上附着核糖体与易位子，合成分泌蛋白和膜蛋白。","误以为核糖体附着于高尔基体或sER，混淆粗面与光面内质网，故判错。"]},{"id":"ch03_judge_3","modI":0,"q":"光面内质网的功能包括解毒、储钙和合成膜脂。","a":"对","e":"sER三大功能：解毒(肝细胞)、储钙(Ca库)、合成膜脂(甘油磷脂/胆固醇)。","kp":"ch03_s0_13","oe":["光面内质网具解毒、储钙(Ca库)和合成膜脂三大功能。","误将解毒储钙归为粗面内质网功能，或否认其合成膜脂，故判错。"]},{"id":"ch03_judge_4","modI":0,"q":"易位子(translocon)位于高尔基体膜上，介导蛋白质进入高尔基体腔。","a":"错","e":"易位子位于粗面内质网(rER)膜上，核心为Sec61复合体，介导新生肽链进入ER腔。","kp":"ch03_s0_19","oe":["若以为易位子在高尔基体膜上则判对，混淆了蛋白质转运位点。","易位子位于粗面内质网膜上，核心为Sec61复合体，介导肽链进入ER腔。"]},{"id":"ch03_judge_5","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个7S RNA组成。","a":"对","e":"SRP由6种多肽和1个300核苷酸(7S)RNA组成，识别信号肽并使翻译暂停。","kp":"ch03_s0_32","oe":["SRP由6种多肽和1个300核苷酸(7S)RNA组成，识别信号肽并暂停翻译。","误记SRP组分数或RNA类型，如说由6种RNA组成，故判错。"]},{"id":"ch03_judge_6","modI":1,"q":"N-连接糖基化起始于内质网，O-连接糖基化发生在高尔基体。","a":"对","e":"N-连接起始于rER、结合Asn；O-连接在高尔基体进行、结合Ser/Thr。","kp":"ch03_s1_2","oe":["N-连接糖基化起始于rER并结合Asn，O-连接发生在高尔基体并结合Ser/Thr。","误以为两者都在同一部位发生，或把N、O连接地点与氨基酸记反，故判错。"]},{"id":"ch03_judge_7","modI":1,"q":"泛素由76个氨基酸组成，泛素化需要E1、E2、E3三种酶。","a":"对","e":"泛素由76个氨基酸组成；E1活化酶、E2结合酶、E3连接酶共同完成泛素化。","kp":"ch03_s1_18","oe":["泛素由76个氨基酸组成，泛素化需E1活化、E2结合、E3连接三种酶。","误记泛素氨基酸数或所需酶的种类与数量，如说只需E1、E2，故判错。"]},{"id":"ch03_judge_8","modI":1,"q":"26S蛋白酶体由20S催化核心和两个19S调节帽组成，降解泛素化蛋白。","a":"对","e":"26S蛋白酶体=20S催化核心+两个19S调节帽，识别多聚泛素链并降解蛋白。","kp":"ch03_s1_20","oe":["26S蛋白酶体由20S催化核心和两个19S调节帽组成，降解泛素化蛋白。","误把核心与调节帽的沉降系数或数量记错，如20S帽、19S核心，故判错。"]},{"id":"ch03_judge_9","modI":2,"q":"溶酶体内部呈碱性(pH≈8)，其水解酶在碱性条件下活性最高。","a":"错","e":"溶酶体内部呈酸性(pH≈5)，由H+泵维持，酸性水解酶在此条件下活性最高。","kp":"ch03_s2_5","oe":["若以为溶酶体内部呈碱性则判对，误记了其pH与酶最适条件。","溶酶体内部呈酸性(pH≈5)，由H+泵维持，酸性水解酶在最适酸性下活性最高。"]},{"id":"ch03_judge_10","modI":2,"q":"溶酶体酶的分选信号是6-磷酸甘露糖(M6P)。","a":"对","e":"溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别并分选到溶酶体。","kp":"ch03_s2_11","oe":["溶酶体酶在高尔基体被加上M6P标志，由M6P受体识别分选至溶酶体。","误记为信号肽或KDEL等分选信号，混淆不同细胞器的定位机制，故判错。"]}],"fill":[{"id":"ch03_fill_1","modI":0,"q":"内膜系统是在结构、功能乃至发生上相关的、由________膜围绕成的细胞器,包括内质网、________、溶酶体等。","a":"单层,高尔基体","kp":"ch03_s0_2","oe":["内膜系统各细胞器均由单层膜包被，区别于双层膜的线粒体和核膜。","高尔基体属内膜系统，参与蛋白质加工、分选和运输，故为答案。"]},{"id":"ch03_fill_2","modI":0,"q":"粗面内质网表面分布大量________,主要合成分泌蛋白；光面内质网的功能有解毒、储钙和________。","a":"核糖体,合成膜脂","kp":"ch03_s0_9","oe":["粗面内质网表面附着大量核糖体，是合成分泌蛋白和膜蛋白的场所。","光面内质网能合成磷脂、胆固醇等膜脂，故第三空填合成膜脂。"]},{"id":"ch03_fill_3","modI":0,"q":"rER膜上的蛋白复合体________(核心为Sec61)中心有直径2nm孔道,使新生肽链进入ER腔。","a":"易位子(translocon)","kp":"ch03_s0_21","oe":["易位子位于rER膜上，由Sec61构成孔道，供新生肽链进入ER腔。"]},{"id":"ch03_fill_4","modI":1,"q":"信号识别颗粒(SRP)由6种多肽和1个________组成,识别新生肽的________并使翻译暂停。","a":"7S RNA,信号肽","kp":"ch03_s0_32","oe":["SRP含1分子7S RNA和6种多肽，7S RNA是其特征性核酸成分。","SRP识别新生肽N端的信号肽并结合，使翻译暂停。"]},{"id":"ch03_fill_5","modI":1,"q":"N-连接糖基化连接________残基,起始于________；O-连接糖基化连接________残基,发生在________。","a":"天冬酰胺(Asn),内质网,丝氨酸/苏氨酸(Ser/Thr),高尔基体","kp":"ch03_s1_2","oe":["N-连接糖基化发生于天冬酰胺残基的酰胺氮上，故填Asn。","N-连接糖基化在内质网腔内起始，先接核心寡糖再加工。","O-连接糖基化连接丝氨酸或苏氨酸残基的羟基氧，故填Ser/Thr。","O-连接糖基化主要在高尔基体中进行，故填高尔基体。"]},{"id":"ch03_fill_6","modI":1,"q":"ER驻留蛋白的驻留信号是________；溶酶体酶的分选信号是________。","a":"KDEL序列,6-磷酸甘露糖(M6P)","kp":"ch03_s1_13","oe":["ER驻留蛋白C端的KDEL序列被受体识别，经COPI小泡回收回ER。","溶酶体酶在高尔基体被标记6-磷酸甘露糖，经M6P受体分选入溶酶体。"]},{"id":"ch03_fill_7","modI":1,"q":"泛素由________个氨基酸组成；泛素化需要________、________、________三种酶。","a":"76,E1(活化酶),E2(结合酶),E3(连接酶)","kp":"ch03_s1_18","oe":["泛素是由76个氨基酸组成的小分子调控蛋白，故填76。","E1以ATP供能活化泛素，形成E1-泛素硫酯键。","E2承接并携带活化泛素，与E3协同完成泛素连接。","E3识别底物并催化泛素连接到靶蛋白的赖氨酸残基上。"]},{"id":"ch03_fill_8","modI":1,"q":"26S蛋白酶体由20S________和两个19S________组成,降解泛素化的蛋白质。","a":"催化核心,调节帽","kp":"ch03_s1_19","oe":["20S为圆柱形复合体，含蛋白酶活性位点，是降解肽链的催化核心。","两个19S调节帽位于20S两端，负责识别、解折叠并送入底物。"]},{"id":"ch03_fill_9","modI":2,"q":"高尔基体顺面网状结构(CGN)接收________合成的物质,反面膜囊(TGN)将物质分选运往________、质膜或胞外。","a":"内质网,溶酶体","kp":"ch03_s2_0","oe":["CGN接收内质网经COPII小泡送来的物质，故第一空填内质网。","TGN将溶酶体酶等分选运往溶酶体，此外还运往质膜或胞外。"]},{"id":"ch03_fill_10","modI":2,"q":"溶酶体含多种________水解酶(最适pH约为________),膜上的________维持其酸性环境。","a":"酸性,5,H+泵(质子泵)","kp":"ch03_s2_1","oe":["溶酶体含多种酸性水解酶，最适pH约为5，故第一空填酸性。","溶酶体腔内pH约为5，是酸性水解酶的最适pH，故填5。","溶酶体膜上的V型H+泵泵入H+，维持腔内酸性环境。"]},{"id":"ch03_fill_11","modI":2,"q":"溶酶体的消化类型包括________(吞噬外源物质)和________(降解自身老化细胞器)。","a":"phagocytosis(吞噬),autophagy(自噬)","kp":"ch03_s2_4","oe":["溶酶体消化吞噬小泡进入的外源物质，属异体吞噬phagocytosis。","自噬体包裹自身衰老细胞器，与溶酶体融合后被降解。"]},{"id":"ch03_fill_12","modI":0,"q":"内质网驻留蛋白Bip和PDI属于________,其中PDI催化________的形成。","a":"分子伴侣(ER驻留蛋白),二硫键","kp":"ch03_s1_7","oe":["Bip和PDI是内质网驻留的分子伴侣，协助蛋白折叠并防止聚集。","PDI催化肽链半胱氨酸间二硫键的形成与重排，故填二硫键。"]}],"short":[{"id":"ch03_short_1","modI":1,"q":"简述信号肽假说及分泌蛋白共翻译转移的过程。","a":"信号肽假说(1975年提出)：\n\n【过程】\n①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽(signal peptide)伸出；\n②信号识别颗粒(SRP，6种多肽+7S RNA)识别并结合信号肽及核糖体大亚基→翻译暂停；\n③SRP-核糖体复合物结合内质网膜上的SRP受体(停泊蛋白DP)；\n④核糖体附着到rER膜上，SRP释放，翻译恢复；\n⑤肽链边延伸边穿过易位子(translocon，核心Sec61)进入ER腔；\n⑥信号肽被信号肽酶切除，蛋白在ER腔折叠、修饰。\n\n【证据】1972年Milstein发现细胞内的免疫球蛋白N端比分泌到胞外的多一截(信号肽)。\n\n【意义】解释了分泌蛋白、膜蛋白如何定向进入ER。","kp":"ch03_s1_13","kps":"游离核糖体合成,信号肽伸出;SRP识别暂停;结合ER的SRP受体,SRP释放翻译续;经易位子入ER腔;信号肽酶切除"},{"id":"ch03_short_2","modI":0,"q":"简述内质网的功能。","a":"内质网分粗面内质网(rER)和光面内质网(sER)：\n\n【rER功能】\n①蛋白质合成——膜上有易位子，新生肽链共翻译转移入ER腔；\n②蛋白质的N-连接糖基化修饰；\n③新生多肽的折叠与装配(二硫键形成，PDI催化)；\n④蛋白质质量监控(只有正确折叠的蛋白才能离开ER)；\n⑤错误折叠蛋白经ERAD途径降解。\n\n【sER功能】\n①解毒(肝细胞，细胞色素P450)；\n②储钙(Ca库，Ca2+-ATPase泵入Ca2+，参与信号传递)；\n③合成膜脂(甘油磷脂和胆固醇)。\n\n【其他】\nER是内膜系统的重要组分，膜脂在ER合成后运往其他膜；ER驻留蛋白含KDEL信号。","kp":"ch03_s0_11","kps":"rER:蛋白合成、N-糖基化、折叠(二硫键/PDI)、质量监控、ERAD;sER:解毒(P450)、储钙、合成膜脂"},{"id":"ch03_short_3","modI":1,"q":"简述蛋白质糖基化的类型、部位和生物学功能。","a":"蛋白质糖基化类型：\n\n【N-连接糖基化】\n• 合成部位：起始于粗面内质网；\n• 结合残基：天冬酰胺(Asn)，序列Asn-X-Ser/Thr；\n• 方式：来自同一个寡糖前体(连在磷酸多萜醇上)整体转移。\n\n【O-连接糖基化】\n• 合成部位：高尔基体；\n• 结合残基：丝氨酸/苏氨酸(Ser/Thr)羟基；\n• 方式：一个个单糖加上去。\n\n【生物学功能】\n①促进蛋白质折叠(如抗体IgG、质膜糖蛋白血凝素)；\n②影响蛋白稳定性、半衰期和运输；\n③参与细胞识别与免疫(如血型抗原)；\n④溶酶体酶的M6P分选信号；\n⑤负责糖链合成加工的酶均为管家基因编码。","kp":"ch03_s1_3","kps":"N:rER起始、Asn-X-S/T、寡糖整体转移;O:高尔基体、Ser/Thr、逐个加;促折叠、识别免疫、M6P分选"},{"id":"ch03_short_4","modI":1,"q":"简述泛素-蛋白酶体系统降解蛋白质的机制。","a":"泛素-蛋白酶体系统(2004年诺贝尔化学奖)：\n\n【泛素】\n由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞。\n\n【泛素化过程】\n①E1(泛素活化酶)消耗ATP激活泛素；\n②E2(泛素结合酶)接受活化泛素；\n③E3(泛素连接酶)识别靶蛋白并将泛素转移至靶蛋白的赖氨酸残基；\n④多轮循环形成多聚泛素链(降解信号)。\n\n【蛋白酶体降解】\n26S蛋白酶体=20S催化核心+两个19S调节帽，由约50种亚基组成。\n①19S帽识别多聚泛素链；\n②去折叠、去泛素化；\n③20S核心催化降解为短肽；\n④泛素可回收再利用。\n\n【意义】\n调控细胞周期、凋亡、信号转导等；错误折叠蛋白(ERAD)也经此降解。","kp":"ch03_s1_20","kps":"泛素76aa保守;E1活化耗ATP、E2结合、E3连赖氨酸、多聚链;26S蛋白酶体识别去折叠降解,泛素回收"},{"id":"ch03_short_5","modI":1,"q":"比较N-连接和O-连接糖基化。","a":"N-连接 vs O-连接糖基化：\n\n| 特征 | N-连接 | O-连接 |\n|---|---|---|\n| 合成部位 | 起始于粗面内质网(完成于高尔基体) | 高尔基体 |\n| 合成方式 | 来自同一个寡糖前体整体转移 | 一个个单糖加上去 |\n| 结合残基 | 天冬酰胺Asn(Asn-X-Ser/Thr) | 丝氨酸/苏氨酸Ser/Thr羟基 |\n| 前体 | 磷酸多萜醇(dolichol)连接的寡糖 | 单糖核苷酸 |\n\n【共同点】\n①都属于蛋白质翻译后修饰；\n②都由糖基转移酶催化；\n③糖链都位于细胞外侧/ER腔侧。\n\n【生物学功能】\n促进折叠、影响稳定性与半衰期、参与细胞识别与免疫、M6P分选信号等。","kp":"ch03_s1_2","kps":"N:rER起始、整体转移、Asn、磷酸多萜醇;O:高尔基体、逐个加、Ser/Thr;翻译后修饰、糖基转移酶、糖链外侧"},{"id":"ch03_short_6","modI":2,"q":"简述高尔基体的结构和功能。","a":"高尔基体(Golgi complex)结构：\n由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性：\n①顺面网状结构(CGN)——接收内质网合成的新物质；\n②中间膜囊——加工修饰；\n③反面网状结构(TGN)——输出端，分选运往溶酶体、质膜或胞外。\n\n高尔基体功能：\n①蛋白质的糖基化——O-连接糖基化在此进行；N-连接糖基化在此完成加工；\n②糖胺聚糖/蛋白聚糖的合成；\n③蛋白质加工、修饰；\n④分类装载运输的分选站(枢纽作用)——通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖信号序列与受体的相互作用；\n⑤植物细胞高尔基体参与细胞壁合成。\n\n【意义】高尔基体是内膜系统的'分拣中心'。","kp":"ch03_s2_0","kps":"顺面CGN、中间膜囊、反面TGN,具极性;功能:O-糖基化、N-糖加工、糖胺聚糖合成、分选装载枢纽、植物参与细胞壁"},{"id":"ch03_short_x1","modI":1,"q":"比较N-连接糖基化与O-连接糖基化在发生部位、连接残基和糖链合成方式上的区别。","a":"①发生部位：N-连接糖基化起始于粗面内质网（rER），在高尔基体加工完成；O-连接糖基化主要在高尔基体进行。②连接残基：N-连接糖链连接在Asn（天冬酰胺）残基的酰胺氮上，需序列Asn-X-Ser/Thr；O-连接糖链连接在Ser/Thr（丝氨酸/苏氨酸）的羟基氧上。③合成方式：N-连接糖链先由多萜醇载体携带来完成的寡糖前体，整体转移给Asn，再在高尔基体修剪加工；O-连接糖链是糖基逐个直接加到Ser/Thr上。","kps":"N:rER起始高尔基完成、连Asn、多萜醇载体整块转移;O:高尔基、连Ser/Thr羟基、逐个加糖","type":"比较型","kp":"ch03_s1_2"}],"calc":[{"id":"ch03_calc_1","modI":0,"q":"论述内膜系统的组成、膜泡运输途径及其生物学意义。","a":"内膜系统是真核细胞分室化的结构基础,膜泡运输实现区室间物质交流","steps":"【组成】\n由单层膜围绕、结构功能发生上相关的细胞器：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)。\n\n【膜泡运输途径】\n①分泌途径(向外)：ER→高尔基体(CGN→中间→TGN)→分泌小泡→质膜/胞外或溶酶体；\n②胞吞途径(向内)：质膜→早期胞内体→晚期胞内体→溶酶体；\n③回收途径：逃逸蛋白经COPI小泡返回ER。\n\n【意义】\n①实现细胞分室化，各细胞器功能专一、效率高；\n②完成蛋白质的合成、加工、分选和运输(分泌蛋白、膜蛋白、溶酶体酶)；\n③实现物质的摄取(胞吞)与降解(溶酶体)；\n④维持细胞器膜的特性和动态平衡；\n⑤是真核细胞比原核细胞复杂高效的根本原因。","kp":"ch03_s0_0","kps":"组成:ER/高尔基/溶酶体/内体/液泡/分泌小泡(不含线粒体叶绿体过氧化物酶体);途径:分泌、胞吞、COPI回收;意义:分室化、加工分选、摄取降解、膜动态"},{"id":"ch03_calc_2","modI":0,"q":"论述内质网的蛋白质质量监控体系及其意义。","a":"ER质量监控确保只有正确折叠的蛋白才能离开ER,错误蛋白被降解","steps":"【监控体系组成】\n①分子伴侣：Bip(识别错误折叠/未组装蛋白)、Hsp70家族；\n②折叠酶：PDI(催化二硫键形成与重排)；\n③糖基化系统：N-连接糖基化参与折叠监控；\n④ER驻留信号KDEL使Bip/PDI留在ER。\n\n【监控机制】\n①新生肽链进入ER腔→分子伴侣帮助折叠；\n②正确折叠和装配的蛋白→允许离开ER运往高尔基体；\n③错误折叠蛋白→被Bip滞留→反复尝试折叠；\n④长期不能正确折叠→逆向转运至胞质(ERAD)→泛素化→26S蛋白酶体降解。\n\n【意义】\n①保证分泌蛋白和膜蛋白的质量；\n②防止错误折叠蛋白聚集造成细胞损伤；\n③与多种疾病相关(如囊性纤维化CFTR突变、α1-抗胰蛋白酶缺乏症等折叠病)；\n④维持细胞稳态。","kp":"ch03_s0_18","kps":"组成:Bip/Hsp70、PDI、N糖基化、KDEL;机制:折叠→正确放行/错误滞留→ERAD→泛素化→26S降解;意义:质量、防聚集、折叠病、稳态"},{"id":"ch03_calc_3","modI":2,"q":"论述溶酶体的形成、功能及其与疾病的关系。","a":"溶酶体是细胞的消化系统,其酶经M6P途径分选形成,功能异常导致溶酶体贮积症","steps":"【形成(M6P途径)】\n①溶酶体酶在rER合成并进行N-连接糖基化；\n②在高尔基体CGN，由N-乙酰葡萄糖胺磷酸转移酶催化加上6-磷酸甘露糖(M6P)标志；\n③M6P受体识别并结合溶酶体酶；\n④包装入网格蛋白有被小泡→运往胞内体→溶酶体。\n(部分经M6P非依赖途径)\n\n【功能】\n①消化：'清道夫'，清除无用生物大分子、衰老细胞器、凋亡细胞及吞噬的营养大分子；\n②吞噬(phagocytosis)：消化细菌等外源物质；\n③自噬(autophagy)：降解自身老化废弃的细胞器和蛋白；\n④参与蛋白质存量调节(除泛素途径外的另一途径)；\n⑤维持内部酸性环境(H+泵，pH≈5)。\n\n【疾病】\n溶酶体酶缺陷→底物不能被降解→溶酶体贮积症(如泰-萨克斯病、戈谢病、I细胞病等)，表现为神经退行、肝脾肿大等。","kp":"ch03_s2_2","kps":"形成:M6P途径(加签→受体→网格蛋白小泡→内体→溶酶体);功能:消化/吞噬/自噬/蛋白存量/酸性;疾病:贮积症"},{"id":"ch03_calc_x2","modI":0,"q":"说明信号肽引导分泌蛋白进行共翻译转移的分子机制（从SRP到易位子）。","a":"①分泌蛋白mRNA在游离核糖体上起始翻译，新生肽N端信号肽一露出即被信号识别颗粒（SRP）识别并结合。②SRP结合后暂停翻译（延缓延伸），并引导核糖体-mRNA-新生肽复合物结合到内质网膜上的SRP受体（停泊蛋白）。③核糖体与内质网膜上的易位子（translocon，核心为Sec61复合体）对接，SRP释放，翻译恢复。④新生肽链经易位子中央孔道边合成边进入ER腔，信号肽被信号肽酶切除。⑤肽链在ER腔内由分子伴侣帮助折叠，完成共翻译转移。","kps":"游离核糖体起始;信号肽→SRP识别并暂停;结合SRP受体停泊;对接易位子(Sec61);边合成边入腔;信号肽被切除;ER腔折叠","type":"机制型","kp":"ch03_s0_36"},{"id":"ch03_calc_x3","modI":0,"q":"设计实验验证某分泌蛋白经“内质网→高尔基体→质膜”的运输路径。","a":"思路一（脉冲-追踪放射自显影）：用3H-亮氨酸短时脉冲标记细胞合成蛋白，随后在不同时间点取材，用放射自显影或免疫电镜观察放射性标记依次出现在内质网、高尔基体、分泌小泡、质膜/细胞外。思路二（荧光蛋白标记）：将该分泌蛋白与GFP融合表达，用荧光显微镜/活细胞成像追踪荧光信号从ER到高尔基体再到质膜的动态过程；可用高尔基体特异荧光探针共定位。对照：加入蛋白合成抑制剂或低温（如20℃）阻断运输，观察信号是否停滞在ER或高尔基体。预期：标记信号按ER→高尔基体→质膜的顺序依次转移，证明该运输路径。","kps":"脉冲-追踪(3H-亮氨酸/放射自显影);或GFP融合活细胞成像;高尔基体探针共定位;低温/抑制剂阻断对照;预期顺序ER→高尔基→质膜","type":"实验设计型","kp":"ch03_s0_6"}],"term":[{"id":"ch03_term_1","modI":0,"term":"内膜系统(Endomembrane System)","def":"①在结构、功能乃至发生上相关的、由单层膜围绕成的细胞器或细胞结构（定义）。②组成：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)（组成）。③特点：膜相互流动、可相互转化（特点）。④意义：是真核细胞分室化的基础（意义）。","kps":"踩分点:①定义(1分)②组成(2分)③意义(1分)","kp":"ch03_s0_2"},{"id":"ch03_term_2","modI":0,"term":"粗面内质网(rER)","def":"①膜表面分布大量核糖体的内质网，多呈扁囊状（定义）。②功能：合成分泌性蛋白和膜蛋白；蛋白质N-连接糖基化；新生肽折叠与装配；蛋白质质量监控（功能）。③膜上有易位子(translocon)介导肽链进入ER腔（结构）。","kps":"踩分点:①定义(1分)②功能(2分)③易位子(1分)","kp":"ch03_s0_10"},{"id":"ch03_term_3","modI":0,"term":"光面内质网(sER)","def":"①表面无核糖体的内质网（定义）。②功能：解毒(肝细胞细胞色素P450)；储钙(Ca库，Ca2+-ATPase泵入，参与信号传递)；合成膜脂(甘油磷脂和胆固醇)（功能）。","kps":"踩分点:①定义(1分)②三大功能(3分)","kp":"ch03_s0_9"},{"id":"ch03_term_4","modI":0,"term":"易位子(Translocon)","def":"①rER膜上的蛋白复合体，中心有直径2nm的孔道（定义）。②核心为Sec61复合体(Sec61α/β/γ)，高度保守（结构）。③功能：介导新生肽链进入ER腔（功能）。","kps":"踩分点:①定义(1分)②Sec61(1分)③功能(1分)","kp":"ch03_s0_19"},{"id":"ch03_term_5","modI":1,"term":"信号肽(Signal Peptide)","def":"①位于分泌蛋白N端、引导蛋白进入ER的短肽序列（定义）。②特点：通常位于N端，完成使命后被信号肽酶切除（特点）。③机制：被SRP识别→核糖体停泊到ER膜→共翻译转移（机制）。④证据：1972年Milstein发现细胞内免疫球蛋白N端比胞外多一截（证据）。","kps":"踩分点:①定义(1分)②特点(1分)③机制(1分)④证据(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_6","modI":1,"term":"信号识别颗粒(SRP)","def":"①由6种多肽和1个300核苷酸(7S)RNA组成的核糖核蛋白复合物（定义）。②功能：既结合新生肽信号序列，又结合核糖体大亚基，使翻译暂停（功能）。③作用：将核糖体引导到ER膜的SRP受体(停泊蛋白DP)上（作用）。","kps":"踩分点:①组成(1分)②功能(2分)③与SRP受体(1分)","kp":"ch03_s1_13"},{"id":"ch03_term_7","modI":0,"term":"分子伴侣(Molecular Chaperone)","def":"①能识别并结合正在合成或部分折叠的多肽、帮助其折叠装配的蛋白（定义）。②特点：不构成最终产物的一部分；高度保守(如Hsp70)（特点）。③举例：Bip、Hsp70、伴侣蛋白GroEL/GroES（举例）。④意义：帮助蛋白正确折叠、防止聚集（意义）。","kps":"踩分点:①定义(1分)②特点(1分)③举例(1分)④意义(1分)","kp":"ch03_s0_4"},{"id":"ch03_term_8","modI":0,"term":"Bip蛋白（BiP protein）","def":"①内质网驻留的分子伴侣(binding protein)（定义）。②功能：识别不正确折叠或未组装的蛋白，防止聚集，帮助折叠（功能）。③含KDEL内质网驻留信号，被保留在ER中（特点）。","kps":"踩分点:①定义(1分)②功能(2分)③KDEL(1分)","kp":"ch03_s0_0"},{"id":"ch03_term_9","modI":1,"term":"泛素(Ubiquitin)","def":"①由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞（定义）。②功能：作为蛋白质降解的标签，共价结合到靶蛋白赖氨酸残基上（功能）。③泛素化需E1/E2/E3三种酶，多聚泛素链是降解信号（机制）。④发现获2004年诺贝尔化学奖（意义）。","kps":"踩分点:①定义(1分)②功能(1分)③三种酶(1分)④诺贝尔奖(1分)","kp":"ch03_s1_17"},{"id":"ch03_term_10","modI":1,"term":"蛋白酶体(Proteasome)","def":"①细胞内降解蛋白质的大分子复合体，由约50种亚基组成（定义）。②结构：26S蛋白酶体=20S催化核心+两个19S调节帽（结构）。③功能：识别多聚泛素链，将泛素化蛋白降解为短肽（功能）。","kps":"踩分点:①定义(1分)②结构(2分)③功能(1分)","kp":"ch03_s1_20"},{"id":"ch03_term_11","modI":2,"term":"高尔基体(Golgi Complex)","def":"①由扁平膜囊和囊泡组成的细胞器，具极性(cis/medial/trans)（定义）。②功能：蛋白质O-连接糖基化、N-连接糖基化加工；蛋白质分选装载运输的枢纽；糖胺聚糖合成（功能）。③CGN接收ER物质，TGN输出到溶酶体/质膜/胞外（极性）。","kps":"踩分点:①定义(1分)②功能(2分)③极性区室(1分)","kp":"ch03_s2_0"},{"id":"ch03_term_12","modI":2,"term":"溶酶体(Lysosome)","def":"①单层膜包围、含多种酸性水解酶的细胞器，是细胞的消化系统（定义）。②特点：内部酸性(pH≈5，H+泵维持)；膜高度糖基化保护；异质性（特点）。③功能：吞噬消化外源物质、自噬降解自身老化细胞器、参与蛋白存量调节（功能）。④酶经M6P途径分选（分选）。","kps":"踩分点:①定义(1分)②特点(1分)③功能(2分)④M6P(1分)","kp":"ch03_s2_1"},{"id":"ch03_term_13","modI":2,"term":"M6P分选途径（M6P sorting pathway）","def":"①通过6-磷酸甘露糖(M6P)标志将溶酶体酶靶向到溶酶体的途径（定义）。②过程：溶酶体酶在rER合成/N-糖基化→高尔基体CGN由N-乙酰葡萄糖胺磷酸转移酶加上M6P→M6P受体识别→包装入运输小泡→溶酶体（过程）。③意义：保证溶酶体酶正确分选（意义）。","kps":"踩分点:①定义(1分)②过程(2分)③意义(1分)","kp":"ch03_s2_15"},{"id":"ch03_term_14","modI":2,"term":"细胞自噬(Autophagy)","def":"①细胞在自噬相关基因调控下，降解自身受损或需淘汰更新的物质(细胞器、大分子)并再利用的过程（定义）。②过程：形成自噬体→与溶酶体融合→降解（过程）。③意义：清除受损细胞器、维持稳态、应对饥饿（意义）。","kps":"踩分点:①定义(1分)②过程(1分)③意义(2分)","kp":"ch03_s2_10"},{"id":"ch03_term_15","modI":0,"term":"分子伴侣介导的蛋白折叠（Chaperone-mediated protein folding）","def":"①分子伴侣通过反复结合与释放，帮助新生多肽折叠的机制（定义）。②与伴侣蛋白(GroEL/GroES)的隔离腔室折叠方式不同（区别）。③最终三维构象仍由氨基酸序列决定（特点）。","kps":"踩分点:①定义(1分)②与伴侣蛋白区别(2分)③序列决定构象(1分)","kp":"ch03_s0_18"},{"id":"ch03_term_16","modI":1,"term":"ER驻留信号(KDEL)","def":"①内质网驻留蛋白C端的一段回收信号序列(KDEL)（定义）。②功能：使Bip、PDI等驻留蛋白被保留在ER中而不被分泌（功能）。③机制：逃逸到高尔基体的驻留蛋白经KDEL受体识别，由COPI小泡回收回ER（机制）。","kps":"踩分点:①定义(1分)②功能(1分)③回收机制(2分)","kp":"ch03_s1_13"}],"preview":{"main":"本章围绕真核细胞的内膜系统，讲解细胞如何通过分室化实现蛋白质的合成、加工、分选与运输。核心内容包括内质网和高尔基体的结构与功能、信号肽假说与共翻译转运、糖基化与分子伴侣、以及溶酶体和液泡的形成与分选机制，是理解细胞器间物质流与信息流的关键一章。","questions":["真核细胞为什么要进行分室化？内膜系统由哪些细胞器组成，它们之间如何相互联系？","分泌蛋白是如何被定向转运到内质网的？信号肽、SRP、SRP受体和易位子各自发挥什么作用？","可溶性蛋白、跨膜蛋白和多次跨膜蛋白在ER膜上的转运方式有何不同？起始转移序列和停止转移序列如何决定膜蛋白的拓扑结构？","内质网中的N-连接糖基化、二硫键形成和分子伴侣如何保证蛋白质正确折叠？错误折叠的蛋白最终如何被降解？","高尔基体在蛋白质加工和分选中扮演什么角色？M6P分选信号是如何把溶酶体酶准确送到溶酶体的？","溶酶体有哪些消化类型和功能？细胞自噬与溶酶体在蛋白质存量调节中有何意义？"]},"appcards":[{"front":"简述信号肽假说及分泌蛋白共翻译转移的过程。","back":"信号肽假说(1975年提出)：\n\n【过程】\n①蛋白质起始合成在细胞质游离核糖体上，肽链生长至约80个氨基酸后，N端信号肽(signal peptide)伸出；\n②信号识别颗粒(SRP，6种多肽+7S RNA)识别并结合信号肽及核糖体大亚基→翻译暂停；\n③SRP-核糖体复合物结合内质网膜上的SRP受体(停泊蛋白DP)；\n④核糖体附着到rER膜上，SRP释放，翻译恢复；\n⑤肽链边延伸边穿过易位子(translocon，核心Sec61)进入ER腔；\n⑥信号肽被信号肽酶切除，蛋白在ER腔折叠、修饰。\n\n【证据】1972年Milstein发现细胞内的免疫球蛋白N端比分泌到胞外的多一截(信号肽)。\n\n【意义】解释了分泌蛋白、膜蛋白如何定向进入ER。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"简述内质网的功能。","back":"内质网分粗面内质网(rER)和光面内质网(sER)：\n\n【rER功能】\n①蛋白质合成——膜上有易位子，新生肽链共翻译转移入ER腔；\n②蛋白质的N-连接糖基化修饰；\n③新生多肽的折叠与装配(二硫键形成，PDI催化)；\n④蛋白质质量监控(只有正确折叠的蛋白才能离开ER)；\n⑤错误折叠蛋白经ERAD途径降解。\n\n【sER功能】\n①解毒(肝细胞，细胞色素P450)；\n②储钙(Ca库，Ca2+-ATPase泵入Ca2+，参与信号传递)；\n③合成膜脂(甘油磷脂和胆固醇)。\n\n【其他】\nER是内膜系统的重要组分，膜脂在ER合成后运往其他膜；ER驻留蛋白含KDEL信号。","points":"","mod":0,"modName":"模块一：真核细胞分室化与内质网","level":"掌握","src":"题库"},{"front":"简述蛋白质糖基化的类型、部位和生物学功能。","back":"蛋白质糖基化类型：\n\n【N-连接糖基化】\n• 合成部位：起始于粗面内质网；\n• 结合残基：天冬酰胺(Asn)，序列Asn-X-Ser/Thr；\n• 方式：来自同一个寡糖前体(连在磷酸多萜醇上)整体转移。\n\n【O-连接糖基化】\n• 合成部位：高尔基体；\n• 结合残基：丝氨酸/苏氨酸(Ser/Thr)羟基；\n• 方式：一个个单糖加上去。\n\n【生物学功能】\n①促进蛋白质折叠(如抗体IgG、质膜糖蛋白血凝素)；\n②影响蛋白稳定性、半衰期和运输；\n③参与细胞识别与免疫(如血型抗原)；\n④溶酶体酶的M6P分选信号；\n⑤负责糖链合成加工的酶均为管家基因编码。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"简述泛素-蛋白酶体系统降解蛋白质的机制。","back":"泛素-蛋白酶体系统(2004年诺贝尔化学奖)：\n\n【泛素】\n由76个氨基酸组成的小分子球蛋白，高度保守，普遍存在于真核细胞。\n\n【泛素化过程】\n①E1(泛素活化酶)消耗ATP激活泛素；\n②E2(泛素结合酶)接受活化泛素；\n③E3(泛素连接酶)识别靶蛋白并将泛素转移至靶蛋白的赖氨酸残基；\n④多轮循环形成多聚泛素链(降解信号)。\n\n【蛋白酶体降解】\n26S蛋白酶体=20S催化核心+两个19S调节帽，由约50种亚基组成。\n①19S帽识别多聚泛素链；\n②去折叠、去泛素化；\n③20S核心催化降解为短肽；\n④泛素可回收再利用。\n\n【意义】\n调控细胞周期、凋亡、信号转导等；错误折叠蛋白(ERAD)也经此降解。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"比较N-连接和O-连接糖基化。","back":"N-连接 vs O-连接糖基化：\n\n| 特征 | N-连接 | O-连接 |\n|---|---|---|\n| 合成部位 | 起始于粗面内质网(完成于高尔基体) | 高尔基体 |\n| 合成方式 | 来自同一个寡糖前体整体转移 | 一个个单糖加上去 |\n| 结合残基 | 天冬酰胺Asn(Asn-X-Ser/Thr) | 丝氨酸/苏氨酸Ser/Thr羟基 |\n| 前体 | 磷酸多萜醇(dolichol)连接的寡糖 | 单糖核苷酸 |\n\n【共同点】\n①都属于蛋白质翻译后修饰；\n②都由糖基转移酶催化；\n③糖链都位于细胞外侧/ER腔侧。\n\n【生物学功能】\n促进折叠、影响稳定性与半衰期、参与细胞识别与免疫、M6P分选信号等。","points":"","mod":1,"modName":"模块二：蛋白质分选与降解","level":"掌握","src":"题库"},{"front":"简述高尔基体的结构和功能。","back":"高尔基体(Golgi complex)结构：\n由顺面(cis)、中间膜囊(medial)、反面(trans)的扁平膜囊堆叠而成，具极性：\n①顺面网状结构(CGN)——接收内质网合成的新物质；\n②中间膜囊——加工修饰；\n③反面网状结构(TGN)——输出端，分选运往溶酶体、质膜或胞外。\n\n高尔基体功能：\n①蛋白质的糖基化——O-连接糖基化在此进行；N-连接糖基化在此完成加工；\n②糖胺聚糖/蛋白聚糖的合成；\n③蛋白质加工、修饰；\n④分类装载运输的分选站(枢纽作用)——通过膜泡运输将蛋白运往溶酶体、质膜或分泌到胞外，依赖信号序列与受体的相互作用；\n⑤植物细胞高尔基体参与细胞壁合成。\n\n【意义】高尔基体是内膜系统的'分拣中心'。","points":"","mod":2,"modName":"模块三：高尔基体与溶酶体","level":"掌握","src":"题库"},{"front":"论述内膜系统的组成、膜泡运输途径及其生物学意义。","back":"【组成】\n由单层膜围绕、结构功能发生上相关的细胞器：内质网、高尔基体、溶酶体、胞内体、液泡、分泌小泡等(不含线粒体/叶绿体/过氧化物酶体)。\n\n【膜泡运输途径】\n①分泌途径(向外)：ER→高尔基体(CGN→中间→TGN)→分泌小泡→质膜/胞外或溶酶体；\n②胞吞途径(向内)：质膜→早期胞内体→晚期胞内体→溶酶体；\n③回收途径：逃逸蛋白经COPI小泡返回ER。\n\n【意义】\n①实现细胞分室化，各细胞器功能专一、效率高；\n②完成蛋白质的合成、加工、分选和运输(分泌蛋白、膜蛋白、溶酶体酶)；\n③实现物质的摄取(胞吞)与降解(溶酶体)；\n④维持细胞器膜的特性和动态平衡；\n⑤是真核细胞比原核细胞复杂高效的根本原因。","points":"","mod":0,"modName":"模块一：真核细胞分室化与内质网","level":"掌握","src":"题库"},{"front":"论述内质网的蛋白质质量监控体系及其意义。","back":"【监控体系组成】\n①分子伴侣：Bip(识别错误折叠/未组装蛋白)、Hsp70家族；\n②折叠酶：PDI(催化二硫键形成与重排)；\n③糖基化系统：N-连接糖基化参与折叠监控；\n④ER驻留信号KDEL使Bip/PDI留在ER。\n\n【监控机制】\n①新生肽链进入ER腔→分子伴侣帮助折叠；\n②正确折叠和装配的蛋白→允许离开ER运往高尔基体；\n③错误折叠蛋白→被Bip滞留→反复尝试折叠；\n④长期不能正确折叠→逆向转运至胞质(ERAD)→泛素化→26S蛋白酶体降解。\n\n【意义】\n①保证分泌蛋白和膜蛋白的质量；\n②防止错误折叠蛋白聚集造成细胞损伤；\n③与多种疾病相关(如囊性纤维化CFTR突变、α1-抗胰蛋白酶缺乏症等折叠病)；\n④维持细胞稳态。","points":"","mod":0,"modName":"模块一：真核细胞分室化与内质网","level":"掌握","src":"题库"},{"front":"论述溶酶体的形成、功能及其与疾病的关系。","back":"【形成(M6P途径)】\n①溶酶体酶在rER合成并进行N-连接糖基化；\n②在高尔基体CGN，由N-乙酰葡萄糖胺磷酸转移酶催化加上6-磷酸甘露糖(M6P)标志；\n③M6P受体识别并结合溶酶体酶；\n④包装入网格蛋白有被小泡→运往胞内体→溶酶体。\n(部分经M6P非依赖途径)\n\n【功能】\n①消化：'清道夫'，清除无用生物大分子、衰老细胞器、凋亡细胞及吞噬的营养大分子；\n②吞噬(phagocytosis)：消化细菌等外源物质；\n③自噬(autophagy)：降解自身老化废弃的细胞器和蛋白；\n④参与蛋白质存量调节(除泛素途径外的另一途径)；\n⑤维持内部酸性环境(H+泵，pH≈5)。\n\n【疾病】\n溶酶体酶缺陷→底物不能被降解→溶酶体贮积症(如泰-萨克斯病、戈谢病、I细胞病等)，表现为神经退行、肝脾肿大等。","points":"","mod":2,"modName":"模块三：高尔基体与溶酶体","level":"掌握","src":"题库"},{"front":"比较粗面内质网(rER)与光面内质网(sER)在形态和功能上的主要差异。","back":"形态：rER膜表面有核糖体，多呈扁囊状；sER无核糖体，多呈管状。功能：rER合成分泌蛋白和膜蛋白，进行N-糖基化；sER合成脂类、解毒、储钙。两者膜连续。","points":"核糖体有无；形态差异；rER合成蛋白；sER脂类/解毒/储钙","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说内质网是蛋白质分选的起点？请从共翻译转移的角度说明。","back":"分泌蛋白在游离核糖体起始合成；N端信号肽被SRP识别，翻译暂停；SRP-核糖体复合物结合ER膜SRP受体；翻译恢复，肽链边合成边进入ER腔，完成共翻译转移。","points":"游离核糖体起始；信号肽-SRP；SRP受体停泊；共翻译入ER腔","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较N-连接糖基化与O-连接糖基化在合成部位、方式和结合氨基酸上的异同。","back":"部位：N-连接起始于rER，O-连接在高尔基体；方式：N-连接来自同一寡糖前体，O-连接逐个加单糖；氨基酸：N-连接为Asn，O-连接为Ser/Thr。","points":"N在rER起始；O在高尔基；N用寡糖前体；O逐个加；Asn vs Ser/Thr","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么真核细胞中二硫键只在ER腔内形成？其意义是什么？","back":"ER腔为氧化环境，且含二硫键异构酶(PDI)催化；胞质为还原环境，不利于二硫键稳定。意义：保证分泌蛋白和膜蛋白正确折叠与稳定。","points":"ER腔氧化环境；PDI催化；胞质还原；正确折叠","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明分子伴侣在ER中的作用。","back":"Bip是ER驻留分子伴侣，识别错误折叠或未组装蛋白，防止其聚集，帮助正确折叠；Hsp70家族协助新生肽折叠。它们不构成最终产物。","points":"Bip识别错误折叠；防止聚集；帮助折叠；不构成产物","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞中SRP受体(停泊蛋白)功能缺失，分泌蛋白的合成与运输会怎样？","back":"SRP-核糖体复合物无法停泊到ER膜；翻译不能恢复或肽链不能进入ER腔；分泌蛋白无法共翻译转移入ER，后续分泌途径受阻。","points":"不能停泊ER膜；翻译暂停不能恢复；不能入ER腔；分泌受阻","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较游离核糖体与膜结合核糖体在结构和功能上的异同。","back":"结构相同，均为核糖体；区别在于是否附着ER膜。游离核糖体合成胞质蛋白、核编码线粒体蛋白等；膜结合核糖体合成分泌蛋白、膜蛋白和溶酶体酶。","points":"结构相同；附着与否；游离合成胞质/线粒体蛋白；膜结合合成分泌/膜蛋白","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说高尔基体是蛋白质分选和运输的枢纽？","back":"高尔基体由顺面、中间、反面膜囊组成，具极性；接收ER新合成物质，进行加工修饰；通过信号序列与受体相互作用，将蛋白分选运往溶酶体、质膜或胞外。","points":"极性区室；接收ER物质；加工修饰；分选运往溶酶体/质膜/胞外","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明溶酶体异质性的表现。","back":"不同来源、不同发育阶段的溶酶体形态大小和所含水解酶不同；分为初级溶酶体(刚形成)、次级溶酶体(正在消化)、残余小体。","points":"来源/阶段不同；形态大小不同；酶类不同；初级/次级/残余小体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较吞噬作用与自噬作用在溶酶体消化中的异同。","back":"相同：最终均由溶酶体酸性水解酶降解。不同：吞噬作用摄取胞外物质如细菌、衰老红细胞；自噬作用降解细胞自身老化细胞器或生物大分子。","points":"均由溶酶体降解；吞噬摄胞外；自噬降解自身；举例","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么溶酶体膜不会被自身水解酶消化？","back":"溶酶体膜蛋白高度糖基化，保护膜不被水解酶消化；同时膜上有H+泵维持腔内酸性环境，水解酶在pH≈5时活性最高，在胞质中性pH下活性低。","points":"膜蛋白高度糖基化；H+泵维持酸性；酶最适pH≈5；胞质中性保护","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若溶酶体H+泵功能丧失，溶酶体的消化功能会受到什么影响？","back":"腔内pH升高，酸性水解酶活性降低或丧失；水解酶不能有效降解生物大分子；未降解物质在溶酶体内积累，影响细胞清除功能。","points":"pH升高；酶活性降低；降解受阻；物质积累","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"说明M6P分选信号在溶酶体酶定向运输中的作用。","back":"溶酶体酶在rER合成并N-糖基化；在高尔基体CGN，甘露糖残基被磷酸化形成M6P标志；M6P受体识别并分选，包装入运输小泡运往溶酶体。","points":"rER合成/N-糖基化；高尔基体磷酸化形成M6P；M6P受体识别；运往溶酶体","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若M6P受体缺失，溶酶体酶的运输会发生什么变化？","back":"溶酶体酶不能被M6P受体识别和分选；酶可能被分泌到细胞外，而不是运往溶酶体；溶酶体缺乏水解酶，导致未降解物质积累。","points":"不能识别分选；酶分泌到胞外；溶酶体缺酶；物质积累","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较信号肽与信号斑在蛋白质分选中的异同。","back":"信号肽是线性氨基酸序列，通常位于N端，完成使命后被切除；信号斑由折叠后空间结构形成，可位于蛋白内部。两者均为分选信号。","points":"信号肽线性/N端/可切除；信号斑空间结构；均为分选信号","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说ER的质量监控系统对细胞具有重要意义？","back":"只有正确折叠和装配的蛋白才能离开ER；错误折叠蛋白被滞留并逆向转运到胞质，经泛素-蛋白酶体系统降解；保证分泌蛋白和膜蛋白质量。","points":"正确折叠才能离开；错误折叠滞留；ERAD降解；保证蛋白质量","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明泛素-蛋白酶体系统降解错误折叠ER蛋白的过程。","back":"错误折叠ER蛋白被逆向转运到胞质；泛素分子共价结合到靶蛋白赖氨酸残基上；经E1、E2、E3催化形成多聚泛素链；26S蛋白酶体将其降解成短肽。","points":"逆向转运胞质；泛素化；E1/E2/E3；26S蛋白酶体降解","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若26S蛋白酶体功能被抑制，错误折叠蛋白的降解会怎样？","back":"泛素化的错误折叠蛋白不能被降解；在胞质中积累，可能形成聚集体；影响细胞正常功能，甚至导致细胞应激或死亡。","points":"不能降解；蛋白积累；形成聚集体；细胞功能受损","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"说明ER驻留信号KDEL的作用。","back":"Bip、PDI等ER驻留蛋白含KDEL序列；该信号使其被保留在ER中而不被分泌；保证ER内分子伴侣和折叠酶浓度充足。","points":"KDEL序列；保留在ER；不被分泌；保证伴侣/酶浓度","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"比较组成型分泌途径与调节型分泌途径的异同。","back":"相同：均经ER→高尔基体→分泌小泡运输。不同：组成型分泌持续进行，分泌小泡直接与质膜融合；调节型分泌小泡储存，需信号刺激才释放。","points":"均经ER/高尔基；组成型持续；调节型需信号；小泡储存","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"为什么说内质网是脂类合成的中心？","back":"sER合成构成细胞所需的绝大多数膜脂，包括甘油磷脂和胆固醇；磷脂酰胆碱在sER膜上经酶催化合成；膜脂在ER合成后运往其他膜。","points":"sER合成膜脂；甘油磷脂/胆固醇；磷脂酰胆碱合成；运往其他膜","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明sER的解毒功能。","back":"肝细胞sER很丰富，含细胞色素P450等酶；清除脂溶性药物和代谢产生的有害物质；多数解毒反应与氧化作用有关。","points":"肝细胞sER丰富；细胞色素P450；清除脂溶性药物；氧化反应","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"说明sER储钙功能与细胞信号传递的关系。","back":"ER膜上Ca2+-ATPase将胞质钙泵入ER腔，使腔内钙浓度高达3mM；sER通过释放/回收Ca2+调节细胞信号，如肌肉收缩。","points":"Ca2+-ATPase泵钙；腔内高钙；释放/回收Ca2+；肌肉收缩","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"若细胞中PDI功能缺失，分泌蛋白的折叠会受什么影响？","back":"二硫键不能正确形成或重排；分泌蛋白折叠异常；错误折叠蛋白被ER质量监控滞留并降解；分泌蛋白产量下降。","points":"二硫键形成异常；折叠异常；被滞留降解；分泌下降","mod":null,"modName":"应用综合","level":"掌握","src":"生成"},{"front":"举例说明放射自显影与电镜技术在研究膜泡运输中的应用。","back":"用放射性标记氨基酸脉冲标记胰腺腺泡细胞；追踪分泌蛋白在ER→Golgi→分泌小泡→细胞外的运输路径；证明膜泡运输的经典实验。","points":"放射性标记氨基酸；脉冲标记胰腺腺泡细胞；追踪ER→Golgi→小泡→胞外；经典实验","mod":null,"modName":"应用综合","level":"掌握","src":"生成"}],"jyq":[{"id":"jyq_ch03_1","kind":"short","q":"中膜体（mesosome）","a":"又称间体、质膜体、中间体。是某些细菌的质膜内陷经折叠后形成的一种重叠交粒体的基本功能类似的细胞器，故又称为拟线粒体。中间体膜上存在的呼吸酶可进行氧化磷酸化作用。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_2","kind":"fill","q":"植物细胞的和有类似溶酶体的功能。","a":"圆球体；糊粉粒。","src":"厦门大学，2008年","kp":null,"e":"植物细胞中的圆球体（脂质体）和糊粉粒含有水解酶，具有类似溶酶体的消化分解功能。","oe":["圆球体：是植物细胞的脂质贮藏细胞器，含多种水解酶，具类似溶酶体的分解功能。","糊粉粒：是种子中的蛋白质贮藏细胞器，也含水解酶，可起类似溶酶体的作用。"]},{"id":"jyq_ch03_3","kind":"short","q":"用柱层析方法可对细胞提取液中的蛋白质进行。","a":"纯化（分离）。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch03_4","kind":"mcq","q":"用3H-唾液酸对培养细胞进行脉冲标记，电镜放射自显影结果显示其标记物集中在哪一部位（）。","o":["A. 内质网","B. 高尔基体顺面膜囊","C. 高尔基体反面管网结构中","D. 溶酶体"],"a":"C","src":"南京师范大学，2008年","kp":null,"e":"唾液酸由唾液酸转移酶在反面高尔基体加到糖链末端，故脉冲标记集中在其反面管网结构。","oe":["错误：内质网只进行N-连接糖链的初步加工，不添加唾液酸。","错误：顺面膜囊负责接收产物与磷酸化等早期加工，无唾液酸转移酶。","正确：唾液酸转移酶位于反面高尔基体，标记集中在反面管网结构。","错误：溶酶体是水解酶的工作场所，不进行唾液酸修饰。"]},{"id":"jyq_ch03_5","kind":"short","q":"如何用CFP显示活细胞内蛋白质的运动？","a":"可以有两种方法。第一种方法是先找到该蛋白的抗体，以此蛋白为抗原，将该蛋白的抗体用绿色荧光蛋白标记，然后注人细胞中，根据抗体-抗原之间的反应，绿色荧光蛋白可以与待测蛋白相结合，通过在荧光显微镜下观察绿色荧光蛋白的活动就可以观察待测蛋白的运动。第二种方法更为可信，即将GFP与该蛋白基因融合构建质粒，然后将质粒转化人细胞质中，融合蛋白表达后在荧光显微镜下观察绿色荧光的运动，就可以间接观察到蛋白质的运动。","src":"上海交通大学，2007年","kp":null},{"id":"jyq_ch03_6","kind":"short","q":"如何将动物或植物组织或细胞制备成可在透射电镜下观察的超薄切片标本？","a":"①透射电镜所用的标本一般要切成50～100nm厚的薄片，即一个细胞要切成100～200片。②独特的技术环节：固定一脱水→渗透一包埋→聚合→超薄切片→置于铜质的载网（相当于载玻片）上→染色一透射电镜中观察。","src":"华中农业大学，2009年","kp":null},{"id":"jyq_ch03_7","kind":"short","q":"细胞组分的分离与分析有哪些基本的实验技术？","a":"哪些技术可用于大分子在细胞内的定性与定位研究？答细胞组分的分离方法：差速离心、密度梯度离心、速度沉降、等密度沉降以及利用流式细胞仪对细胞进行精确分选。细胞组分的分析方法：细胞组分的定性研究方法有组织化学、细胞化学、免疫荧光、免疫电镜技术等。细胞组分的定量研究方法主要有分光光度计和流式细胞仪分析方法。生物大分子在细胞内的定性与定位研究方法：免疫荧光、免疫电镜技术和原位杂交技术等。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_8","kind":"mcq","q":"下面哪种生物学功能可能与糖蛋白的糖侧链无关（）。","o":["A. 细胞识别作用","B. 增强糖蛋白的稳定性","C. 增加糖蛋白由高尔基体向细胞质膜的转运速率","D. 使糖蛋白折叠成正确的构象"],"a":"C","src":"南京师范大学，2009年","kp":null,"e":"糖蛋白糖侧链参与细胞识别、维持稳定和帮助折叠，但与糖蛋白向质膜的转运速率无直接关系。","oe":["错误：糖侧链参与细胞识别，如血型抗原与受体的识别。","错误：糖链可保护肽链、增强糖蛋白的稳定性。","正确：糖侧链主要影响折叠、稳定与识别，不直接决定向质膜的转运速率。","错误：糖链有类似分子伴侣的作用，有助于糖蛋白折叠成正确构象。"]},{"id":"jyq_ch03_9","kind":"short","q":"阐述动物细胞膜和细胞表面各自的结构特点及其相互关系。","a":"细胞膜是由磷脂双分子层构成骨架，蛋白质和脂类分子镶嵌于其中，且膜的结构处于流动变化中，其特征为镶嵌性、流动性、不对称性、蛋白质的极性。细胞膜的磷脂双分子层结构是整个细胞质膜的骨架，它具有将细胞质和外界环境隔离开来的作用。质膜上镶嵌着诸多蛋白质，这些蛋白质在信号转导和物质运输方面起着重要作用。这些蛋白质在细胞内外两个朝向上是不对称的，具有极性，这种极性也是与其信号转导和物质运输的功能相适应的。质膜表面存在一层富含糖类结构的细胞外被，具有细胞识别、血型抗原功能。细胞与细胞之间、细胞与细胞外基质间也往往通过这层细胞外被形成细胞连接结构，如封闭连接、锚定连接和通讯连接等。磷脂双分子层具有流动性，并且带动膜上的蛋白质等一起运动，并存在脂筏这样的亚微观结构。磷脂双分子层的流动性与脂质分子的类型、比率有关，与脂分子同膜蛋白及膜两侧的生物大分子之间的相互作用以及温度等环境条件有关。","src":"山东大学，2006年","kp":null},{"id":"jyq_ch03_10","kind":"short","q":"胞吞可分为两种类型：胞吞物质若为溶液的，则称为；若胞吞物为大的颗粒，形成的囊泡较大，则称为_。","a":"胞饮；吞噬。","src":"中国科学院，2007年","kp":null},{"id":"jyq_ch03_11","kind":"short","q":"新合成的、没有分选信号的蛋白质将被保留在中。","a":"细胞质溶液。","src":"中山大学，2009年","kp":null},{"id":"jyq_ch03_12","kind":"short","q":"C，植物（Cplant）","a":"通过还原型戊糖磷酸循环而进行CO2固定的植物称为C，植物，如小球藻、菠菜、大豆、稻、小麦等都是C植物。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_13","kind":"judge","q":"溶酶体合成构成细胞所需的包括磷脂和胆固醇在内的几乎全部的膜脂。","a":"错","src":"华中师范大学，2008年","kp":null,"e":"膜脂（磷脂、胆固醇等）主要由光面内质网合成，溶酶体只含水解酶，不承担膜脂合成，故说法错误。","oe":["选“对”：错误。溶酶体是含水解酶的消化细胞器，不负责合成膜脂。","选“错”：正确。构成细胞膜的膜脂几乎全部由光面内质网合成，故原说法错误。"]},{"id":"jyq_ch03_14","kind":"judge","q":"NLS可指导蛋白质进人过氧化物酶体。","a":"错","src":"华中师范大学，2008年","kp":null,"oe":["NLS富含碱性氨基酸，专一引导蛋白质入核，易被误认为也用于过氧化物酶体。","NLS只介导蛋白质进入细胞核，过氧化物酶体蛋白靠PTS1、PTS2信号引导。"]},{"id":"jyq_ch03_15","kind":"short","q":"所有进人早期内体的分子都毫无例外地进人后期内体，在那里与新合成的酸性水解酶会合并最终在溶酶体中被水解。","a":"错。活性大大降低。【答案】对。","src":"中山大学，2009年","kp":null},{"id":"jyq_ch03_16","kind":"judge","q":"M6P是溶酶体酶的分选标志，该标志是在内质网中合成的。","a":"对","src":"华中师范大学，2007年","kp":null,"e":"M6P（甘露糖-6-磷酸）是溶酶体水解酶的分选标志，溶酶体酶在糙面内质网合成并加工后带上M6P标志，用于高尔基体的分选，说法正确。","oe":["选“对”：正确。M6P是溶酶体酶的分选标志，溶酶体酶在糙面内质网合成并加工后带M6P，用于高尔基体分选。","选“错”：错误。溶酶体酶须具M6P标志才能被受体识别并分选入溶酶体，否认该标志则不成立。"]},{"id":"jyq_ch03_17","kind":"judge","q":"内质网是真核细胞中膜蛋白与膜合成的基地。","a":"对","src":"南京师范大学，2009年","kp":null,"e":"内质网合成膜脂并合成分泌蛋白与膜蛋白，是膜系统更新及膜蛋白、膜脂合成的基地，说法正确。","oe":["选“对”：正确。内质网合成膜脂和膜蛋白，是膜系统的重要来源，故说法成立。","选“错”：错误。若否认内质网合成膜脂与膜蛋白的功能，则不符合事实。"]},{"id":"jyq_ch03_18","kind":"fill","q":"当某种溶酶体酶缺失或溶酶体发生的某个环节出现故障时，细胞的溶酶体内常常充满了未被降解的物质而引起疾病。这类疾病一般称为，它是一种遗传病。","a":"储积症；隐性。","src":"南京师范大学，2009年","kp":null,"e":"溶酶体酶缺失致底物不能被降解而在溶酶体内堆积，引起溶酶体储积症，此类病多为隐性遗传。","oe":["储积症：某种溶酶体酶缺失时，底物不能被降解而在溶酶体内大量堆积，引起溶酶体储积症。","隐性：溶酶体储积症多为单基因隐性遗传病，杂合子携带者通常不发病。"]},{"id":"jyq_ch03_19","kind":"fill","q":"一种溶酶体贮存病是由于病人缺损N-乙酰葡萄糖胺磷酸转移酶，而不能产生，因而溶酶体酶在转运时，不能被受体识别进人溶酶体中，溶酶体中的生物大分子不能被降解。","a":"M6P标记。","src":"中山大学，2009年","kp":null,"e":"N-乙酰葡糖胺磷酸转移酶缺陷使溶酶体酶不能获得M6P标记，无法被高尔基体受体识别分选，导致酶分泌到细胞外（I细胞病）。","oe":["M6P标记：该酶缺陷使溶酶体酶缺乏M6P标记，不能被受体识别而误分泌到细胞外，溶酶体内底物堆积，故填M6P标记。"]},{"id":"jyq_ch03_20","kind":"fill","q":"肝细胞的解毒作用主要是在上进行的。因为上面含有丰富的系统，使有害物质转化。","a":"光面内质网；氧化还原酶。","src":"湖北大学，2008年","kp":null,"e":"肝细胞的解毒作用主要在光面内质网上进行，因上面含有丰富的氧化还原酶系，可将脂溶性有害物质转化以便排出。","oe":["光面内质网：肝细胞解毒主要在此进行，故第一个空填光面内质网。","氧化还原酶：光面内质网含丰富的氧化还原酶系（如细胞色素P450），使有害物质氧化转化，故第二个空填氧化还原酶。"]},{"id":"jyq_ch03_21","kind":"fill","q":"光面内质网功能主要包括和而糙面内质网最主要的功能是。","a":"合成脂类；解毒作用；精原代谢；蛋白质加工和修饰。","src":"山东大学，2006年","kp":null,"e":"光面内质网主要功能是合成脂类、解毒和参与糖原代谢，糙面内质网最主要的功能是对蛋白质进行加工和修饰。","oe":["合成脂类：光面内质网是细胞合成磷脂、胆固醇等膜脂的主要场所。","解毒作用：光面内质网含氧化还原酶，可对药物、毒物进行氧化转化而解毒。","糖原代谢：光面内质网膜上含葡萄糖-6-磷酸酶，参与糖原分解与血糖调节（题干“精原代谢”应为“糖原代谢”）。","蛋白质加工和修饰：糙面内质网最主要的功能是对新合成的分泌蛋白进行折叠、糖基化等加工修饰。"]},{"id":"jyq_ch03_22","kind":"fill","q":"通常内体与内吞体结合，在内体作用下，内吞体中和分离，形成的膜泡所携带的物质最终与溶酶体结合。","a":"酸性环境；配体；受体；内体膜。","src":"山东大学，2006年","kp":null,"e":"内体的酸性环境使受体与配体解离，配体进入溶酶体降解，受体经膜泡回收，内体膜包裹配体形成的内体性溶酶体最终与溶酶体融合。","oe":["酸性环境：内体呈酸性，使受体构象改变而与配体解离，是分选的驱动力。","配体：在酸性环境中与受体分离，随后被运入溶酶体降解。","受体：解离后经膜泡返回细胞膜循环再利用。","内体膜：包裹配体出芽形成膜泡（内体性溶酶体），最终与溶酶体融合。"]},{"id":"jyq_ch03_23","kind":"fill","q":"在糙面内质网上合成的，除进行糖基化修饰外，还可以进行和等修饰作用，以使新生多肽链折叠成正确的三维结构。","a":"蛋白质；羟基化；酰基化；二硫键的形成。","src":"中国科学院，2007年","kp":null,"e":"糙面内质网合成的蛋白质除糖基化外，还可进行羟基化、酰基化和二硫键形成等修饰，帮助新生肽链折叠成正确三维结构。","oe":["蛋白质：糙面内质网主要合成分泌蛋白、膜蛋白和驻留蛋白。","羟基化：脯氨酸、赖氨酸残基可被羟基化（如胶原蛋白），有助于结构稳定。","酰基化：多肽可发生N-豆蔻酰化、棕榈酰化等酰基化修饰。","二硫键的形成：由二硫键异构酶催化形成二硫键，稳定蛋白质的空间结构。"]},{"id":"jyq_ch03_24","kind":"short","q":"磷脂合成是在光面内质网的面上进行的，合成的磷脂向其转移询式交要4匙0和。","a":"细胞质基质侧；出芽的方式转运到高尔基体；借水溶性载体蛋白在膜之间转移。","src":"中国科学院，2007年","kp":null},{"id":"jyq_ch03_25","kind":"mcq","q":"细胞质中合成脂类的重要场所是。","o":["A. 糙面内质网","B. 光面内质网","C. 高尔基体","D. 胞质溶胶"],"a":"B","src":"中国科学院，2008年","kp":null,"e":"光面内质网富含脂类合成酶系，是细胞质中合成磷脂、胆固醇等脂类的重要场所。","oe":["错误：糙面内质网表面附核糖体，主要合成分泌蛋白和膜蛋白。","正确：光面内质网含脂类合成酶系，是脂类合成的主要场所。","错误：高尔基体主要加工、分选蛋白质和脂类，不主营合成。","错误：胞质溶胶可合成脂肪酸，但膜脂组装主要在光面内质网。"]},{"id":"jyq_ch03_26","kind":"mcq","q":"膜蛋白高度糖基化的是（）。","o":["A. 内质网膜","B. 质膜","C. 高尔基体膜","D. 溶酶体"],"a":"D","src":"华中农业大学，2009年","kp":null,"e":"溶酶体膜蛋白高度糖基化，糖链朝向膜内侧，可保护膜蛋白免受腔内酸性水解酶降解。","oe":["内质网膜蛋白糖基化程度不高，主要参与蛋白质加工与运输。","质膜蛋白有糖基化，但程度不及溶酶体膜蛋白高度糖基化。","高尔基体膜蛋白有糖基化，程度低于溶酶体膜。","正确：溶酶体膜蛋白高度糖基化以抵抗酸性水解酶，防止自身被消化。"]},{"id":"jyq_ch03_27","kind":"mcq","q":"下面哪种细胞器不属于细胞内膜系统的细胞器（）。","o":["A. 溶酶体","B. 内质网","C. 高尔基体","D. 过氧化物酶体"],"a":"D","src":"南京师范大学，2009年","kp":null,"e":"内膜系统包括内质网、高尔基体、溶酶体及膜泡等；过氧化物酶体独立形成，不属内膜系统。","oe":["溶酶体由高尔基体出芽形成，属内膜系统。","内质网是内膜系统的核心成员，与多种膜性细胞器相连。","高尔基体是内膜系统的重要组成。","正确：过氧化物酶体不参与内膜系统膜泡运输，不属于内膜系统。"]},{"id":"jyq_ch03_28","kind":"mcq","q":"下列哪种细胞器在代谢过程中直接需要氧气（）。","o":["A. 溶酶体","B. 核糖体","C. 高尔基体","D. 过氧化物酶体"],"a":"D","src":"南京师范大学，2009年","kp":null,"e":"过氧化物酶体含氧化酶，可直接以O2为受氢体氧化底物生成H2O2，是代谢中直接需氧的细胞器。","oe":["错误：溶酶体进行水解反应，不直接消耗氧气。","错误：核糖体合成蛋白质，不涉及需氧氧化。","错误：高尔基体负责加工分选，不直接需要氧气。","正确：过氧化物酶体的氧化酶直接利用O2氧化底物，产生H2O2。"]},{"id":"jyq_ch03_29","kind":"mcq","q":"高尔基体的极性反映在它们的形成而到成熟的酶成分不同，成熟面含有较多的（)。","o":["A. 唾液酸转移酶","B. 甘露糖磷酸化酶","C. N-葡萄糖胺转移酶","D. 半乳糖转移酶"],"a":"A","src":"南开大学，2009年","kp":null,"e":"高尔基体有极性，反面（成熟面）含唾液酸转移酶等晚期加工酶，完成糖链末端唾液酸化。","oe":["正确：唾液酸转移酶位于反面高尔基体，成熟面含量较多。","错误：甘露糖磷酸化酶属顺面或中间膜囊的早期加工酶。","错误：N-乙酰葡萄糖胺转移酶主要在中间膜囊，非成熟面标志酶。","错误：半乳糖转移酶位于中间与反面之间，成熟面以唾液酸转移酶为主。"]},{"id":"jyq_ch03_30","kind":"short","q":"试比较光面内质网与糙面内质网的形态结构与基本功能。","a":"糙面内质网有核糖体附着，多呈扁平囊状。光面内质网无核糖体附着，多呈分枝管状，两者互相连接形成一个完整的膜池。糙面内质网主要进行分泌蛋白等蛋白质合成。光面内质网主要进行脂类合成和解毒功能等。内质网腔中还具有多肽折叠、修饰及贮存Ca+等多种功能。【答案】蛋白质的糖基化类型：①N-连接的糖基化：主要发生在内质网中；②0-连接的糖基化：主要发生在高尔基体中。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch03_31","kind":"short","q":"溶酶体的发生及溶酶体的基本生物功能。","a":"的顺面膜囊中寡糖链上的甘露糖残基被磷酸化形成M6P，在高尔基体的反面膜囊和TGN膜上存在M6P的受体，这样溶酶体酶与其他蛋白区分开来，并得以浓缩，最后以出芽的方式转运到溶酶体中。功能：见上题。","src":"华东师范天学，2009年","kp":null},{"id":"jyq_ch03_32","kind":"short","q":"简述溶酶体的结构类型和溶酶体的功能。","a":"溶酶体根据其处于生理功能的不同阶段可分为初级溶酶体、次级溶酶体和残余体。初级溶酶体内容物均一，外有一层脂蛋白膜围绕，其中含多种水解酶类，次级溶酶体是初级溶酶体与细胞内的自噬菌泡或异噬菌泡、胞饮泡或吞噬泡融合形成的复合物，经过一段时间的消化后，小分子物质可通过膜上的载体蛋白转运到细胞质基质中，供细胞代谢使用，未被消化的物质残存在溶酶体即形成残余体。功能：见2008年中国科学院考试试题。","src":"浙江理工大学，2009年","kp":null},{"id":"jyq_ch03_33","kind":"short","q":"过氧化物酶体是怎样进行氧浓度调节的？有什么意义？","a":"过氧化物酶体中的氧化酶都是利用分子氧作为氧化剂，催化下面的化学反应：RH2+O2—消耗的，其余的在线粒体中消耗。在过氧化物酶体中氧化产生的能量以产热的方式消耗掉，而在线粒体中氧化产生的能量贮存在ATP中。线粒体与过氧化物酶体对氧的敏感性是不一样的，线粒体氧化所需的最佳氧浓度为2%左右，增加氧浓度，并不提高线粒体的氧化能力。过氧化物酶体与线粒体不同，它的氧化率是随氧张力增强而成正比地提高。因此，在低浓度氧的条件下，线粒体利用氧的能力比过氧化物酶体强，但在高浓度氧的情况下，过氧化物酶体的氧化反应占主导地位，这种特性使过氧化物酶体具有使细胞免受高浓度氧的毒性作用。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch03_34","kind":"short","q":"如果用碱性物质（如氨或氯奎）处理细胞，将会使细胞器中的pH升高接近中性。请预测此时M6P受体蛋白位于何种细胞器的膜中，原因是什么？","a":"用弱碱性试剂处理离体细胞，M6P受体从高尔基体的TGN上消失而仅仅存在于前溶酶体膜上。因为M6P受体在pH为7左右时与M6P结合，在pH为6以下则与M6P分离。通常情况下，M6P受体穿梭于高尔基体的TGN和前溶酶体之间，在高尔基体的TGN中性环境中M6P受体与M6P结合，运至前溶酶体（酸性环境）后M6P受体与M6P解离，并返回高尔基体。现在因为碱性物质的处理而使细胞器中的pH接近中性，则M6P受体-M6P复合物被转运至前溶酶体后无法解离，M6P受体富集在前溶酶体膜上。","src":"中山大学，2009年","kp":null},{"id":"jyq_ch03_35","kind":"short","q":"内膜系统包括哪些结构，并举例说明在功能上的相关性。","a":"细胞的内膜系统主要包括内质网、高尔基体、溶酶体、分泌泡等，它们都是由膜围绕的细胞器或细胞结构，在结构、功能乃至发生上相关的。内质网是由封闭的膜系统及其围成的腔形成相互沟通的网状结构，通常占据细胞膜系统的一半左右，在不同细胞类型之间和同一细胞的不同时期，其结构和功能也会发生变化。由于内质网的存在，大大增加了细胞内膜的表面积，为各种酶反应提供了充足的结合位点。糙面内质网上结合有大量的核糖体，是蛋白合成和加工修饰的重要场所，光面内质网则主要是脂质合成的场所。高尔基体的结构特征则是由一些排列较为整齐的扁平膜囊堆叠在一起形成的，扁囊多呈弓形，中间囊腔较窄，边缘多呈泡状。高尔基体是一种有极性的细胞器，一般靠近细胞核的一面或物质进人高尔基体的一侧为顺面，面向细胞膜的一侧为反面。高尔基体的主要功能是将内质网合成的多种蛋白进行加工、分类与包装，然后分门别类地运送到细胞特定部位或分泌出细胞，内质网合成时脂类也有部分通过高尔基体转运向细胞其他细胞器或细胞膜，此外高尔基体还是细胞内糖类合成的工厂，也是对蛋白进行糖基化修饰的重要场所之一。溶酶体是单层膜围绕、内含多种酸性水解酶的囊泡状细胞器，其主要功能是进行细胞内的消化。溶酶体在维持细胞正常代谢以及防御等方面也起着重要的作用。溶酶体内的各种酶在内质网上合成，内质网和高尔基体上进行修饰加工组装，通过高尔基体的反面膜泡转运到溶生离通询胞内体融形第七章细胞质基质与内膜系统成次级胞内体，将内吞的物质消化降解，为细胞的生长发育提供营养。分泌泡是单层膜包裹的球形结构，内含来自内质网或高尔基体的蛋白质等分子，分泌泡将这些“货物”运输到细胞膜并与细胞膜融合而将“货物”分泌到细胞外，在这种情况下分泌泡和内质网或高尔基体在发生上是连续的。分泌泡也可以由内吞方式形成，这种情况下分泌泡在发生上与细胞膜连续。分泌泡可以与溶酶体融合降解消化内吞的外来物质起着保护和营养的作用，也可以降解消化自身失去功能蛋白质，作用是保护细胞内稳态。通过分泌泡，细胞的各种膜系统联系起来。联系。【答案】高尔基体在细胞中的位置、结构、物质运输具极性，因此说高尔基体是极性细胞器。高尔基体靠近细胞核的一面，膜囊弯曲成凸面，称为形成面或顺面；面向细胞质膜的一面常呈凹面，称为成熟面或反面。高尔基体的亚显微结构分区，从顺面到反而，依次为：顺面膜囊及顺面高尔基管网状结构（CGN）、中间膜囊、反面膜囊及反面高尔基管网状结构（TGN）。各亚显微结构分区对应的功能是：①顺面膜囊及TGN：初级分选站，负责对糙面内质网上转运来的蛋白质进行鉴别；②中间膜囊：多数糖基修饰、糖脂形成以及有关的多糖合成；③反面膜囊及FGN：参与蛋白质的分类与包装，并输出高尔基体。不同膜囊有不同功能，执行功能时是粼式操作，上一道工序完成了才能进行了下一道工序。","src":"南开大学，2009年","kp":null},{"id":"jyq_ch03_36","kind":"short","q":"溶酶体酶在高尔基体复合体中被准确分拣的分子机制是什么？","a":"溶酶体酶在高尔基复合体被准确分拣是靠M6P受体蛋白完成的。溶酶体形成的M6P分选的分子机制为：具有M6P标记是溶酶体酶在高尔基体外侧网络与受体结合后，在网格蛋白帮助下形成具有网格蛋白外被的溶酶体酶分泌小泡，网格蛋白解聚后的溶酶体酶分泌小泡与具有分选作用的细胞器次级内体融合，由于次级内体内部的pH约5.5，融合后的内体中的pH低于6，所以与M6P受体结合的溶酶体与受体脱离，释放到内体中；接着，由次级内体中的磷酸酶使溶酶体酶脱磷酸，防止溶酶体酶与M6P受体重新结合。融合后的次级内体可以通过出芽形成两种类型的小泡，一种是含有溶酶体酶蛋白但不含质膜中M6P受体蛋白结合，并通过内吞作用被包装到初级内体中，然后通过与来自外侧高尔基体和溶酶体酶运输小泡相同的方式形成成熟的溶酶体。","src":"华中师范大学，2007年","kp":null},{"id":"jyq_ch03_37","kind":"short","q":"试述内质网的主要功能及其质量监控作用。","a":"答内质网是细胞内的一个精细的膜系统，是交织分布于细胞质中的膜的管道系统。两膜间是扁平的腔、囊或池。内质网分两类：一类是膜上附着核糖体颗粒的称为粗面内质网；另一类是膜上光滑的，没有核糖体附在上面，称为光面内质网。粗面内质网的功能是合成蛋白质大分子，并把它从细胞内输送出去或在细胞内转运到其他部位。凡蛋白质合成旺盛的细胞，粗面内质网便发达。在神经细胞中，粗面内质网的发达与记忆有关。光面内质网的功能与糖类和脂类的合成、解毒、同化作用有关，并且还具有运输蛋白质的功能。内质网含有一系列的酶，可对内质网上合成的蛋白质进行合成后加工，为它们形成具有正常功能的蛋白质提供物质保障；同时内质网上还包含有不同的受体蛋白，可指引这些蛋白质准确高效地到达靶部位。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_38","kind":"short","q":"溶酶体是怎样发生的？","a":"它有哪些基本功能？容溶酶体是动物细胞中一种膜结合细胞器，含有多种水解酶类，在细胞内起消化和保护作用，可与吞噬泡或胞饮泡结合，消化和利用其中的物质。也可以消化自身细胞破损的细胞器或残片，有利于细胞器的重新组装、成分的更新及废物的消除。溶酶体的发生：溶酶体酶是在糙面内质网上合成并经N-连接的糖基依物碾至谢基体在寝0尔基体的顺面膜囊中寡糖链上的甘露糖残基发生磷酸化形成M6P，在高尔基体的反面膜囊和TGN膜上存在M6P的受体，这样溶酶体的酶与其他蛋白区分开来，并得以浓缩，最后以出芽的方式转运到溶酶体中。溶酶体的功能：防御功能；作为细胞内的消化“器官”为细胞提供营养；在分泌腺细胞中，溶酶体常常含有摄人的分泌颗粒，可能参与分泌过程的调节；两栖类发育过程中蝌蚪尾巴的退化，哺乳动物断奶后乳腺的退行性变化等都涉及某些特定细胞编程性死亡及周围活细胞对其的清除，这些过程都与溶酶体有关；在受精过程中的作用，精子的顶体相当于特化的溶酶体，其中含多种水解酶类，如透明质酸酶、酸性磷酸酶、它能溶解卵细胞的外被及滤泡细胞，产生孔道，使精子进人卵细胞。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_39","kind":"short","q":"过氧化物酶体与溶酶体有哪些区别？","a":"怎样理解过氧化物酶体是异质性的细胞器？容过氧化物酶体又称微体，是由单层膜围绕的、内含一种或几种氧化酶类的细胞器。1954年Rhodin首次在鼠肾的肾小管上皮细胞中观察到这种细胞器。由于过氧化物酶体在形态大小及降解生物大分子等功能上与溶酶体类似，再加上过氧化物酶体也是一种异质性的细胞器，其确切的生理功能尚不清楚，因此人们在很长时间里把它看作某种溶酶体，直至20世纪70年代才逐渐确认过氧化物酶体是一种与溶酶体完全不同的细胞器。它普遍地存在于所有动物细胞和很多植物细胞中。早年以大鼠肝组织及种子植物的种子作为研究过氧化物酶体的实验材料。近些年来，人们从几种酵母菌及成纤维细胞中筛选出一系列过氧化物酶体缺陷突变株，进而克隆了18种之多与过氧化物酶体发生相关的基因，从而对这一细胞器的成分、功能及其发生过程有了进一步了解。尿酸氧化酶等常形成晶格状结构，因此可作为电镜下识别的主要特征。此外，这两种细胞器在成分、功能及发生方式等方面都有很大的差异，详见表7-2。表7-2过氧化物酶体与溶酶体的不同点特征溶酶体过氧化物酶体球形，哺乳动物细胞中直径多在0.15～形态大小多呈球形，直径0.2~0.5μm，无酶晶体","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_40","kind":"short","q":"25um，内常有酶晶体酶种类酸性水解酶含有氧化酶类pH5左右7左右是否需02不需要需要功能细胞内的消化作用多种功能酶在糙面内质网合成经高尔基体出芽酶在细胞质基质中合成经分裂与装配发生形成形成识别的标志酶酸性水解酶等过氧化氢酶","a":"","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_41","kind":"short","q":"蛋白质分选（proteinsorting）","a":"依靠蛋白质自身信号序列，从蛋白质起始合成部位转运到其功能发挥部位的过程。蛋白质分选不仅保证了蛋白质的正确定位，也保证了蛋白质的生物学活性。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_42","kind":"short","q":"逃离的内质网驻留蛋白通过进行回收，驻留信号序列的受体位于上。","a":"COPI包被；高尔基体CGN以及COPI和COPⅡ的小泡膜。","src":"湖北大学，2007年","kp":null},{"id":"jyq_ch03_43","kind":"short","q":"在高尔基体修饰蛋白质的过程中，糖基化修饰发生在其面，分泌泡在面。","a":"反；顺。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch03_44","kind":"mcq","q":"各种水解酶之所以能够选择性的运人溶酶体是因为它们具有（）。","o":["A. M6P标志","B. 导肽","C. 信号肽","D. 酸性序列"],"a":"A","src":"湖北大学，2008年","kp":null,"e":"溶酶体水解酶在顺面高尔基体被加上M6P标志，经M6P受体识别后定向运入溶酶体。","oe":["正确：M6P是溶酶体水解酶的分选信号，被M6P受体识别后定向运输。","错误：导肽是线粒体、叶绿体等蛋白的转运信号，与溶酶体无关。","错误：信号肽引导分泌蛋白进入内质网，不是溶酶体分选标志。","错误：酸性序列不是溶酶体酶分选的识别标志。"]},{"id":"jyq_ch03_45","kind":"mcq","q":"导肽在进行蛋白质运送时，先将被运送的蛋白质（），运送到预定区域后，蛋白质再进行）。","o":["A. 变性、复性","B. 解折叠、折叠","C. 磷酸化、去磷酸化","D. 甲基化；去甲基化"],"a":"B","src":"南开大学，2009年","kp":null,"e":"导肽引导的蛋白质在转运前需解折叠成伸展状态，跨膜后再重新折叠为有活性构象。","oe":["错误：跨膜转运需先解折叠，不是简单的变性、复性过程。","正确：导肽运输时蛋白先解折叠，进入线粒体等后再折叠成熟。","错误：磷酸化与去磷酸化不是导肽转运的主要构象变化机制。","错误：甲基化与导肽介导的蛋白跨膜运输无直接关系。"]},{"id":"jyq_ch03_46","kind":"short","q":"细胞内蛋白质合成部位及其去向如何？说明蛋白质分选的途径有哪些类型。","a":"①合成部位：在细胞基质起始，糙面内质网上合成一内质网腔一高尔基体或溶酶体一细胞膜或细胞外。在细胞基质中合成一细胞器或细胞基质特定部位。②分选类型：跨膜转运：到细胞器；门控运输：到细胞核；膜泡运输：到细胞器间；胞基质中运输。","src":"华中农业大学，2009年","kp":null},{"id":"jyq_ch03_47","kind":"short","q":"简述分泌蛋白质的合成和分泌过程。","a":"分泌蛋白质的合成是在糙面内质网上进行的，其合成和分泌过程是一个非常复杂的过程。它包括核糖体被信号肽引导与内质网膜结合；由结合在内质网膜上的核糖体合成的不断延长的多肽穿过内质网膜进入内质网腔；在内质网腔的蛋白质的糖基化；蛋白质经过高尔基复合体形成浓缩泡被运输排出细胞之外等连续过程。","src":"武汉大学，2009年","kp":null},{"id":"jyq_ch03_48","kind":"short","q":"简述胞膜的主要类型（包括有被小泡盒其他形式小泡）以及各类型的膜泡结构、运输途经与生物学功能。","a":"①网格蛋白有被小泡：由网格蛋白构成蜂巢样外层网格，由接合素蛋白构成内层网格。TGN腔内的特异性分子被浓缩进网格蛋白有被小泡，从TGN区以出芽的方式形成转运泡，网格蛋白包被脱落，有被小泡被转运至相应的靶膜并与其融合。负责从高尔基体TGN向质膜、胞内体或溶酶体和植物液泡运输，另外在受体介导的细胞内吞途径中负责将物质从质膜运往细胞质，以及从胞内体到溶酶体的运输。②COPⅡ有被小泡：由内质网膜出芽形成，由5种蛋白亚基形成。COPⅡ蛋白通过内质网跨膜蛋白识别、浓缩、转运物质，由内质网出芽形成COPⅡ有被小泡，转运至靶膜前，包被蛋白去装备。负责从内质网向高尔基体的物质运输。③COPI有被小泡。高尔基体出芽形成，由8种蛋白亚基形成。高尔基体CGN区，KDEL受体识别内质网逃逸蛋白，由高尔基体膜出芽形成COPI有被小泡，转运至内质网。负责回收、转运内质网逃逸蛋白返回内质网。","src":"武汉大学，2006年","kp":null},{"id":"jyq_ch03_49","kind":"short","q":"比较糙面内质网与光面内质网的形态结构与功能。","a":"谷内质网是由封闭的膜系统及其围成的腔形成的互相沟通的网状结构。糙面内质网多呈扁囊状，排列较为整齐，并附着有大量核糖体；光面内质网没有核糖体附着，多为分支管状，是复杂的立体结构。粗面质网是由一层单位膜围成的扁囊状内质网，其特点为在膜的外表面附着大量的颗粒样核糖体，在糙面内质网的囊腔中含有电子密度低、透明度大的内含物。糙面内质网的主要功能是：①为负责蛋白质合成的细胞器核糖体提供支架；②糙面内质网与蛋白质的粗加工和蛋白质的转运有关。蛋白质在核糖体上合成以后，进人内质网腔，在内质网腔中进行蛋白质的糖基化，然后以芽生方式从糙面内质网膜上膨出，脱落形成小囊泡，小囊泡将这些蛋白质定向地转运到高尔基复合体进一步加工修饰。虽然在大多数细胞中，光面内质网的形态相似，但其化学组成、酶的种类和含量等都有差异，因此不同类型细胞中光面内质网的功能各有不同，主要功能为：①参与脂质和胆固醇的合成与运输。脂质和胆固醇的合成是光面内质网最明显的功能。在光面内质网膜上有合成脂质分子的酶，可合成磷脂和其他脂类。光面内质网膜上合成的脂质分子可以通过芽生形成运输小泡运送到高尔基复合体，也可通过特殊的磷脂交换蛋白送往各膜性细胞器。②与糖原的合成和分解有关。肝细胞中常见光面内质网与糖原相伴而存在，肝糖原丰富时，光面内质网增多；肝糖原减少时，光面内质网减少。另有实验证明，光面内质网膜上含有葡萄糖-6－磷酸酶，此酶是糖原降解为葡萄糖的关键酶，由此说明糠分光面网有第八章蛋白质分选与膜泡运输关。③解毒作用。光面内质网上能合成分解一些脂溶性毒物的酶类，生化研究表明，光面内质网上集中着重要的氧化酶系，该酶系将药物和毒物进行解毒或转化，消除毒性。④与肌肉收缩有关。肌肉中的光面内质网即肌质网是Ca²+的贮存部位，Ca²释放可触发肌肉收缩。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_50","kind":"short","q":"指导分泌性蛋白在糙面内质网上合成需要哪些主要结构或因子？","a":"它们如何协同作用完成肽链在内质网上的合成？容分泌性蛋白信号假说：即分泌性蛋白N端序列作为信号肽，指导分泌性蛋白到内质网膜上合成。在蛋白质合成结束之前信号肽被切除。指导分泌性蛋白在rER上合成的决定因素是蛋白质N端的信号肽，信号识别颗粒和ER膜上的信号识别颗粒受体（又称停泊蛋白）等因子协助完成这一过程。三者协同作用方式如下：①共转移：protein首先在基质游离核糖体上起始合成，当多肽链延伸至80个aa左右后，N的信号序列与信号识别颗粒结合使肽链延伸暂时停止，并防止新肽N端损伤和成熟前折叠，有的信号识别颗粒与内质网膜上的偏激蛋白（SRP受体）结合，核糖体与内质网膜上的易位子结合，此后SRP脱离了信号序列和核糖体，返回细胞质基质中重复使用，肽链又开始延伸。以环化构象存在的信号肽和与易位了组分结合并使孔道打开，信号肽穿入内质网膜并引来肽链以祥环的形式进人内质网腔中，这是一个需GTP的耗能过程，与此同时，腔面上的信号肽被切除。肽链继续延伸直至完成整个多肽链的合成。这种肽链边合成边转移至内质网腔中的方式称共转移。②后转移：线粒体、叶绿体中绝大多数protein和过氧化物酶体中的protein在导肽或前导肽的指导下进人这些细胞器，这种转移方式在protein跨膜过程中不仅需要ATP使多肽去折叠，而且还需要一些protein的帮助使其能够正确地折叠成有功能的蛋白。这些蛋白基本的特征在细胞质基质中合成以后再转移到这些细胞器中，因此称后转移。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_51","kind":"short","q":"何谓蛋白质的分选？","a":"图解真核细胞内蛋白质分选途径。答绝大多数蛋白质均在细胞质基质中的核糖体上起始合成，随后在细胞质基质中，或转运至糙面内质网上继续合成。合成完成后，再通过不同的途径转运到细胞特定部位并装配成结构与功能的复合体参与细胞活动，这一过程称为蛋白质的分选或定向转运。真核细胞内蛋白质分选的途径见教材图7-21。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_52","kind":"short","q":"神经递质（neurotransmitters）","a":"是从神经细胞的特殊部分突触中释放出来的信号分子，在它们作用于靶细胞之前，突触必须同靶细胞挨得很近，这是因为递质扩散的距离有限。另外，为了引起邻近靶细胞的反应，还需产生一种电信号，所以神经递质仅作用于与之相连的靶细胞。般至少包括两个功能区域，与配体结合的区域和产生效应的区域，当受体与配体结合后，构象改变而产生活性，启动一系列过程，最终表现为生物学效应。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_53","kind":"short","q":"转位因子（translocator）","a":"靶细胞器膜上与蛋白质输人有关的蛋白通道或载体。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_54","kind":"mcq","q":"与细胞内钙离子浓度调控直接相关的信号为（）。","o":["A. DAG","B. PKC","C. CaM","D. IP3"],"a":"D","src":"湖北大学，2008年","kp":null,"e":"IP3与内质网上的IP3受体结合，促使内质网释放Ca2+，从而直接升高胞质钙浓度。","oe":["错误：DAG激活PKC，不直接调节胞质钙离子浓度。","错误：PKC是DAG和钙依赖的激酶，属效应器而非钙调控信号。","错误：CaM是钙的受体蛋白，感受钙信号而非直接调控其浓度。","正确：IP3触发内质网钙释放，直接调控胞质Ca2+浓度。"]},{"id":"jyq_ch03_55","kind":"judge","q":"大多数动物细胞中，负端走向的微管发动机蛋白是将货物运送到细胞周边，而正端走向的微管发动机蛋白将货物向细胞内部运送。","a":"错","src":"中山大学，2009年","kp":null,"e":"微管负端指向细胞中心（微管组织中心），负端走向的马达蛋白（细胞质动力蛋白）将货物运向细胞内部；正端走向的驱动蛋白把货物运向细胞周边。题干说反了，故错误。","oe":["选“对”：错误。负端走向马达蛋白实际把货物运向细胞中心而非周边，故该说法不成立。","选“错”：正确。负端走向者运向细胞内部、正端走向者运向周边，题干颠倒，故错误。"]},{"id":"jyq_ch03_56","kind":"short","q":"用能够使微管去聚合的药物处理细胞时，Golgi发生片段化，成为小的膜泡，散布在细胞中。将药物除去后，细胞恢复原状并正常生长。若用电子显微镜对这种恢复生长的细胞进行检查，可观察到Golgi非常正常，这是否意味着Golgi已经重新合成了？还是另有原因？","a":"这并不能说明高尔基体重新合成了。微管对于维持高尔基体等细胞内膜系统的形态结构具有重要作用。用微管特异性药物处理细胞,高尔基体发生片段化,很大程星粵微解异亮尔第十章细胞骨架基体的形态发生变化。移除药物后，微管重新聚合生成，使高尔基体恢复原样。要想证明高尔基体是不是重新合成，可以用放射性同位素标记或者免疫荧光标记的方法来进行尝试。","src":"中山大学，2009年","kp":null},{"id":"jyq_ch03_57","kind":"short","q":"比较微丝与微管生物学功能的异同。","a":"微管的生物学功能包括：①构成细胞内网状支架，维持细胞形状，固定与支持细胞器的位置；②与细胞器位移和细胞运动有关；③参与物质运输；④与某些信息的传递有关。微丝的功能主要是：①参与构成细胞支架，保持细胞的一定形态；②与细胞运动紧密相关，如有丝分裂时染色体移动，胞质分裂，肌肉收缩，细胞移动，胞质环流等；③常与其他细胞器连接，与细胞内运输、细胞分泌活动有关。答通过学习细胞骨架，了解微管、微丝和中间纤维的装配过程，我们可以这样认为：细胞内的复杂结构可由简单的分子组装而成，生命体是由生物大分子自装配而成。其组装过程受到细胞本身的调节，这样便于细胞在不同生理状态下调节细胞结构的组织形式，执行特定的功能。多种结构相互联系，共同完成细胞的生命活动。在自装配时受到多种因素影响，具有高度的时空顺序性。","src":"南京师范大学，2008年","kp":null},{"id":"jyq_ch03_58","kind":"short","q":"分子伴侣（molecularchaperone）","a":"是一类能够协助其他多肽进行正常折叠、组装、转运、降解的蛋白，并在DNA的复制、转录、细胞骨架功能、细胞内的信号转导等广泛的领域都发挥着重要的生理作用。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_59","kind":"fill","q":"端粒酶是有蛋白质和DNA组成的脱氧核糖核蛋白复合物。","a":"错。改：端粒酶是由蛋白质和RNA组成的脱氧核糖核蛋白复合物。","src":"华中师范大学，2007年","kp":null,"e":"端粒酶是由蛋白质和RNA组成的核糖核蛋白复合物，其RNA为端粒DNA合成提供模板，题干“蛋白质和DNA”的说法错误。","oe":["选“对”：错误。端粒酶的核酸组分是RNA而非DNA，故原说法不正确。","选“错”：正确。端粒酶是蛋白质与RNA组成的核糖核蛋白复合物（RNP），RNA提供合成端粒的模板。"]},{"id":"jyq_ch03_60","kind":"judge","q":"巴氏小体（Barrbody）存在于雄性哺育动物体上皮细胞中。","a":"错","src":"华中师范大学，2008年","kp":null,"oe":["雌性体细胞中一条X失活形成巴氏小体，有人因混淆而误选对。","巴氏小体是雌性哺乳动物体细胞中失活的X染色体，雄性仅一条X，不形成。"]},{"id":"jyq_ch03_61","kind":"mcq","q":"下面哪个有关核仁的描述是错误的（）。（南京师范大学2008年，南开大学2009年）","o":["A. 核仁的主要功能之一是参与核糖体的生物合成","B. rDNA定位于核仁区内","C. 细胞在G期，核仁消失","D. 细胞在M期末和S期重新组织核仁"],"a":"C","src":"姜益泉《辅导与习题集》","kp":null,"e":"核仁在M期消失、M末期重建并在S期活跃，与G1期无关，故C描述错误。","oe":["正确：核仁是rRNA合成和核糖体亚基组装的场所。","正确：rDNA（核仁组织者）定位于核仁区，是核仁形成的基础。","错误（答案）：核仁在M期消失，并非G1期，故该描述有误。","正确：核仁在M期末开始重建，并在S期积极组织。"]},{"id":"jyq_ch03_62","kind":"mcq","q":"细胞核内的蛋白质主要通过（)完成。","o":["A. 门控运输","B. 跨膜运输","C. 膜泡运输","D. 核膜上的核糖体合成"],"a":"A","src":"南开大学，2009年","kp":null,"e":"核内蛋白质通过核孔复合体进行门控运输，依赖核定位信号与核输入受体完成。","oe":["正确：核蛋白经核孔复合体门控转运进入细胞核。","错误：跨膜运输指穿膜转运，核蛋白不穿膜进入核内。","错误：膜泡运输用于内膜系统间的运输，不是核输入方式。","错误：核膜上的核糖体合成膜蛋白，不负责核内蛋白的输入。"]},{"id":"jyq_ch03_63","kind":"mcq","q":"果蝇幼虫唾液腺细胞中，多线染色体的膨泡显示的是（）。","o":["A. 重复序列的DNA复制","B. RNA转录","C. 合成分泌性蛋白质","D. 大量合成卵黄蛋白"],"a":"B","src":"南京师范大学，2008年","kp":null,"e":"多线染色体膨泡是染色质解螺旋、进行活跃RNA转录的区域。","oe":["错误：膨泡反映转录活跃，不是DNA复制。","正确：膨泡为染色质疏松解螺旋区，进行旺盛的RNA转录。","错误：膨泡的转录产物并非专门合成分泌性蛋白质。","错误：卵黄蛋白由特定基因表达，膨泡并非其专有标志。"]},{"id":"jyq_ch03_64","kind":"mcq","q":"如果将双线期灯刷染色体在放射性标记的尿嘧啶中培养，然后通过放射自显影进行检测，大部分的放射性将出现在（）。","o":["A. 灯刷环与灯刷骨架","B. 灯刷环上","C. 沿着灯刷骨架","D. 与染色体无关"],"a":"B","src":"南开大学，2009年","kp":null,"e":"灯刷染色体的侧环是解螺旋并活跃转录的DNA，故放射性尿嘧啶主要出现在灯刷环上。","oe":["错误：放射性集中在转录活跃的环上，而非环与骨架均匀分布。","正确：灯刷环是活跃转录区，掺入3H-尿嘧啶最多。","错误：染色体骨架（轴）转录不活跃，标记较少。","错误：标记来自转录掺入，确实与染色体相关。"]},{"id":"jyq_ch03_65","kind":"mcq","q":"以下哪些结构不是每条染色体均具有的（）。","o":["A. 着丝粒与着丝点","B. 端粒与染色体臂","C. 端粒与主缢痕","D. 次缢痕与随体E.核仁组织者与随体F.D+E"],"a":"","src":"南京师范大学，2008年","kp":null,"e":"着丝粒、端粒、染色体臂每条染色体都有；次缢痕、随体、核仁组织者仅见于部分染色体，故选F（D+E）。","oe":["每条染色体都有着丝粒与着丝点，是必需结构，故不选A。","每条染色体都有端粒与染色体臂，属基本结构，故不选B。","主缢痕即着丝粒区，每条染色体都有，端粒也普遍存在，不选C。","正确：次缢痕、随体与核仁组织者并非每条染色体都有，故D+E即F正确。"]},{"id":"jyq_ch03_66","kind":"short","q":"试述核小体的结构要点及其实验证据。","a":"核小体结构要点是：①每个核小体单位包括200bp左右的DNA超螺旋和一个组蛋白八聚体及一个分子H1；②组蛋白八聚体构成核小体的盘状核心结构；③146bp的DNA分子超螺旋盘绕组蛋白八聚体1.75圈，组蛋白H1在核心颗粒外结合额外20bpDNA，锁住核小体DNA的进出端，起稳定核小体的作用。包括组蛋白H1和166bpDNA的核小体结构又称染色质小体；4两个相邻核小体之间以连接DNA相连，典型长度60bp，不同物种变化值为0~80bp；5组蛋白与DNA之间的相互作用主要是结构性的，基本不依赖于核苷酸的特异序列，实验表明，核小体具有自组装的性质；6核小体沿DNA的定位受不同因素的影响，进而通过核小体相位改变影响基因表达。核小体的主要实验证据有：①铺展染色质的电镜观察，未经处理的染色质自然结构为30nm的纤丝，经盐溶液处理后解聚的染色质呈现10nm串珠状结构；②用非特异性微球菌核酸酶消化染色质，部分酶解片段分析结果；③应用X射线衍射、中子散射和电镜三维重建技术研究，发现核小体颗粒是直径为11nm、高","src":"华中师范大学，2008年","kp":null},{"id":"jyq_ch03_67","kind":"short","q":"分泌性蛋白质首先在合成，当肽链延长到80个氨基酸左右时，信号肽与结合，肽链延长暂时停止。","a":"游离核糖体；SRP颗粒。","src":"湖北大学，2007年","kp":null},{"id":"jyq_ch03_68","kind":"mcq","q":"真核细胞中下列哪种细胞器或细胞结构上不可能有多核糖体存在（）。","o":["A. 内质网","B. 细胞质基质","C. 细胞核膜","D. 细胞质膜"],"a":"D","src":"南京师范大学，2009年","kp":null,"e":"核糖体可附着在内质网、细胞质基质和核膜外表面，但不能存在于细胞质膜上，故D不可能。","oe":["错误：糙面内质网表面附着多核糖体，可合成蛋白质。","错误：细胞质基质中存在游离多核糖体，合成胞内蛋白。","错误：核膜外膜与内质网相连，可附着核糖体。","正确：细胞质膜上无核糖体，故不可能存在多核糖体。"]},{"id":"jyq_ch03_69","kind":"short","q":"概述依赖泛化的蛋白质降解途径及其分子机制。","a":"泛素系统（UPS）广泛存在于真核生物中，是精细的特异性的蛋白质降解系统。它由泛素、26S蛋白酶体、多种酶（如E1、E2、E3、去泛素酶）构成。在泛素系统中，泛素（Ubiquitin，Ub）是一种序列保守的小分子蛋白，蛋白质与泛素结合后，被蛋白酶体以ATP依赖的方式降解。E1、E2酶分别称为泛素活化酶和泛素载体酶，使泛素通过Ub-腺苷酸中间产物形成E2-Ub疏基酯。泛素连接酶E3负责连接泛素和特异性的底物，这样泛素化的底物可以被26S蛋白酶体降解为若干肽段。泛素系统通过特异性的降解蛋白质，调节细胞分化、免疫反应，参与转录、离子通道、分泌的调控及神经元网络、细胞器的形成等等，泛素系统还与人类某些疾病有关。蛋白质的泛素化降解途径的主要步骤：①识别被降解的靶蛋白；②多个泛素分子共价结合到蛋白质底物上，形成多泛素链；③通过26S的蛋白酶体复合物降解靶蛋白，同时释放游离的、可重新利用的泛素分子。目前发现参与泛素化反应的酶有E1，E2，E3这三类：E1即泛素活化酶（Ubactivatingenzyme），在ATP的参与下，E1以其活性位点半胱氨酸的疏基与泛素的C末端生成高能硫酯键，使泛素活移到底物上。另外，核糖体上还有许多与起始因子、延伸因子、释放因子以及多种酶相结合的部位。","src":"武汉大学，2007年","kp":null},{"id":"jyq_ch03_70","kind":"short","q":"质粒（plasmid）","a":"细菌核区DNA以外的，可进行自主复制的遗传因子，称为质粒。质粒是裸露的环状DNA分子，所含遗传信息量为2～200个基因，能进行自我复制，有时能整合到核DNA中去。质粒DNA在遗传工程研究中很重要，常用作基因重组与基因转移的载体。","src":"姜益泉《辅导与习题集》","kp":null},{"id":"jyq_ch03_71","kind":"short","q":"测定细胞周期各期的时间，可采用3H-TdR脉冲标记法，利用放射自显影方法，统计占总细胞的百分数加以测定。","a":"带标记的分裂期细胞。","src":"南京师范大学，2009年","kp":null},{"id":"jyq_ch03_72","kind":"short","q":"奢侈蛋白（luxuryprotein）","a":"特异性的蛋白如红细胞的血红蛋白、肌细胞的收缩蛋白，这类蛋白对细胞自身生存并无直接影响，却是细胞向特殊类型分化的物质基础，故称为奢侈蛋白，由奢侈基因所控制。","src":"姜益泉《辅导与习题集》","kp":null}],"outline":["内膜系统概览","内质网(合成/修饰/质控)","高尔基体(加工/分选)","溶酶体(消化)","过氧化物酶体"],"outlineMap":[0,1,0,2,0]};